# --- RECURSOS DA VERSÃO 2.1 ---
def valor_float(valor, padrao=0.0):
    try:
        return float(valor)
    except (TypeError, ValueError):
        return float(padrao)


def valor_bool(valor):
    if isinstance(valor, bool):
        return valor
    if isinstance(valor, (int, float)):
        return bool(valor)
    return str(valor or "").strip().casefold() in {"1", "true", "sim", "yes", "ok", "pago", "aprovado", "entregue"}



# --- 20.4.9-I8.11: Perfil Comercial do Cliente ---
I811_MODALIDADE_NORMAL = "Por proposta"
I811_MODALIDADE_MENSAL = "Faturamento mensal"


def perfil_comercial_cliente(cliente):
    """Normaliza o perfil comercial sem inventar condições para cadastros antigos."""
    cliente = cliente or {}
    perfil = cliente.get("perfil_comercial", {}) if isinstance(cliente.get("perfil_comercial", {}), dict) else {}
    regras = perfil.get("abatimentos_produto", []) if isinstance(perfil.get("abatimentos_produto", []), list) else []
    return {
        "faturamento_mensal": bool(perfil.get("faturamento_mensal", False)),
        "dia_fechamento": int(perfil.get("dia_fechamento", 1) or 1),
        "dia_vencimento": int(perfil.get("dia_vencimento", 10) or 10),
        "observacao_faturamento": str(perfil.get("observacao_faturamento", "") or "").strip(),
        "abatimentos_produto": [r for r in regras if isinstance(r, dict)],
    }


def proposta_faturamento_mensal(prop):
    """Alias da fonte única de status (I8.11.1-HF3)."""
    return _status_proposta_mensal(prop)


def _i811_digitos(valor):
    return re.sub(r"\D", "", str(valor or ""))


def localizar_cliente_comercial(nome="", documento="", whatsapp=""):
    """Localiza o cadastro mestre para aplicar a regra comercial correta na proposta."""
    clientes = carregar_clientes()
    doc = _i811_digitos(documento)
    wa = _telefone_chave(whatsapp)
    nome_norm = normalizar_texto_cliente(nome).casefold()
    if doc:
        achado = next((c for c in clientes if _i811_digitos(c.get("documento")) == doc), None)
        if achado:
            return achado
    if wa:
        achado = next((c for c in clientes if _telefone_chave(c.get("whatsapp")) == wa), None)
        if achado:
            return achado
    if nome_norm:
        return next((c for c in clientes if normalizar_texto_cliente(c.get("nome")).casefold() == nome_norm), None)
    return None


def autopreencher_cliente_whatsapp_i8111():
    """Reconhece cliente cadastrado pelo WhatsApp no formulário do Jorge.

    O callback roda antes do rerun do Streamlit, então os demais campos podem
    ser preenchidos com segurança antes da criação dos widgets no novo ciclo.
    A Anna não usa este fluxo nesta versão; sua extensão depende de homologação.
    """
    whatsapp = str(st.session_state.get("form_whatsapp", "") or "").strip()
    digitos = _telefone_chave(whatsapp)
    if len(digitos) < 8:
        st.session_state.pop("_i8111_cliente_reconhecido_id", None)
        st.session_state.pop("_i8111_cliente_reconhecido_msg", None)
        return
    cliente = localizar_cliente_comercial(whatsapp=whatsapp)
    if not cliente:
        st.session_state.pop("_i8111_cliente_reconhecido_id", None)
        st.session_state["_i8111_cliente_reconhecido_msg"] = "nao_encontrado"
        return
    st.session_state["form_cliente"] = str(cliente.get("nome", "") or "").strip()
    st.session_state["form_documento"] = str(cliente.get("documento", "") or "").strip()
    # Não reescreve a própria chave form_whatsapp dentro do callback que foi
    # disparado por ela; preserva exatamente o número confirmado pelo usuário.
    st.session_state["_i8111_cliente_reconhecido_id"] = cliente.get("id", "")
    st.session_state["_i8111_cliente_reconhecido_msg"] = "encontrado"


def autopreencher_cliente_whatsapp_anna_i811hf2():
    """HF2: espelha no modal da Anna a identificação por WhatsApp homologada no Jorge.

    Mantém chaves próprias do modal para não interferir no formulário principal.
    O callback apenas lê o cadastro mestre e preenche identificação do cliente;
    nenhuma condição comercial é criada ou alterada aqui.
    """
    whatsapp = str(st.session_state.get("anna_modal_whatsapp", "") or "").strip()
    digitos = _telefone_chave(whatsapp)
    if len(digitos) < 8:
        st.session_state.pop("_i811hf2_anna_cliente_reconhecido_id", None)
        st.session_state.pop("_i811hf2_anna_cliente_reconhecido_msg", None)
        return
    cliente = localizar_cliente_comercial(whatsapp=whatsapp)
    if not cliente:
        st.session_state.pop("_i811hf2_anna_cliente_reconhecido_id", None)
        st.session_state["_i811hf2_anna_cliente_reconhecido_msg"] = "nao_encontrado"
        return
    st.session_state["anna_modal_cliente"] = str(cliente.get("nome", "") or "").strip()
    st.session_state["anna_modal_documento"] = str(cliente.get("documento", "") or "").strip()
    # Preserva exatamente o número confirmado pela Anna no campo que disparou o callback.
    st.session_state["_i811hf2_anna_cliente_reconhecido_id"] = cliente.get("id", "")
    st.session_state["_i811hf2_anna_cliente_reconhecido_msg"] = "encontrado"


def resumo_cliente_reconhecido_i8111(cliente):
    if not cliente:
        return ""
    partes = []
    cidade = str(cliente.get("cidade", "") or "").strip()
    if cidade:
        partes.append(cidade)
    classificacao = str(cliente.get("classificacao_relacionamento", "") or "").strip()
    if classificacao:
        partes.append(classificacao)
    perfil = resumo_perfil_comercial(cliente)
    if perfil.get("faturamento_mensal"):
        partes.append(f"mensalista · fecha dia {perfil.get('dia_fechamento')} · vence dia {perfil.get('dia_vencimento')}")
    if perfil.get("qtd_regras_ativas"):
        partes.append(f"{perfil.get('qtd_regras_ativas')} preço(s) especial(is)")
    return " · ".join(partes)


def _i811_data_regra(valor):
    texto = str(valor or "").strip()
    if not texto:
        return None
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(texto[:10], fmt).date()
        except (TypeError, ValueError):
            pass
    return None


def _i811_preco_catalogo_float(produto):
    texto = str((produto or {}).get("Preco", (produto or {}).get("preco", "")) or "").replace("R$", "").strip()
    if not texto:
        return 0.0
    try:
        return float(texto.replace(".", "").replace(",", ".")) if "," in texto else float(texto)
    except (TypeError, ValueError):
        return 0.0


def regra_abatimento_cliente(cliente, produto_nome, referencia=None):
    """Retorna a regra ativa do produto. O desconto é sempre valor absoluto em reais."""
    if not cliente or not str(produto_nome or "").strip():
        return None
    perfil = perfil_comercial_cliente(cliente)
    referencia = referencia or hoje_local()
    catalogo = carregar_catalogo()
    oficial = nome_produto_oficial_catalogo(produto_nome, catalogo)
    chave = normalizar_identidade_produto(oficial)
    for regra in perfil.get("abatimentos_produto", []):
        if not valor_bool(regra.get("ativo", True)):
            continue
        if normalizar_identidade_produto(regra.get("produto")) != chave:
            continue
        inicio = _i811_data_regra(regra.get("validade_inicio"))
        fim = _i811_data_regra(regra.get("validade_fim"))
        if inicio and referencia < inicio:
            continue
        if fim and referencia > fim:
            continue
        abatimento = max(valor_float(regra.get("abatimento", 0)), 0.0)
        if abatimento <= 0:
            continue
        return {**regra, "produto": oficial, "abatimento": abatimento}
    return None


def calcular_preco_cliente_item(cliente, produto_nome, valor_digitado=0.0):
    """Calcula preço especial sem alterar o Catálogo Oficial.

    Base preferencial = preço oficial atual. Se o produto não puder ser resolvido,
    não aplicamos automaticamente uma regra especial para evitar desconto no item errado.
    """
    regra = regra_abatimento_cliente(cliente, produto_nome)
    if not regra:
        return None
    catalogo = carregar_catalogo()
    _, produto = _produto_catalogo_da_proposta(produto_nome, catalogo)
    if not produto:
        return None
    base = _i811_preco_catalogo_float(produto)
    if base <= 0:
        base = max(valor_float(valor_digitado), 0.0)
    if base <= 0:
        return None
    abatimento = max(valor_float(regra.get("abatimento")), 0.0)
    if abatimento > base:
        return {
            "produto_oficial": str(produto.get("Nome") or regra.get("produto") or produto_nome),
            "preco_base": base,
            "abatimento": abatimento,
            "preco_final": None,
            "bloqueado": True,
            "mensagem": "O abatimento cadastrado é maior que o preço oficial atual. Revise o Perfil Comercial antes de gerar a proposta.",
            "regra": regra,
        }
    final = base - abatimento
    return {
        "produto_oficial": str(produto.get("Nome") or regra.get("produto") or produto_nome),
        "preco_base": base,
        "abatimento": abatimento,
        "preco_final": final,
        "bloqueado": False,
        "regra": regra,
    }


def resumo_perfil_comercial(cliente):
    perfil = perfil_comercial_cliente(cliente)
    regras_ativas = [r for r in perfil.get("abatimentos_produto", []) if valor_bool(r.get("ativo", True)) and valor_float(r.get("abatimento")) > 0]
    return {
        **perfil,
        "regras_ativas": regras_ativas,
        "qtd_regras_ativas": len(regras_ativas),
        "modalidade": I811_MODALIDADE_MENSAL if perfil.get("faturamento_mensal") else I811_MODALIDADE_NORMAL,
    }


def proposta_encerrada(prop):
    """Fonte única compartilhada com Alpha Core, THU e painéis."""
    return _status_proposta_encerrada(prop)


def proposta_concluida(prop):
    """Fonte única compartilhada com Alpha Core, THU e painéis."""
    return _status_proposta_concluida(prop)


def proposta_ativa_operacional(prop):
    """Fonte única para listas e contadores operacionais da Anna, Jorge e THU."""
    return _status_proposta_ativa(prop)


def diagnosticar_sincronizacao_status(historico):
    """HF3: compara a antiga regra fixa com a fonte única atual.

    Serve somente como diagnóstico executivo; não altera nenhuma proposta.
    """
    divergencias = []
    contradicoes = []
    for prop in (historico or []):
        if not isinstance(prop, dict):
            continue
        numero = str(prop.get("numero_proposta") or "SEM-NÚMERO")
        cliente = str(prop.get("cliente_nome") or prop.get("cliente") or "Cliente")
        aprovado = valor_bool(prop.get("aprovado"))
        pago = valor_bool(prop.get("pago"))
        entregue = valor_bool(prop.get("entregue"))
        legado_concluido = aprovado and pago and entregue
        oficial_concluido = proposta_concluida(prop)
        if legado_concluido != oficial_concluido:
            divergencias.append({
                "Proposta": numero,
                "Cliente": cliente,
                "Cobrança": "Mensal" if proposta_faturamento_mensal(prop) else "Por proposta",
                "Aprovado": "Sim" if aprovado else "Não",
                "Pago": "Sim" if pago else "Não",
                "Entregue": "Sim" if entregue else "Não",
                "Regra oficial": "Concluída" if oficial_concluido else "Ativa",
            })
        if entregue and not aprovado:
            contradicoes.append({"Proposta": numero, "Cliente": cliente, "Problema": "Entregue sem aprovação"})
        if pago and not aprovado:
            contradicoes.append({"Proposta": numero, "Cliente": cliente, "Problema": "Pago sem aprovação"})
    return {
        "avaliadas": len([p for p in (historico or []) if isinstance(p, dict)]),
        "divergencias_legadas": divergencias,
        "contradicoes": contradicoes,
    }


def calcular_valores_proposta(prop):
    itens = prop.get("itens", []) or []
    subtotal = sum(valor_float(i.get("quantidade")) * valor_float(i.get("valor_unitario")) for i in itens)
    desconto = valor_float(prop.get("desconto", prop.get("desconto_valor", 0)))
    taxa_entrega = valor_float(prop.get("taxa_entrega", 0))
    total = prop.get("valor_total", prop.get("total"))
    total_calculado = max(subtotal - desconto, 0) + taxa_entrega
    total = valor_float(total, total_calculado) if total is not None else total_calculado
    return subtotal, desconto, total



def _data_resultado(valor):
    """Normaliza datas usadas em indicadores financeiros/comerciais."""
    if isinstance(valor, datetime):
        return valor.date()
    if isinstance(valor, date):
        return valor
    texto = str(valor or "").strip()
    if not texto:
        return None
    candidatos = (texto, texto[:19], texto[:10])
    formatos = (
        "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M", "%d/%m/%Y",
        "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d",
    )
    for candidato in candidatos:
        for formato in formatos:
            try:
                return datetime.strptime(candidato, formato).date()
            except (TypeError, ValueError):
                pass
    try:
        return datetime.fromisoformat(texto.replace("Z", "+00:00")).date()
    except (TypeError, ValueError):
        return None


def _data_evento_resultado(proposta, campos_principais, campos_legado=()):
    """Retorna (data, campo_usado, usou_fallback_legado)."""
    for campo in campos_principais:
        d = _data_resultado(proposta.get(campo))
        if d:
            return d, campo, False
    for campo in campos_legado:
        d = _data_resultado(proposta.get(campo))
        if d:
            return d, campo, True
    return None, "", False


def calcular_resultados_oficiais(historico, referencia=None):
    """20.4.9-G — fonte única dos resultados financeiros/comerciais.

    Regras:
    - Total orçado: tudo que foi efetivamente registrado como proposta.
    - Total aprovado: propostas aprovadas e não encerradas/canceladas.
    - Recebido: propostas pagas e não encerradas/canceladas.
    - A receber: aprovadas, não pagas e não encerradas/canceladas.
    - Indicadores 'hoje' usam a data do evento (aprovação/pagamento/entrega);
      registros legados sem data do evento são auditados, mas não têm a data adivinhada.
    """
    referencia = referencia or hoje_local()
    propostas = [p for p in (historico or []) if isinstance(p, dict)]
    validas = [p for p in propostas if not proposta_encerrada(p)]
    aprovadas = [p for p in validas if valor_bool(p.get("aprovado"))]
    pagas = [p for p in validas if valor_bool(p.get("pago"))]
    mensais_a_faturar = [p for p in aprovadas if proposta_faturamento_mensal(p) and not valor_bool(p.get("pago"))]
    a_receber = [p for p in aprovadas if not proposta_faturamento_mensal(p) and not valor_bool(p.get("pago"))]

    def total_lista(lista):
        return sum(calcular_valores_proposta(p)[2] for p in lista)

    criadas_hoje = []
    propostas_mes = []
    inicio_mes = referencia.replace(day=1)
    for p in propostas:
        d, _, _ = _data_evento_resultado(
            p,
            ("data_geracao", "data", "criado_em", "created_at"),
        )
        if d == referencia:
            criadas_hoje.append(p)
        if d and inicio_mes <= d <= referencia:
            propostas_mes.append(p)

    aprovadas_hoje = []
    pagas_hoje = []
    entregues_hoje = []
    fallback_eventos = {"aprovacao": 0, "pagamento": 0, "entrega": 0}

    for p in aprovadas:
        d, _, _ = _data_evento_resultado(
            p,
            ("aprovado_em", "data_aprovacao"),
        )
        if d == referencia:
            aprovadas_hoje.append(p)
        if d is None:
            fallback_eventos["aprovacao"] += 1

    for p in pagas:
        d, _, _ = _data_evento_resultado(
            p,
            ("pago_em", "data_pagamento"),
        )
        if d == referencia:
            pagas_hoje.append(p)
        if d is None:
            fallback_eventos["pagamento"] += 1

    entregues_validas = [p for p in validas if valor_bool(p.get("entregue"))]
    for p in entregues_validas:
        d, _, _ = _data_evento_resultado(
            p,
            ("entregue_em", "data_entrega_real"),
        )
        if d == referencia:
            entregues_hoje.append(p)
        if d is None:
            fallback_eventos["entrega"] += 1

    aprovadas_mes = [p for p in propostas_mes if (not proposta_encerrada(p)) and valor_bool(p.get("aprovado"))]

    return {
        "referencia": referencia,
        "propostas_total": len(propostas),
        "propostas_validas": len(validas),
        "propostas_encerradas": len(propostas) - len(validas),
        "aprovadas_total": len(aprovadas),
        "pagas_total": len(pagas),
        "a_receber_total_qtd": len(a_receber),
        "mensais_a_faturar_qtd": len(mensais_a_faturar),
        "total_orcado": total_lista(propostas),
        "total_orcado_valido": total_lista(validas),
        "total_aprovado": total_lista(aprovadas),
        "total_recebido": total_lista(pagas),
        "a_receber": total_lista(a_receber),
        "mensais_a_faturar": total_lista(mensais_a_faturar),
        "orcado_hoje": total_lista(criadas_hoje),
        "confirmado_hoje": total_lista(aprovadas_hoje),
        "recebido_hoje": total_lista(pagas_hoje),
        "entregues_hoje": len(entregues_hoje),
        "propostas_mes": propostas_mes,
        "aprovadas_mes": aprovadas_mes,
        "total_mes": total_lista(propostas_mes),
        "confirmado_mes": total_lista(aprovadas_mes),
        "ticket_medio": (total_lista(propostas) / len(propostas)) if propostas else 0.0,
        "ticket_aprovado_mes": (total_lista(aprovadas_mes) / len(aprovadas_mes)) if aprovadas_mes else 0.0,
        "conversao_mes": (len(aprovadas_mes) / len(propostas_mes) * 100.0) if propostas_mes else 0.0,
        "fallback_eventos": fallback_eventos,
        "_listas": {
            "propostas": propostas,
            "validas": validas,
            "aprovadas": aprovadas,
            "pagas": pagas,
            "a_receber": a_receber,
            "mensais_a_faturar": mensais_a_faturar,
            "criadas_hoje": criadas_hoje,
            "aprovadas_hoje": aprovadas_hoje,
            "pagas_hoje": pagas_hoje,
            "entregues_hoje": entregues_hoje,
        },
    }


def auditar_integridade_resultados(historico):
    """Audita inconsistências que podem fazer telas exibirem resultados estranhos."""
    propostas = [p for p in (historico or []) if isinstance(p, dict)]
    achados = []

    numeros = {}
    for indice, p in enumerate(propostas):
        numero = str(p.get("numero_proposta") or "").strip()
        if numero:
            numeros.setdefault(numero, []).append(indice)
        else:
            achados.append({
                "nivel": "Atenção",
                "proposta": f"registro {indice + 1}",
                "problema": "Proposta sem número identificador",
            })

        aprovado = valor_bool(p.get("aprovado"))
        pago = valor_bool(p.get("pago"))
        entregue = valor_bool(p.get("entregue"))

        if pago and not aprovado:
            achados.append({
                "nivel": "Crítico",
                "proposta": numero or f"registro {indice + 1}",
                "problema": "Marcada como paga, mas não aprovada",
            })
        if entregue and not aprovado:
            achados.append({
                "nivel": "Crítico",
                "proposta": numero or f"registro {indice + 1}",
                "problema": "Marcada como entregue, mas não aprovada",
            })
        if entregue and not pago and not proposta_faturamento_mensal(p):
            achados.append({
                "nivel": "Atenção",
                "proposta": numero or f"registro {indice + 1}",
                "problema": "Entregue, mas pagamento ainda não está marcado",
            })

        if aprovado and not (_data_resultado(p.get("aprovado_em")) or _data_resultado(p.get("data_aprovacao"))):
            achados.append({
                "nivel": "Legado",
                "proposta": numero or f"registro {indice + 1}",
                "problema": "Aprovação sem data própria; indicador diário usa fallback",
            })
        if pago and not (_data_resultado(p.get("pago_em")) or _data_resultado(p.get("data_pagamento"))):
            achados.append({
                "nivel": "Legado",
                "proposta": numero or f"registro {indice + 1}",
                "problema": "Pagamento sem data própria; indicador diário usa fallback",
            })
        if entregue and not (_data_resultado(p.get("entregue_em")) or _data_resultado(p.get("data_entrega_real"))):
            achados.append({
                "nivel": "Legado",
                "proposta": numero or f"registro {indice + 1}",
                "problema": "Entrega concluída sem data própria; indicador diário usa fallback",
            })

        itens = p.get("itens", []) or []
        subtotal_calc = sum(
            valor_float(i.get("quantidade")) * valor_float(i.get("valor_unitario"))
            for i in itens if isinstance(i, dict)
        )
        desconto = valor_float(p.get("desconto", p.get("desconto_valor", 0)))
        taxa = valor_float(p.get("taxa_entrega", 0))
        total_calc = max(subtotal_calc - desconto, 0) + taxa
        total_salvo = p.get("valor_total", p.get("total"))
        if total_salvo is not None:
            total_salvo_num = valor_float(total_salvo, total_calc)
            if abs(total_salvo_num - total_calc) > 0.01:
                achados.append({
                    "nivel": "Atenção",
                    "proposta": numero or f"registro {indice + 1}",
                    "problema": f"Total salvo ({total_salvo_num:.2f}) difere do cálculo dos itens ({total_calc:.2f})",
                })

    for numero, indices in numeros.items():
        if len(indices) > 1:
            achados.append({
                "nivel": "Crítico",
                "proposta": numero,
                "problema": f"Número de proposta duplicado em {len(indices)} registros",
            })

    ordem = {"Crítico": 0, "Atenção": 1, "Legado": 2}
    achados.sort(key=lambda x: (ordem.get(x["nivel"], 9), str(x["proposta"])))
    return achados


def renderizar_auditoria_resultados(historico, resultados=None):
    resultados = resultados or calcular_resultados_oficiais(historico)
    achados = auditar_integridade_resultados(historico)

    st.markdown("### 🔎 Auditoria de Resultados")
    st.caption(
        "Central, Painel Executivo e Relatórios passam a consultar a mesma regra oficial "
        "para indicadores equivalentes. A auditoria abaixo verifica a qualidade dos dados que alimentam essas telas."
    )

    a1, a2, a3, a4 = st.columns(4)
    a1.metric("Propostas auditadas", resultados["propostas_total"])
    a2.metric("Aprovadas válidas", resultados["aprovadas_total"])
    a3.metric("Pagas válidas", resultados["pagas_total"])
    a4.metric("Achados", len(achados))

    st.markdown("##### Regras oficiais que devem coincidir entre telas")
    regras = pd.DataFrame([
        {
            "Indicador": "A receber",
            "Regra": "Aprovada + não paga + não encerrada/cancelada",
            "Valor oficial": f"R$ {resultados['a_receber']:,.2f}".replace(",", "X").replace(".", ",").replace("X", "."),
        },
        {
            "Indicador": "Recebido total",
            "Regra": "Paga + não encerrada/cancelada",
            "Valor oficial": f"R$ {resultados['total_recebido']:,.2f}".replace(",", "X").replace(".", ",").replace("X", "."),
        },
        {
            "Indicador": "Orçado hoje",
            "Regra": "Proposta criada hoje",
            "Valor oficial": f"R$ {resultados['orcado_hoje']:,.2f}".replace(",", "X").replace(".", ",").replace("X", "."),
        },
        {
            "Indicador": "Confirmado hoje",
            "Regra": "Aprovação registrada hoje",
            "Valor oficial": f"R$ {resultados['confirmado_hoje']:,.2f}".replace(",", "X").replace(".", ",").replace("X", "."),
        },
        {
            "Indicador": "Recebido hoje",
            "Regra": "Pagamento registrado hoje",
            "Valor oficial": f"R$ {resultados['recebido_hoje']:,.2f}".replace(",", "X").replace(".", ",").replace("X", "."),
        },
    ])
    st.dataframe(regras, use_container_width=True, hide_index=True)

    fallback = resultados.get("fallback_eventos", {})
    total_fallback = sum(int(v or 0) for v in fallback.values())
    if total_fallback:
        st.warning(
            "Existem registros antigos sem data específica do evento. Eles não são adivinhados nos indicadores do dia. "
            f"Sem data — aprovação: {fallback.get('aprovacao', 0)}, "
            f"pagamento: {fallback.get('pagamento', 0)}, entrega: {fallback.get('entrega', 0)}."
        )
    else:
        st.success("Datas de aprovação, pagamento e entrega estão consistentes para os registros auditados.")

    if not achados:
        st.success("Nenhuma inconsistência estrutural encontrada nos resultados.")
    else:
        criticos = sum(1 for a in achados if a["nivel"] == "Crítico")
        atencao = sum(1 for a in achados if a["nivel"] == "Atenção")
        legado = sum(1 for a in achados if a["nivel"] == "Legado")
        st.caption(f"Críticos: {criticos} • Atenção: {atencao} • Legados: {legado}")
        st.dataframe(pd.DataFrame(achados[:100]), use_container_width=True, hide_index=True)
        if len(achados) > 100:
            st.caption(f"Mostrando 100 de {len(achados)} achados.")


def atualizar_proposta(numero_original, dados_atualizados):
    historico = carregar_historico()
    for indice, proposta in enumerate(historico):
        if proposta.get("numero_proposta") == numero_original:
            historico[indice] = dados_atualizados
            salvar_historico_completo(historico)
            return True
    return False


def carregar_proposta_no_formulario(prop_atual, duplicar=False):
    """Agenda o carregamento para o próximo rerun.

    No Streamlit, uma chave ligada a um widget não pode ser alterada depois que
    o widget já foi criado no mesmo ciclo. Por isso, guardamos os dados em uma
    chave temporária e aplicamos antes da criação dos campos no próximo rerun.
    """
    st.session_state._proposta_pendente_formulario = {
        "prop": dict(prop_atual),
        "duplicar": bool(duplicar),
    }


def aplicar_proposta_pendente_no_formulario():
    pendente = st.session_state.pop("_proposta_pendente_formulario", None)
    if not pendente:
        return

    prop = pendente.get("prop", {}) or {}
    duplicar = bool(pendente.get("duplicar", False))

    st.session_state.temp_itens = [dict(item) for item in prop.get("itens", []) or []]
    st.session_state.form_cliente = prop.get("cliente_nome", prop.get("cliente", ""))
    st.session_state.form_documento = prop.get("documento", prop.get("cliente_cpf_cnpj", ""))
    st.session_state.form_whatsapp = prop.get("whatsapp", prop.get("cliente_wa", ""))
    st.session_state.form_evento = str(prop.get("evento", ""))
    st.session_state.form_desconto = valor_float(prop.get("desconto", prop.get("desconto_valor", 0)))
    st.session_state.form_prazo = str(prop.get("prazo_dias", "10"))
    frete_salvo = str(prop.get("frete_tipo", "Retirada")).strip()
    st.session_state.form_frete = "Entrega" if "entrega" in frete_salvo.casefold() and "retirada" not in frete_salvo.casefold() else "Retirada"
    st.session_state.form_taxa_entrega = valor_float(prop.get("taxa_entrega", 0))
    st.session_state.form_validade = str(prop.get("validade_dias", "5"))
    try:
        st.session_state.form_entrega = datetime.strptime(
            str(prop.get("data_entrega", "")), "%d/%m/%Y"
        ).date()
    except (TypeError, ValueError):
        st.session_state.form_entrega = hoje_local()

    st.session_state.editar_numero = None if duplicar else prop.get("numero_proposta")
    st.session_state.form_key += 1


def agendar_limpeza_formulario():
    """Limpa o formulário no próximo rerun, antes da criação dos widgets."""
    st.session_state._limpar_formulario_pendente = True


def aplicar_limpeza_formulario_pendente():
    if not st.session_state.pop("_limpar_formulario_pendente", False):
        return

    st.session_state.temp_itens = []
    st.session_state.editar_numero = None
    st.session_state.form_cliente = ""
    st.session_state.form_documento = ""
    st.session_state.form_whatsapp = ""
    st.session_state.form_evento = ""
    st.session_state.form_desconto = 0.0
    st.session_state.form_entrega = hoje_local()
    st.session_state.form_prazo = "10"
    st.session_state.form_frete = "Retirada"
    st.session_state.form_taxa_entrega = 0.0
    st.session_state.form_validade = "5"
    st.session_state.form_key += 1


def remover_item_temp(indice, aba_destino=None):
    if 0 <= indice < len(st.session_state.temp_itens):
        st.session_state.temp_itens.pop(indice)
        if aba_destino:
            rerun_na_aba(aba_destino)
        else:
            st.rerun()


def data_entrega_segura(valor):
    try:
        return datetime.strptime(str(valor), "%d/%m/%Y").date()
    except (TypeError, ValueError):
        return None


def normalizar_texto_busca(prop):
    partes = [
        prop.get("numero_proposta", ""), prop.get("cliente_nome", ""),
        prop.get("whatsapp", prop.get("cliente_wa", "")),
        prop.get("documento", prop.get("cliente_cpf_cnpj", "")),
    ]
    partes.extend(item.get("produto", "") for item in prop.get("itens", []) or [])
    return " ".join(str(p) for p in partes).lower()


# --- CLIENTES (VERSÃO 3.1) ---
def carregar_clientes():
    """Carrega o cadastro de clientes do Supabase, com fallback em JSON local."""
    dados = load_document("clientes_db", ARQUIVO_CLIENTES, [])
    return dados if isinstance(dados, list) else []


def salvar_clientes(lista):
    if not isinstance(lista, list):
        raise ValueError("O cadastro de clientes precisa ser uma lista.")
    save_document("clientes_db", lista, ARQUIVO_CLIENTES)


def normalizar_texto_cliente(valor):
    return re.sub(r"\s+", " ", str(valor or "").strip())


def chave_cliente(nome, documento="", whatsapp=""):
    documento_limpo = re.sub(r"\D", "", str(documento or ""))
    whatsapp_limpo = re.sub(r"\D", "", str(whatsapp or ""))
    if documento_limpo:
        return f"doc:{documento_limpo}"
    if whatsapp_limpo:
        return f"wa:{whatsapp_limpo}"
    return f"nome:{normalizar_texto_cliente(nome).lower()}"


def _valor_preenchido(valor):
    if isinstance(valor, (list, dict)):
        return bool(valor)
    return bool(str(valor or "").strip())


def _pontuacao_cadastro_relacionamento(cliente):
    """Prioriza o cadastro manual/mais completo ao consolidar duplicidades seguras."""
    campos = ["documento", "whatsapp", "email", "cidade", "aniversario", "observacoes", "segmentos", "interesses", "papeis"]
    pontos = sum(1 for campo in campos if _valor_preenchido(cliente.get(campo)))
    origem = str(cliente.get("origem", cliente.get("origem_cliente", ""))).casefold()
    if "histórico" not in origem and "historico" not in origem:
        pontos += 3
    if cliente.get("politica_atendimento"):
        pontos += 2
    if cliente.get("classificacao_relacionamento") not in (None, "", "Não classificado"):
        pontos += 1
    return pontos


def consolidar_cadastros_duplicados_relacionamentos(clientes=None, historico=None, salvar=True):
    """Consolida apenas duplicidades seguras e preserva o cadastro mais completo.

    A consolidação automática exige nome exato normalizado e, além disso, identificadores
    iguais ou ausência de documento/WhatsApp em pelo menos um dos cadastros. Propostas são
    religadas ao cadastro canônico; nenhuma proposta é removida.
    """
    clientes = list(clientes if clientes is not None else carregar_clientes())
    historico = list(historico if historico is not None else carregar_historico())
    grupos = {}
    for cli in clientes:
        nome = normalizar_texto_cliente(cli.get("nome", "")).casefold()
        if nome:
            grupos.setdefault(nome, []).append(cli)

    removidos = set()
    alterou_clientes = False
    alterou_historico = False
    consolidados = 0

    for _, grupo in grupos.items():
        ativos = [c for c in grupo if id(c) not in removidos]
        if len(ativos) < 2:
            continue
        canonico = max(ativos, key=_pontuacao_cadastro_relacionamento)
        garantir_id_relacionamento(canonico)
        for duplicado in ativos:
            if duplicado is canonico or id(duplicado) in removidos:
                continue
            doc_c = re.sub(r"\D", "", str(canonico.get("documento", "")))
            doc_d = re.sub(r"\D", "", str(duplicado.get("documento", "")))
            wa_c = re.sub(r"\D", "", str(canonico.get("whatsapp", "")))
            wa_d = re.sub(r"\D", "", str(duplicado.get("whatsapp", "")))
            identificador_conflitante = (doc_c and doc_d and doc_c != doc_d) or (wa_c and wa_d and wa_c != wa_d)
            if identificador_conflitante:
                continue

            # Preenche apenas lacunas do cadastro canônico; nunca sobrescreve dado manual atual.
            for campo, valor in duplicado.items():
                if campo in {"id", "nome", "criado_em"}:
                    continue
                if not _valor_preenchido(canonico.get(campo)) and _valor_preenchido(valor):
                    canonico[campo] = valor
                    alterou_clientes = True

            dup_id = str(duplicado.get("id", "")).strip()
            can_id = str(canonico.get("id", "")).strip()
            for prop in historico:
                prop_id = str(prop.get("relacionamento_id", "")).strip()
                nome_prop = normalizar_texto_cliente(prop.get("cliente_nome", prop.get("cliente", ""))).casefold()
                if (dup_id and prop_id == dup_id) or (not prop_id and nome_prop == normalizar_texto_cliente(canonico.get("nome", "")).casefold()):
                    prop["relacionamento_id"] = can_id
                    alterou_historico = True
            removidos.add(id(duplicado))
            alterou_clientes = True
            consolidados += 1

    if removidos:
        clientes = [c for c in clientes if id(c) not in removidos]
    if salvar:
        if alterou_clientes:
            salvar_clientes(clientes)
        if alterou_historico:
            salvar_historico_completo(historico)
    return clientes, historico, {"consolidados": consolidados, "clientes_alterados": alterou_clientes, "historico_alterado": alterou_historico}


def sincronizar_clientes_do_historico():
    """Inclui clientes das propostas e consolida duplicidades seguras sem perder dados."""
    clientes = carregar_clientes()
    historico = carregar_historico()
    clientes, historico, _ = consolidar_cadastros_duplicados_relacionamentos(clientes, historico, salvar=True)

    por_doc, por_wa, por_nome = {}, {}, {}
    for c in clientes:
        nome = normalizar_texto_cliente(c.get("nome", "")).casefold()
        doc = re.sub(r"\D", "", str(c.get("documento", "")))
        wa = re.sub(r"\D", "", str(c.get("whatsapp", "")))
        if doc: por_doc.setdefault(doc, []).append(c)
        if wa: por_wa.setdefault(wa, []).append(c)
        if nome: por_nome.setdefault(nome, []).append(c)

    alterado = False
    historico_alterado = False
    for prop in historico:
        nome = normalizar_texto_cliente(prop.get("cliente_nome", prop.get("cliente", "")))
        if not nome:
            continue
        documento = normalizar_texto_cliente(prop.get("documento", prop.get("cliente_cpf_cnpj", "")))
        whatsapp = normalizar_texto_cliente(prop.get("whatsapp", prop.get("cliente_wa", "")))
        doc = re.sub(r"\D", "", documento)
        wa = re.sub(r"\D", "", whatsapp)
        nome_norm = nome.casefold()
        candidatos = []
        if doc and len(por_doc.get(doc, [])) == 1:
            candidatos = por_doc[doc]
        elif wa and len(por_wa.get(wa, [])) == 1:
            candidatos = por_wa[wa]
        elif len(por_nome.get(nome_norm, [])) == 1:
            candidatos = por_nome[nome_norm]

        if candidatos:
            atual = candidatos[0]
            garantir_id_relacionamento(atual)
            if prop.get("relacionamento_id") != atual.get("id"):
                prop["relacionamento_id"] = atual.get("id")
                historico_alterado = True
            if not atual.get("documento") and documento:
                atual["documento"] = documento; alterado = True
            if not atual.get("whatsapp") and whatsapp:
                atual["whatsapp"] = whatsapp; alterado = True
            continue

        novo = {
            "id": f"CLI-{agora_local().strftime('%Y%m%d%H%M%S%f')}",
            "nome": nome,
            "documento": documento,
            "whatsapp": whatsapp,
            "email": "",
            "aniversario": "",
            "observacoes": "",
            "origem": "Histórico de propostas",
            "criado_em": agora_local().strftime("%d/%m/%Y %H:%M"),
        }
        clientes.append(novo)
        por_nome.setdefault(nome_norm, []).append(novo)
        if doc: por_doc.setdefault(doc, []).append(novo)
        if wa: por_wa.setdefault(wa, []).append(novo)
        prop["relacionamento_id"] = novo["id"]
        alterado = True
        historico_alterado = True

    if alterado:
        salvar_clientes(clientes)
    if historico_alterado:
        salvar_historico_completo(historico)
    return clientes




def _digitos(valor):
    return re.sub(r"\D", "", str(valor or ""))


def _campos_identidade_registro(registro):
    """Extrai os campos de identidade usados para ligar qualquer módulo ao cadastro mestre."""
    return {
        "id": str(registro.get("relacionamento_id", registro.get("cliente_id", "")) or "").strip(),
        "nome": normalizar_texto_cliente(registro.get("cliente_nome", registro.get("cliente", registro.get("nome_cliente", registro.get("nome", ""))))).casefold(),
        "documento": _digitos(registro.get("documento", registro.get("cliente_cpf_cnpj", registro.get("cpf_cnpj", "")))),
        "whatsapp": _telefone_chave(registro.get("whatsapp", registro.get("cliente_wa", registro.get("telefone", "")))),
    }


def _indices_cadastro_mestre(clientes):
    por_id, por_doc, por_wa, por_nome = {}, {}, {}, {}
    for cli in clientes:
        garantir_id_relacionamento(cli)
        cid = str(cli.get("id", "")).strip()
        nome = normalizar_texto_cliente(cli.get("nome", "")).casefold()
        doc = _digitos(cli.get("documento", ""))
        wa = _telefone_chave(cli.get("whatsapp", ""))
        if cid:
            por_id[cid] = cli
        if doc:
            por_doc.setdefault(doc, []).append(cli)
        if wa:
            por_wa.setdefault(wa, []).append(cli)
        if nome:
            por_nome.setdefault(nome, []).append(cli)
    return por_id, por_doc, por_wa, por_nome


def _localizar_no_cadastro_mestre(registro, indices):
    por_id, por_doc, por_wa, por_nome = indices
    ident = _campos_identidade_registro(registro)
    if ident["id"] and ident["id"] in por_id:
        return por_id[ident["id"]]
    for chave, mapa in ((ident["documento"], por_doc), (ident["whatsapp"], por_wa), (ident["nome"], por_nome)):
        if chave and len(mapa.get(chave, [])) == 1:
            return mapa[chave][0]
    return None


def _vincular_lista_cadastro_mestre(itens, indices):
    alterados = 0
    sem_vinculo = 0
    for item in itens or []:
        if not isinstance(item, dict):
            continue
        cli = _localizar_no_cadastro_mestre(item, indices)
        if cli:
            cid = str(cli.get("id", "")).strip()
            if cid and str(item.get("relacionamento_id", "")).strip() != cid:
                item["relacionamento_id"] = cid
                alterados += 1
        elif any(_campos_identidade_registro(item).values()):
            sem_vinculo += 1
    return alterados, sem_vinculo


def sincronizar_cadastro_mestre(salvar=True):
    """Vincula os módulos ao relacionamento mestre sem apagar dados históricos.

    Os dados pessoais continuam preservados dentro dos documentos antigos para auditoria,
    porém todas as telas podem consultar o cadastro atual pelo relacionamento_id.
    """
    clientes = carregar_clientes()
    historico = carregar_historico()
    clientes, historico, consolidacao = consolidar_cadastros_duplicados_relacionamentos(clientes, historico, salvar=False)
    indices = _indices_cadastro_mestre(clientes)
    total_ids = sum(1 for c in clientes if c.get("id"))

    resultados = {
        "relacionamentos": len(clientes),
        "ids_validos": total_ids,
        "duplicidades_consolidadas": consolidacao.get("consolidados", 0),
        "modulos": {},
        "alteracoes": 0,
        "sem_vinculo": 0,
    }

    docs = [
        ("Orçamentos", historico, lambda v: salvar_historico_completo(v)),
        ("Projetos", carregar_projetos(), lambda v: salvar_projetos(v)),
        ("Produção", carregar_producao(), lambda v: salvar_producao(v)),
        ("Campanhas", load_document("campanhas_db", ARQUIVO_CAMPANHAS, []), lambda v: save_document("campanhas_db", v, ARQUIVO_CAMPANHAS)),
    ]
    atendimentos = carregar_atendimentos()
    docs.append(("Atendimentos", atendimentos.get("itens", []), None))

    for nome, itens, salvador in docs:
        if not isinstance(itens, list):
            itens = []
        alterados, sem_vinculo = _vincular_lista_cadastro_mestre(itens, indices)
        resultados["modulos"][nome] = {"registros": len(itens), "vinculados_agora": alterados, "sem_vinculo": sem_vinculo}
        resultados["alteracoes"] += alterados
        resultados["sem_vinculo"] += sem_vinculo
        if salvar and alterados:
            if nome == "Atendimentos":
                atendimentos["itens"] = itens
                salvar_atendimentos(atendimentos)
            elif salvador:
                salvador(itens)

    if salvar:
        salvar_clientes(clientes)
        if consolidacao.get("historico_alterado") and not resultados["modulos"]["Orçamentos"]["vinculados_agora"]:
            salvar_historico_completo(historico)
    return resultados


def dados_atuais_cadastro_mestre(registro):
    """Retorna identidade atual, mantendo o documento operacional original intacto."""
    cli = _localizar_no_cadastro_mestre(registro, _indices_cadastro_mestre(carregar_clientes()))
    if not cli:
        return dict(registro)
    visao = dict(registro)
    mapa = {
        "cliente_nome": "nome",
        "whatsapp": "whatsapp",
        "documento": "documento",
        "email": "email",
        "cidade": "cidade",
    }
    for destino, origem in mapa.items():
        if cli.get(origem):
            visao[destino] = cli.get(origem)
    visao["relacionamento_id"] = cli.get("id")
    return visao

PAPEIS_RELACIONAMENTO = [
    "Cliente", "Fornecedor", "Parceiro comercial", "Prestador de serviço",
    "Freelancer", "Transportadora", "Influenciador / Indicador",
    "Concorrente monitorado", "Ex-cliente", "Contato em observação"
]
NIVEIS_ATENDIMENTO = ["Normal", "Somente manual", "Atenção", "Monitorado", "Bloqueado"]
CLASSIFICACOES_RELACIONAMENTO = ["Não classificado", "Bronze", "Prata", "Ouro", "VIP", "Atenção", "Restrito", "Bloqueado"]
PRIORIDADES_FORNECEDOR = ["Não definida", "Preferencial", "Alternativo", "Emergencial"]

def papeis_relacionamento(cliente):
    papeis = cliente.get("papeis", []) or []
    if isinstance(papeis, str):
        papeis = [x.strip() for x in papeis.split(",") if x.strip()]
    if not papeis:
        papeis = ["Cliente"]
    return list(dict.fromkeys(papeis))

def politica_atendimento(cliente):
    politica = cliente.get("politica_atendimento", {}) or {}
    return {
        "nivel": politica.get("nivel", "Normal"),
        "motivo": politica.get("motivo", ""),
        "permitir_resposta": bool(politica.get("permitir_resposta", True)),
        "permitir_catalogo": bool(politica.get("permitir_catalogo", True)),
        "permitir_orcamento": bool(politica.get("permitir_orcamento", True)),
        "permitir_campanhas": bool(politica.get("permitir_campanhas", True)),
        "exigir_pagamento_antecipado": bool(politica.get("exigir_pagamento_antecipado", False)),
        "exigir_aprovacao_gestor": bool(politica.get("exigir_aprovacao_gestor", False)),
    }

def localizar_relacionamento(nome="", whatsapp=""):
    chave_wa = _telefone_chave(whatsapp)
    nome_norm = normalizar_texto_cliente(nome).casefold()
    for cli in carregar_clientes():
        if chave_wa and _telefone_chave(cli.get("whatsapp")) == chave_wa:
            return cli
        if nome_norm and normalizar_texto_cliente(cli.get("nome")).casefold() == nome_norm:
            return cli
    return None

def relacionamento_da_proposta(prop):
    """Retorna o cadastro atual vinculado à proposta, priorizando relacionamento_id."""
    clientes = carregar_clientes()
    rel_id = str(prop.get("relacionamento_id", "")).strip()
    if rel_id:
        encontrado = next((c for c in clientes if str(c.get("id", "")).strip() == rel_id), None)
        if encontrado:
            return encontrado
    nome = prop.get("cliente_nome", prop.get("cliente", ""))
    whatsapp = prop.get("whatsapp", prop.get("cliente_wa", ""))
    return localizar_relacionamento(nome, whatsapp)


def proposta_com_dados_atuais(prop):
    """Cria uma visão da proposta usando os dados atuais do relacionamento.

    Itens, valores, datas e status continuam vindo da proposta histórica.
    """
    atual = relacionamento_da_proposta(prop)
    if not atual:
        return dict(prop), None
    visao = dict(prop)
    nome = atual.get("nome") or visao.get("cliente_nome", visao.get("cliente", ""))
    documento = atual.get("documento") or visao.get("documento", visao.get("cliente_cpf_cnpj", ""))
    whatsapp = atual.get("whatsapp") or visao.get("whatsapp", visao.get("cliente_wa", ""))
    visao.update({
        "cliente_nome": nome,
        "cliente": nome,
        "documento": documento,
        "cliente_cpf_cnpj": documento,
        "whatsapp": whatsapp,
        "cliente_wa": whatsapp,
        "email": atual.get("email", visao.get("email", "")),
        "cidade": atual.get("cidade", visao.get("cidade", "")),
        "relacionamento_id": atual.get("id", visao.get("relacionamento_id", "")),
    })
    return visao, atual


def resumo_restricao_relacionamento(cliente):
    if not cliente:
        return None
    politica = politica_atendimento(cliente)
    nivel = politica.get("nivel", "Normal")
    papeis = papeis_relacionamento(cliente)
    restrito = nivel != "Normal" or "Concorrente monitorado" in papeis or not politica.get("permitir_resposta", True)
    if not restrito:
        return None
    return {"nivel": nivel, "motivo": politica.get("motivo", ""), "papeis": papeis, **politica}

def propostas_do_cliente(cliente):
    rel_id = str(cliente.get("id", "")).strip()
    chave = chave_cliente(cliente.get("nome"), cliente.get("documento"), cliente.get("whatsapp"))
    propostas = []
    for prop in carregar_historico():
        if rel_id and str(prop.get("relacionamento_id", "")).strip() == rel_id:
            propostas.append(prop)
            continue
        pchave = chave_cliente(
            prop.get("cliente_nome", prop.get("cliente", "")),
            prop.get("documento", prop.get("cliente_cpf_cnpj", "")),
            prop.get("whatsapp", prop.get("cliente_wa", "")),
        )
        if pchave == chave:
            propostas.append(prop)
    return propostas


# --- 20.4.9-I8.12.1: Histórico de Compras por Fornecedor ---
I8121_UNIDADES = ["un", "pct", "cx", "kg", "g", "m", "cm", "L", "ml", "serviço", "outro"]


def carregar_compras(force_refresh=False):
    dados = load_document("compras_db", ARQUIVO_COMPRAS, [], force_refresh=force_refresh)
    return dados if isinstance(dados, list) else []


def salvar_compras(lista):
    if not isinstance(lista, list):
        raise ValueError("O histórico de compras precisa ser uma lista.")
    return bool(save_document("compras_db", lista, ARQUIVO_COMPRAS))


def _i8121_data_compra(valor):
    if isinstance(valor, date):
        return valor
    texto = str(valor or "").strip()
    for formato in ("%Y-%m-%d", "%d/%m/%Y"):
        try:
            return datetime.strptime(texto, formato).date()
        except Exception:
            pass
    return hoje_local()


def _i8121_chave_item(valor):
    return normalizar_identidade_produto(valor)


def _i8121_fornecedores():
    fornecedores = []
    for cli in carregar_clientes():
        if "Fornecedor" in papeis_relacionamento(cli):
            fornecedores.append(cli)
    return sorted(fornecedores, key=lambda c: normalizar_texto_cliente(c.get("nome", "")).casefold())


def _i8121_compra_anterior(compras, fornecedor_id, item, unidade="", antes_de=None, ignorar_id=""):
    chave_item = _i8121_chave_item(item)
    candidatos = []
    for compra in compras or []:
        if str(compra.get("id", "")) == str(ignorar_id or ""):
            continue
        if str(compra.get("fornecedor_id", "")) != str(fornecedor_id or ""):
            continue
        if _i8121_chave_item(compra.get("item", "")) != chave_item:
            continue
        if unidade and str(compra.get("unidade") or "").strip().casefold() != str(unidade).strip().casefold():
            continue
        data_c = _i8121_data_compra(compra.get("data_compra"))
        criado = str(compra.get("criado_em") or "")
        if antes_de:
            data_ref, criado_ref = antes_de
            if data_c > data_ref or (data_c == data_ref and criado >= criado_ref):
                continue
        candidatos.append((data_c, criado, compra))
    if not candidatos:
        return None
    candidatos.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return candidatos[0][2]


def _i8121_variacao_unitaria(compras, compra):
    anterior = _i8121_compra_anterior(
        compras,
        compra.get("fornecedor_id"),
        compra.get("item"),
        compra.get("unidade", ""),
        antes_de=(_i8121_data_compra(compra.get("data_compra")), str(compra.get("criado_em") or "")),
        ignorar_id=compra.get("id", ""),
    )
    if not anterior:
        return None, None
    atual = valor_float(compra.get("custo_unitario", 0))
    anterior_valor = valor_float(anterior.get("custo_unitario", 0))
    return atual - anterior_valor, anterior


def _i8121_moeda(valor):
    return f"R$ {valor_float(valor):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


def _i8121_moeda_md(valor):
    """Moeda segura para componentes Streamlit que interpretam Markdown/LaTeX.

    O caractere $ sem escape pode ser interpretado como delimitador matemático,
    causando textos como **R 0,20** ou exibindo os asteriscos literalmente.
    """
    return _i8121_moeda(valor).replace("$", r"\$")


def _i8121_quantidade(valor):
    numero = valor_float(valor)
    if abs(numero - round(numero)) < 0.000001:
        return str(int(round(numero)))
    return f"{numero:.3f}".rstrip("0").rstrip(".").replace(".", ",")


def _i8121_resumo_variacao(delta):
    if delta is None or abs(delta) < 0.005:
        return "Sem variação" if delta is not None else "Primeira compra"
    if delta > 0:
        return f"↑ +{_i8121_moeda(delta)}"
    return f"↓ -{_i8121_moeda(abs(delta))}"


# --- 20.4.9-I8.12.2: Estoque e movimentação de materiais ---
I8122_ESTOQUE_PADRAO = {"materiais": [], "movimentacoes": []}
I8122_TIPOS_MANUAIS = ["Entrada manual", "Saída manual", "Perda", "Ajuste de inventário"]


def carregar_estoque(force_refresh=False):
    dados = load_document("estoque_db", ARQUIVO_ESTOQUE, I8122_ESTOQUE_PADRAO, force_refresh=force_refresh)
    if not isinstance(dados, dict):
        dados = {}
    materiais = dados.get("materiais") if isinstance(dados.get("materiais"), list) else []
    movimentos = dados.get("movimentacoes") if isinstance(dados.get("movimentacoes"), list) else []
    return {"materiais": materiais, "movimentacoes": movimentos}


def salvar_estoque(dados):
    if not isinstance(dados, dict):
        raise ValueError("O estoque precisa ser um objeto com materiais e movimentações.")
    normalizado = {
        "materiais": list(dados.get("materiais") or []),
        "movimentacoes": list(dados.get("movimentacoes") or []),
    }
    return bool(save_document("estoque_db", normalizado, ARQUIVO_ESTOQUE))


def _i8122_material_id(nome, unidade):
    chave = f"{_i8121_chave_item(nome)}|{str(unidade or '').strip().casefold()}"
    return "MAT" + hashlib.sha1(chave.encode("utf-8")).hexdigest()[:16].upper()


def _i8122_material_por_id(dados, material_id):
    return next((m for m in (dados.get("materiais") or []) if str(m.get("id")) == str(material_id)), None)


def _i8122_garantir_material(dados, nome, unidade, usuario="Jorge", estoque_minimo=None):
    nome = str(nome or "").strip()
    unidade = str(unidade or "un").strip() or "un"
    material_id = _i8122_material_id(nome, unidade)
    material = _i8122_material_por_id(dados, material_id)
    criado = False
    if material is None:
        material = {
            "id": material_id,
            "nome": nome,
            "unidade": unidade,
            "estoque_minimo": max(0.0, valor_float(estoque_minimo or 0)),
            "ativo": True,
            "criado_em": agora_local().isoformat(),
            "criado_por": str(usuario or "Jorge"),
        }
        dados.setdefault("materiais", []).append(material)
        criado = True
    elif estoque_minimo is not None:
        material["estoque_minimo"] = max(0.0, valor_float(estoque_minimo))
    return material, criado


def _i8122_saldo_material(dados, material_id):
    return round(sum(
        valor_float(m.get("delta", 0))
        for m in (dados.get("movimentacoes") or [])
        if str(m.get("material_id")) == str(material_id)
    ), 6)


def _i8122_movimento_estornado(dados, movimento_id):
    return any(
        str(m.get("estorno_de") or "") == str(movimento_id)
        for m in (dados.get("movimentacoes") or [])
    )


def _i8122_adicionar_movimento(dados, material, delta, tipo, data_movimento=None, observacao="", origem_tipo="Manual", origem_id="", estorno_de="", usuario="Jorge"):
    delta = round(valor_float(delta), 6)
    if abs(delta) < 0.000001:
        raise ValueError("A movimentação precisa alterar o saldo do material.")
    registro = {
        "id": agora_local().strftime("MOV%Y%m%d%H%M%S%f"),
        "material_id": str(material.get("id") or ""),
        "material_nome": str(material.get("nome") or ""),
        "unidade": str(material.get("unidade") or ""),
        "tipo": str(tipo or "Movimentação"),
        "quantidade": abs(delta),
        "delta": delta,
        "data_movimento": (data_movimento or hoje_local()).isoformat() if isinstance((data_movimento or hoje_local()), date) else str(data_movimento),
        "observacao": str(observacao or "").strip(),
        "origem_tipo": str(origem_tipo or "Manual"),
        "origem_id": str(origem_id or ""),
        "estorno_de": str(estorno_de or ""),
        "criado_em": agora_local().isoformat(),
        "criado_por": str(usuario or "Jorge"),
    }
    dados.setdefault("movimentacoes", []).append(registro)
    return registro


def _i8122_registrar_entrada_compra(compra, force_refresh=True, motivo="Entrada automática da compra"):
    if not isinstance(compra, dict) or not str(compra.get("id") or "").strip():
        return False, "Compra inválida para entrada de estoque."
    dados = carregar_estoque(force_refresh=force_refresh)
    compra_id = str(compra.get("id"))
    existentes = [
        m for m in (dados.get("movimentacoes") or [])
        if str(m.get("origem_tipo")) == "Compra" and str(m.get("origem_id")) == compra_id and not str(m.get("estorno_de") or "")
    ]
    ativos = [m for m in existentes if not _i8122_movimento_estornado(dados, m.get("id"))]
    if ativos:
        return True, "Entrada de estoque desta compra já registrada."
    material, _ = _i8122_garantir_material(
        dados, compra.get("item"), compra.get("unidade"), usuario=compra.get("criado_por") or "Jorge"
    )
    qtd = valor_float(compra.get("quantidade", 0))
    if qtd <= 0:
        return False, "A compra não possui quantidade válida para estoque."
    mov = _i8122_adicionar_movimento(
        dados, material, qtd, "Entrada por compra", _i8121_data_compra(compra.get("data_compra")),
        observacao=motivo, origem_tipo="Compra", origem_id=compra_id, usuario=compra.get("criado_por") or "Jorge"
    )
    if not salvar_estoque(dados):
        return False, "Não foi possível salvar a entrada de estoque."
    registrar_auditoria("Entrada de estoque por compra", "Estoque", mov.get("id"), {
        "compra_id": compra_id, "material": material.get("nome"), "quantidade": qtd, "unidade": material.get("unidade")
    })
    return True, "Entrada de estoque registrada."


def _i8122_estornar_entrada_compra(compra_id, motivo="Compra removida", usuario="Jorge"):
    dados = carregar_estoque(force_refresh=True)
    originais = [
        m for m in (dados.get("movimentacoes") or [])
        if str(m.get("origem_tipo")) == "Compra" and str(m.get("origem_id")) == str(compra_id) and not str(m.get("estorno_de") or "")
        and not _i8122_movimento_estornado(dados, m.get("id"))
    ]
    if not originais:
        return True, "Nenhuma entrada ativa desta compra no estoque."
    por_material = {}
    for mov in originais:
        por_material.setdefault(str(mov.get("material_id")), 0.0)
        por_material[str(mov.get("material_id"))] += valor_float(mov.get("delta", 0))
    for material_id, qtd_retirar in por_material.items():
        saldo = _i8122_saldo_material(dados, material_id)
        if saldo - qtd_retirar < -0.000001:
            material = _i8122_material_por_id(dados, material_id) or {}
            return False, f"Não é possível excluir a compra: o saldo de {material.get('nome', 'material')} ficaria negativo. Faça primeiro um ajuste de estoque."
    for original in originais:
        material = _i8122_material_por_id(dados, original.get("material_id")) or {
            "id": original.get("material_id"), "nome": original.get("material_nome"), "unidade": original.get("unidade")
        }
        estorno = _i8122_adicionar_movimento(
            dados, material, -valor_float(original.get("delta", 0)), "Estorno de entrada por compra", hoje_local(),
            observacao=motivo, origem_tipo="Estorno", origem_id=str(compra_id), estorno_de=original.get("id"), usuario=usuario
        )
        registrar_auditoria("Estornar entrada de estoque", "Estoque", estorno.get("id"), {
            "compra_id": str(compra_id), "movimento_original": original.get("id"), "material": material.get("nome")
        })
    return bool(salvar_estoque(dados)), "Entrada de estoque estornada."


def _i8122_ultimo_custo(material, compras):
    candidatos = []
    chave = _i8121_chave_item(material.get("nome"))
    unidade = str(material.get("unidade") or "").strip().casefold()
    for compra in compras or []:
        if _i8121_chave_item(compra.get("item")) != chave:
            continue
        if str(compra.get("unidade") or "").strip().casefold() != unidade:
            continue
        candidatos.append((_i8121_data_compra(compra.get("data_compra")), str(compra.get("criado_em") or ""), compra))
    if not candidatos:
        return None
    candidatos.sort(key=lambda x: (x[0], x[1]), reverse=True)
    return candidatos[0][2]


def _i8122_status_material(saldo, minimo):
    saldo = valor_float(saldo)
    minimo = max(0.0, valor_float(minimo))
    if saldo <= 0.000001:
        return "🔴 Zerado"
    if minimo > 0 and saldo <= minimo + 0.000001:
        return "🟡 No/abaixo do mínimo"
    return "🟢 OK"


# --- 20.4.9-I8.12.3: Ficha Técnica de Consumo ---
I8123_FICHAS_PADRAO = []


def carregar_fichas_tecnicas(force_refresh=False):
    dados = load_document("fichas_tecnicas_db", ARQUIVO_FICHAS_TECNICAS, I8123_FICHAS_PADRAO, force_refresh=force_refresh)
    return dados if isinstance(dados, list) else []


def salvar_fichas_tecnicas(lista):
    if not isinstance(lista, list):
        raise ValueError("As fichas técnicas precisam ser uma lista.")
    return bool(save_document("fichas_tecnicas_db", lista, ARQUIVO_FICHAS_TECNICAS))


def _i8123_chave_produto_ref(ref):
    ref = ref or {}
    codigo = str(ref.get("codigo_interno") or "").strip().casefold()
    nome = str(ref.get("nome_chave") or normalizar_identidade_produto(ref.get("nome_ref"))).strip()
    categoria = str(ref.get("categoria_chave") or normalizar_identidade_produto(ref.get("categoria_ref"))).strip()
    return f"{codigo}|{nome}|{categoria}"


def _i8123_ficha_id(ref):
    chave = _i8123_chave_produto_ref(ref)
    return "FT" + hashlib.sha1(chave.encode("utf-8")).hexdigest()[:16].upper()


def _i8123_ficha_para_produto(fichas, produto, indice):
    ref = _i88_ref_produto(produto, indice)
    chave = _i8123_chave_produto_ref(ref)
    for ficha in (fichas or []):
        if _i8123_chave_produto_ref((ficha or {}).get("produto_ref") or {}) == chave:
            return ficha
    return None


def _i8123_resolver_ficha(ficha, catalogo):
    indice, metodo = _i88_resolver_ref_produto((ficha or {}).get("produto_ref") or {}, catalogo or [])
    if indice is None:
        return None, metodo
    return (catalogo or [])[indice], metodo


def _i8123_componentes_ativos(ficha):
    return [
        c for c in ((ficha or {}).get("componentes") or [])
        if c.get("ativo", True) and valor_float(c.get("consumo_por_unidade", 0)) > 0.0000001
    ]


def _i8123_status_ficha(ficha, estoque):
    componentes = _i8123_componentes_ativos(ficha)
    if not componentes:
        return "Sem materiais"
    materiais = {str(m.get("id")): m for m in ((estoque or {}).get("materiais") or []) if m.get("ativo", True)}
    ausentes = [c for c in componentes if str(c.get("material_id")) not in materiais]
    return "Atenção: material ausente" if ausentes else "Pronta para simulação"


def _i8123_capacidade_estimada(ficha, estoque):
    componentes = _i8123_componentes_ativos(ficha)
    if not componentes:
        return None, None
    capacidades = []
    for comp in componentes:
        consumo = valor_float(comp.get("consumo_por_unidade", 0))
        material_id = str(comp.get("material_id") or "")
        material = _i8122_material_por_id(estoque or {}, material_id)
        if not material or consumo <= 0:
            return 0, comp
        saldo = max(0.0, _i8122_saldo_material(estoque or {}, material_id))
        capacidades.append((saldo / consumo, comp))
    if not capacidades:
        return None, None
    capacidade, gargalo = min(capacidades, key=lambda x: x[0])
    return max(0, int(capacidade + 0.0000001)), gargalo


# --- 20.4.9-I8.11.1: Central de Faturamento Mensal ---
I8111_STATUS_FECHADO = "Fechado"
I8111_STATUS_FATURADO = "Faturado"
I8111_STATUS_RECEBIDO = "Recebido"
I8111_STATUS_REABERTO = "Reaberto"


def carregar_faturamentos_mensais():
    dados = load_document("faturamento_mensal_db", ARQUIVO_FATURAMENTO_MENSAL, [])
    return dados if isinstance(dados, list) else []


def salvar_faturamentos_mensais(lista):
    if not isinstance(lista, list):
        raise ValueError("A Central de Faturamento Mensal precisa ser uma lista.")
    return bool(save_document("faturamento_mensal_db", lista, ARQUIVO_FATURAMENTO_MENSAL))


def _i8111_usuario_nome():
    return str((obter_usuario_atual() or {}).get("nome") or "Usuário").strip() or "Usuário"


def _i8111_data_limite_mes(ano, mes, dia):
    ultimo = calendar.monthrange(int(ano), int(mes))[1]
    return date(int(ano), int(mes), max(1, min(int(dia or 1), ultimo)))


def _i8111_mes_seguinte(ano, mes):
    return (ano + 1, 1) if mes == 12 else (ano, mes + 1)


def _i8111_competencia_data(data_base, dia_fechamento):
    """Define a competência pelo ciclo de fechamento do cliente.

    Exemplo: fechamento dia 1 -> entrega em 18/08 pertence à competência 09/2026,
    cujo fechamento previsto será 01/09. Isso evita colocar uma entrega posterior
    dentro de um fechamento que já teria ocorrido.
    """
    data_base = data_base or hoje_local()
    dia = max(1, min(31, int(dia_fechamento or 1)))
    ano, mes = data_base.year, data_base.month
    if data_base.day > dia:
        ano, mes = _i8111_mes_seguinte(ano, mes)
    return f"{ano:04d}-{mes:02d}"


def _i8111_competencia_partes(competencia):
    try:
        ano, mes = [int(x) for x in str(competencia).split("-")[:2]]
        if 1 <= mes <= 12:
            return ano, mes
    except Exception:
        pass
    hoje = hoje_local()
    return hoje.year, hoje.month


def _i8111_datas_competencia(competencia, dia_fechamento, dia_vencimento):
    ano, mes = _i8111_competencia_partes(competencia)
    fechamento = _i8111_data_limite_mes(ano, mes, dia_fechamento)
    vencimento = _i8111_data_limite_mes(ano, mes, dia_vencimento)
    if vencimento < fechamento:
        a2, m2 = _i8111_mes_seguinte(ano, mes)
        vencimento = _i8111_data_limite_mes(a2, m2, dia_vencimento)
    return fechamento, vencimento


def _i8111_competencia_rotulo(competencia):
    meses = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"]
    ano, mes = _i8111_competencia_partes(competencia)
    return f"{meses[mes - 1].capitalize()}/{ano}"


# --- 20.4.9-I8.11.2: Resumo Mensal Executivo ---
def _i8112_competencia_mes(data_base):
    data_base = data_base or hoje_local()
    return f"{data_base.year:04d}-{data_base.month:02d}"


def _i8112_mes_anterior(competencia):
    ano, mes = _i8111_competencia_partes(competencia)
    if mes == 1:
        return f"{ano - 1:04d}-12"
    return f"{ano:04d}-{mes - 1:02d}"


def _i8112_intervalo_mes(competencia, referencia=None):
    referencia = referencia or hoje_local()
    ano, mes = _i8111_competencia_partes(competencia)
    inicio = date(ano, mes, 1)
    fim = date(ano, mes, calendar.monthrange(ano, mes)[1])
    if ano == referencia.year and mes == referencia.month:
        fim = min(fim, referencia)
    return inicio, fim


def _i8112_data_no_intervalo(valor, inicio, fim):
    data_evento = _data_resultado(valor)
    return bool(data_evento and inicio <= data_evento <= fim)


def _i8112_data_evento_mes(prop, campos, inicio, fim):
    for campo in campos:
        data_evento = _data_resultado((prop or {}).get(campo))
        if data_evento:
            return data_evento if inicio <= data_evento <= fim else None
    return None


def _i8112_moeda(valor):
    return f"R$ {valor_float(valor):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


def _i8112_delta_moeda(atual, anterior):
    diferenca = round(valor_float(atual) - valor_float(anterior), 2)
    sinal = "+" if diferenca > 0 else ""
    return f"{sinal}{_i8112_moeda(diferenca)} vs mês anterior"


def _i8112_delta_numero(atual, anterior):
    diferenca = int(atual or 0) - int(anterior or 0)
    sinal = "+" if diferenca > 0 else ""
    return f"{sinal}{diferenca} vs mês anterior"


def _i8112_delta_percentual(atual, anterior):
    diferenca = round(float(atual or 0) - float(anterior or 0), 1)
    sinal = "+" if diferenca > 0 else ""
    return f"{sinal}{diferenca:.1f} p.p. vs mês anterior".replace(".", ",")


def _i8112_valor_recebido_fechamento(registro):
    """Valor efetivamente recebido, preservando ajustes após reabertura."""
    registro = registro or {}
    if registro.get("valor_recebido_preservado") not in (None, ""):
        base = valor_float(registro.get("valor_recebido_preservado"))
        adicional = valor_float(registro.get("saldo_adicional_recebido"))
        return base + adicional
    return valor_float(registro.get("total_fechado"))


def _i8112_competencias_resumo(historico, registros, referencia=None):
    referencia = referencia or hoje_local()
    competencias = set()
    ano, mes = referencia.year, referencia.month
    for _ in range(13):
        competencias.add(f"{ano:04d}-{mes:02d}")
        if mes == 1:
            ano, mes = ano - 1, 12
        else:
            mes -= 1

    for prop in historico or []:
        if not isinstance(prop, dict):
            continue
        d = _data_resultado(
            prop.get("data_geracao")
            or prop.get("data")
            or prop.get("criado_em")
            or prop.get("created_at")
        )
        if d:
            competencias.add(f"{d.year:04d}-{d.month:02d}")

    for registro in registros or []:
        competencia = str((registro or {}).get("competencia") or "").strip()
        if re.fullmatch(r"\d{4}-\d{2}", competencia):
            competencias.add(competencia)

    return sorted(competencias, reverse=True)


def calcular_resumo_mensal_executivo_i8112(historico, registros, competencia, referencia=None):
    """Resumo mensal com a mesma fonte de propostas/status já homologada no HF3/HF4."""
    referencia = referencia or hoje_local()
    inicio, fim = _i8112_intervalo_mes(competencia, referencia)
    propostas = [p for p in (historico or []) if isinstance(p, dict)]
    validas = [p for p in propostas if not proposta_encerrada(p)]

    propostas_mes = []
    for prop in propostas:
        data_emissao = _data_resultado(
            prop.get("data_geracao")
            or prop.get("data")
            or prop.get("criado_em")
            or prop.get("created_at")
        )
        if data_emissao and inicio <= data_emissao <= fim:
            propostas_mes.append(prop)

    propostas_mes_validas = [p for p in propostas_mes if not proposta_encerrada(p)]
    propostas_mes_encerradas = [p for p in propostas_mes if proposta_encerrada(p)]
    # HF1: conversão comercial deve partir de tudo que foi efetivamente emitido.
    # Propostas não fechadas/encerradas representam oportunidades que não converteram
    # e, portanto, permanecem no denominador.
    aprovadas_das_emitidas = [
        p for p in propostas_mes
        if valor_bool(p.get("aprovado")) and not proposta_encerrada(p)
    ]

    entregues_mes = []
    recebidas_mes = []
    for prop in validas:
        if valor_bool(prop.get("entregue")):
            if _i8112_data_evento_mes(prop, ("entregue_em", "data_entrega_real"), inicio, fim):
                entregues_mes.append(prop)
        if valor_bool(prop.get("pago")):
            if _i8112_data_evento_mes(prop, ("pago_em", "data_pagamento"), inicio, fim):
                recebidas_mes.append(prop)

    total_orcado = sum(calcular_valores_proposta(p)[2] for p in propostas_mes)
    total_aprovado = sum(calcular_valores_proposta(p)[2] for p in aprovadas_das_emitidas)
    total_recebido = sum(calcular_valores_proposta(p)[2] for p in recebidas_mes)
    ticket_medio = total_orcado / len(propostas_mes) if propostas_mes else 0.0
    conversao = (len(aprovadas_das_emitidas) / len(propostas_mes) * 100.0) if propostas_mes else 0.0

    registros_competencia = [
        r for r in (registros or [])
        if isinstance(r, dict) and str(r.get("competencia") or "") == str(competencia)
    ]
    mensal_recebido = sum(
        _i8112_valor_recebido_fechamento(r)
        for r in registros_competencia
        if str(r.get("status") or "") == I8111_STATUS_RECEBIDO
    )
    mensal_registrado_aberto = sum(
        valor_float(r.get("total_fechado"))
        for r in registros_competencia
        if str(r.get("status") or "") in {I8111_STATUS_FECHADO, I8111_STATUS_FATURADO, I8111_STATUS_REABERTO}
    )

    grupos_abertos = montar_grupos_faturamento_mensal(historico, registros)
    mensal_em_composicao = sum(
        valor_float(g.get("total_elegivel"))
        for g in grupos_abertos
        if str(g.get("competencia") or "") == str(competencia)
    )
    mensal_em_aberto = mensal_registrado_aberto + mensal_em_composicao

    return {
        "competencia": competencia,
        "inicio": inicio,
        "fim": fim,
        "propostas_emitidas": len(propostas_mes),
        "total_orcado": total_orcado,
        "aprovadas_das_emitidas": len(aprovadas_das_emitidas),
        "nao_aprovadas_das_emitidas": max(len(propostas_mes) - len(aprovadas_das_emitidas), 0),
        "encerradas_das_emitidas": len(propostas_mes_encerradas),
        "base_conversao": len(propostas_mes),
        "total_aprovado": total_aprovado,
        "entregas_concluidas": len(entregues_mes),
        "recebimentos_qtd": len(recebidas_mes),
        "total_recebido": total_recebido,
        "ticket_medio": ticket_medio,
        "conversao": conversao,
        "mensal_em_aberto": mensal_em_aberto,
        "mensal_recebido": mensal_recebido,
        "mensal_fechamentos": len(registros_competencia),
        "mensal_em_composicao": mensal_em_composicao,
        "mensal_registrado_aberto": mensal_registrado_aberto,
    }


def auditar_eventos_diarios_i8112hf1(historico, referencia=None):
    """Explica quando o status registrado hoje pode representar regularização de histórico.

    Não tenta adivinhar a data real de um evento antigo. Apenas diferencia a data
    em que o Manager recebeu o status da data operacional planejada/emissão.
    """
    referencia = referencia or hoje_local()
    propostas = [p for p in (historico or []) if isinstance(p, dict)]
    aprovacoes_hoje = []
    entregas_hoje = []
    pagamentos_hoje = []
    aprovacoes_de_emitidas_antes = []
    entregas_com_prevista_anterior = []

    for prop in propostas:
        if valor_bool(prop.get("aprovado")):
            d_aprov = _data_resultado(prop.get("aprovado_em") or prop.get("data_aprovacao"))
            if d_aprov == referencia:
                aprovacoes_hoje.append(prop)
                d_emissao = _data_resultado(
                    prop.get("data_geracao") or prop.get("data") or prop.get("criado_em") or prop.get("created_at")
                )
                if d_emissao and d_emissao < referencia:
                    aprovacoes_de_emitidas_antes.append(prop)

        if valor_bool(prop.get("entregue")):
            d_entrega = _data_resultado(prop.get("entregue_em") or prop.get("data_entrega_real"))
            if d_entrega == referencia:
                entregas_hoje.append(prop)
                d_prevista = _data_resultado(prop.get("data_entrega"))
                if d_prevista and d_prevista < referencia:
                    entregas_com_prevista_anterior.append(prop)

        if valor_bool(prop.get("pago")):
            d_pag = _data_resultado(prop.get("pago_em") or prop.get("data_pagamento"))
            if d_pag == referencia:
                pagamentos_hoje.append(prop)

    def _rotulo(prop):
        numero = str(prop.get("numero_proposta") or "—")
        cliente = str(prop.get("cliente_nome") or prop.get("cliente") or "Cliente")
        return f"{numero} · {cliente}"

    return {
        "aprovacoes_registradas_hoje": len(aprovacoes_hoje),
        "entregas_registradas_hoje": len(entregas_hoje),
        "pagamentos_registrados_hoje": len(pagamentos_hoje),
        "aprovacoes_de_emitidas_antes": len(aprovacoes_de_emitidas_antes),
        "entregas_com_prevista_anterior": len(entregas_com_prevista_anterior),
        "exemplos_aprovacoes": [_rotulo(p) for p in aprovacoes_de_emitidas_antes[:8]],
        "exemplos_entregas": [_rotulo(p) for p in entregas_com_prevista_anterior[:8]],
    }


def renderizar_resumo_mensal_executivo_i8112(historico, snapshot_alpha_core=None):
    """Visão mensal do Jorge; Anna permanece sem alteração nesta versão."""
    registros = carregar_faturamentos_mensais()
    referencia = hoje_local()
    competencias = _i8112_competencias_resumo(historico, registros, referencia)
    competencia_atual = _i8112_competencia_mes(referencia)
    indice_atual = competencias.index(competencia_atual) if competencia_atual in competencias else 0

    st.markdown("### 📅 Resumo mensal")
    competencia = st.selectbox(
        "Competência do resumo",
        competencias,
        index=indice_atual,
        format_func=_i8111_competencia_rotulo,
        key="i8112_resumo_mensal_competencia",
        help="Altera somente a competência exibida. Não modifica propostas, fechamentos ou indicadores.",
    )

    atual = calcular_resumo_mensal_executivo_i8112(historico, registros, competencia, referencia)
    anterior_comp = _i8112_mes_anterior(competencia)
    anterior = calcular_resumo_mensal_executivo_i8112(historico, registros, anterior_comp, referencia)

    rm1, rm2, rm3, rm4 = st.columns(4)
    rm1.metric(
        "📄 Propostas emitidas",
        atual["propostas_emitidas"],
        _i8112_delta_numero(atual["propostas_emitidas"], anterior["propostas_emitidas"]),
        help="Propostas emitidas dentro da competência selecionada.",
    )
    rm2.metric(
        "💼 Total orçado",
        _i8112_moeda(atual["total_orcado"]),
        _i8112_delta_moeda(atual["total_orcado"], anterior["total_orcado"]),
        help="Soma do valor final das propostas emitidas no período.",
    )
    rm3.metric(
        "✅ Pedidos aprovados",
        atual["aprovadas_das_emitidas"],
        _i8112_delta_numero(atual["aprovadas_das_emitidas"], anterior["aprovadas_das_emitidas"]),
        help="Das propostas emitidas no período, quantas estão atualmente aprovadas.",
    )
    rm4.metric(
        "🚚 Entregas concluídas",
        atual["entregas_concluidas"],
        _i8112_delta_numero(atual["entregas_concluidas"], anterior["entregas_concluidas"]),
        help="Entregas com data própria de conclusão registrada dentro do mês.",
    )

    rf1, rf2, rf3, rf4 = st.columns(4)
    rf1.metric(
        "💵 Recebido no mês",
        _i8112_moeda(atual["total_recebido"]),
        _i8112_delta_moeda(atual["total_recebido"], anterior["total_recebido"]),
        help="Pagamentos com data de recebimento registrada dentro do mês, incluindo propostas mensalistas baixadas pelo fechamento.",
    )
    rf2.metric(
        "🟡 Mensal em aberto",
        _i8112_moeda(atual["mensal_em_aberto"]),
        help="Faturamento mensal da competência ainda em composição, fechado, faturado ou reaberto e não recebido.",
    )
    rf3.metric(
        "🟢 Mensal recebido",
        _i8112_moeda(atual["mensal_recebido"]),
        help="Fechamentos mensais recebidos pertencentes à competência selecionada.",
    )
    rf4.metric(
        "🎟️ Ticket médio",
        _i8112_moeda(atual["ticket_medio"]),
        _i8112_delta_moeda(atual["ticket_medio"], anterior["ticket_medio"]),
        help="Valor médio das propostas emitidas na competência.",
    )

    core = snapshot_alpha_core.to_dict() if hasattr(snapshot_alpha_core, "to_dict") else dict(snapshot_alpha_core or {})
    rc1, rc2, rc3, rc4, rc5 = st.columns(5)
    rc1.metric(
        "📈 Conversão",
        f"{atual['conversao']:.1f}%".replace(".", ","),
        _i8112_delta_percentual(atual["conversao"], anterior["conversao"]),
        help="Conversão comercial = propostas emitidas no mês que estão aprovadas ÷ todas as propostas emitidas no mês. Não fechadas/encerradas permanecem no denominador.",
    )
    rc2.metric("📦 Pedidos ativos · agora", int(core.get("pedidos_ativos") or 0))
    rc3.metric("📊 Carteira aberta · agora", _i8112_moeda(core.get("carteira_aberta") or 0))
    rc4.metric("🟡 Aprovação pendente · agora", int(core.get("aguardando_aprovacao") or 0))
    rc5.metric("🔴 Atrasados · agora", int(core.get("atrasados") or 0))

    with st.expander("🔎 Como ler o resumo mensal", expanded=False):
        st.caption(
            f"Período exibido: {atual['inicio'].strftime('%d/%m/%Y')} a {atual['fim'].strftime('%d/%m/%Y')}. "
            "Propostas e valores do mês usam a data de emissão. Entregas e recebimentos usam a data própria do evento registrada no histórico."
        )
        if atual["base_conversao"]:
            st.write(
                f"**Conversão comercial:** {atual['aprovadas_das_emitidas']} aprovada(s) ÷ "
                f"{atual['base_conversao']} emitida(s) = **{atual['conversao']:.1f}%**. "
                f"Há {atual['nao_aprovadas_das_emitidas']} proposta(s) ainda não convertida(s); "
                f"{atual['encerradas_das_emitidas']} delas estão encerradas/não fechadas e continuam no denominador."
            )
        st.write(
            f"**Faturamento mensal da competência:** {_i8112_moeda(atual['mensal_em_composicao'])} em composição + "
            f"{_i8112_moeda(atual['mensal_registrado_aberto'])} já fechado/faturado/reaberto = "
            f"**{_i8112_moeda(atual['mensal_em_aberto'])} em aberto**."
        )
        st.caption(
            "Os indicadores com “· agora” são uma fotografia operacional atual, mesmo quando você consulta um mês passado. "
            "Essa distinção evita fingir um histórico que o sistema não registrava naquela época."
        )


def _i8111_data_proposta_mensal(prop):
    # A entrega efetiva/planejada define o ciclo. Em bases legadas sem data de
    # entrega, usa a emissão somente para não perder a proposta do controle.
    return (
        _data_resultado((prop or {}).get("data_entrega"))
        or _data_resultado((prop or {}).get("data_geracao"))
        or hoje_local()
    )


def _i8111_cliente_proposta(prop):
    cliente = relacionamento_da_proposta(prop)
    if cliente:
        return cliente
    return localizar_cliente_comercial(
        (prop or {}).get("cliente_nome", ""),
        (prop or {}).get("documento", (prop or {}).get("cliente_cpf_cnpj", "")),
        (prop or {}).get("whatsapp", (prop or {}).get("cliente_wa", "")),
    ) or {}


def _i8111_cliente_id(cliente, prop=None):
    cid = str((cliente or {}).get("id") or "").strip()
    if cid:
        return cid
    rid = str((prop or {}).get("relacionamento_id") or "").strip()
    if rid:
        return rid
    wa = _telefone_chave((cliente or {}).get("whatsapp") or (prop or {}).get("whatsapp") or (prop or {}).get("cliente_wa"))
    if wa:
        return f"WA-{wa}"
    nome = normalizar_texto_cliente((cliente or {}).get("nome") or (prop or {}).get("cliente_nome") or "CLIENTE")
    return f"NOME-{hashlib.sha1(nome.encode('utf-8')).hexdigest()[:12]}"


def _i8111_propostas_vinculadas(registros=None):
    vinculadas = {}
    for reg in (registros if isinstance(registros, list) else carregar_faturamentos_mensais()):
        if str(reg.get("status") or "") not in {I8111_STATUS_FECHADO, I8111_STATUS_FATURADO, I8111_STATUS_RECEBIDO, I8111_STATUS_REABERTO}:
            continue
        for item in reg.get("propostas", []) if isinstance(reg.get("propostas"), list) else []:
            numero = str(item.get("numero_proposta") or "").strip()
            if numero:
                vinculadas[numero] = str(reg.get("id") or "")
    return vinculadas


def montar_grupos_faturamento_mensal(historico=None, registros=None):
    """Monta os ciclos em aberto sem duplicar valores já fechados.

    Somente propostas mensais aprovadas + entregues entram no valor elegível para
    fechamento. Propostas aprovadas aguardando entrega continuam visíveis, mas
    não podem ser faturadas antes da conclusão operacional.
    """
    historico = historico if isinstance(historico, list) else carregar_historico()
    registros = registros if isinstance(registros, list) else carregar_faturamentos_mensais()
    vinculadas = _i8111_propostas_vinculadas(registros)
    grupos = {}
    for prop in historico:
        if not isinstance(prop, dict) or not proposta_faturamento_mensal(prop) or proposta_encerrada(prop):
            continue
        numero = str(prop.get("numero_proposta") or "").strip()
        if numero and numero in vinculadas:
            continue
        cliente = _i8111_cliente_proposta(prop)
        perfil = resumo_perfil_comercial(cliente) if cliente else resumo_perfil_comercial({})
        dia_fecha = int(perfil.get("dia_fechamento") or 1)
        dia_vence = int(perfil.get("dia_vencimento") or 10)
        competencia = str(prop.get("competencia_faturamento") or "").strip() or _i8111_competencia_data(_i8111_data_proposta_mensal(prop), dia_fecha)
        cliente_id = _i8111_cliente_id(cliente, prop)
        chave = (cliente_id, competencia)
        if chave not in grupos:
            fechamento, vencimento = _i8111_datas_competencia(competencia, dia_fecha, dia_vence)
            grupos[chave] = {
                "cliente_id": cliente_id,
                "cliente_nome": str((cliente or {}).get("nome") or prop.get("cliente_nome") or "Cliente").strip(),
                "whatsapp": str((cliente or {}).get("whatsapp") or prop.get("whatsapp") or prop.get("cliente_wa") or "").strip(),
                "competencia": competencia,
                "dia_fechamento": dia_fecha,
                "dia_vencimento": dia_vence,
                "data_fechamento": fechamento,
                "data_vencimento": vencimento,
                "propostas": [],
                "elegiveis": [],
                "aguardando_entrega": [],
                "aguardando_aprovacao": [],
                "pagas_individualmente": [],
            }
        grupo = grupos[chave]
        total = calcular_valores_proposta(prop)[2]
        info = {
            "numero_proposta": numero,
            "valor": total,
            "data_entrega": str(prop.get("data_entrega") or ""),
            "aprovado": valor_bool(prop.get("aprovado")),
            "entregue": valor_bool(prop.get("entregue")),
            "pago": valor_bool(prop.get("pago")),
            "cliente_nome": str(prop.get("cliente_nome") or grupo["cliente_nome"]),
        }
        grupo["propostas"].append(info)
        if info["pago"]:
            grupo["pagas_individualmente"].append(info)
        elif not info["aprovado"]:
            grupo["aguardando_aprovacao"].append(info)
        elif not info["entregue"]:
            grupo["aguardando_entrega"].append(info)
        else:
            grupo["elegiveis"].append(info)
    saida = list(grupos.values())
    for grupo in saida:
        grupo["total_elegivel"] = sum(valor_float(x.get("valor")) for x in grupo["elegiveis"])
        grupo["total_aguardando_entrega"] = sum(valor_float(x.get("valor")) for x in grupo["aguardando_entrega"])
    saida.sort(key=lambda g: (str(g.get("competencia")), str(g.get("cliente_nome", "")).casefold()), reverse=True)
    return saida


def _i8111_snapshot_proposta(info):
    # Snapshot financeiro do fechamento: guarda número e total negociado da
    # proposta. Não duplica preço de produto, foto, descrição ou Catálogo Oficial.
    return {
        "numero_proposta": str(info.get("numero_proposta") or ""),
        "valor": round(valor_float(info.get("valor")), 2),
        "data_entrega": str(info.get("data_entrega") or ""),
    }


def criar_fechamento_mensal(grupo):
    elegiveis = list((grupo or {}).get("elegiveis") or [])
    if not elegiveis:
        raise ValueError("Não existem propostas aprovadas e entregues elegíveis para este fechamento.")
    instante = agora_local()
    registro_id = f"FM-{instante.strftime('%Y%m%d%H%M%S')}-{secrets.token_hex(3)}"
    propostas_snap = [_i8111_snapshot_proposta(x) for x in elegiveis]
    registro = {
        "id": registro_id,
        "cliente_id": str(grupo.get("cliente_id") or ""),
        "cliente_nome": str(grupo.get("cliente_nome") or "Cliente"),
        "whatsapp": str(grupo.get("whatsapp") or ""),
        "competencia": str(grupo.get("competencia") or ""),
        "dia_fechamento": int(grupo.get("dia_fechamento") or 1),
        "dia_vencimento": int(grupo.get("dia_vencimento") or 10),
        "data_fechamento_prevista": grupo.get("data_fechamento").isoformat() if isinstance(grupo.get("data_fechamento"), date) else str(grupo.get("data_fechamento") or ""),
        "data_vencimento_prevista": grupo.get("data_vencimento").isoformat() if isinstance(grupo.get("data_vencimento"), date) else str(grupo.get("data_vencimento") or ""),
        "status": I8111_STATUS_FECHADO,
        "propostas": propostas_snap,
        "total_fechado": round(sum(valor_float(x.get("valor")) for x in propostas_snap), 2),
        "fechado_em": instante.isoformat(timespec="seconds"),
        "fechado_por": _i8111_usuario_nome(),
        "atualizado_em": instante.isoformat(timespec="seconds"),
        "atualizado_por": _i8111_usuario_nome(),
        "observacao_cliente": str((grupo or {}).get("observacao_cliente") or "").strip(),
        "historico_status": [{
            "em": instante.isoformat(timespec="seconds"),
            "por": _i8111_usuario_nome(),
            "acao": "Fechamento criado",
            "status_anterior": "Em aberto",
            "status_novo": I8111_STATUS_FECHADO,
            "total": round(sum(valor_float(x.get("valor")) for x in propostas_snap), 2),
        }],
    }
    registros = carregar_faturamentos_mensais()
    registros.insert(0, registro)
    salvar_faturamentos_mensais(registros)

    numeros = {x.get("numero_proposta") for x in propostas_snap if x.get("numero_proposta")}
    historico = carregar_historico(force_refresh=True)
    for prop in historico:
        if str(prop.get("numero_proposta") or "") in numeros:
            prop["faturamento_mensal_id"] = registro_id
            prop["competencia_faturamento"] = registro["competencia"]
            prop["financeiro_status"] = "Fechado mensal · aguardando faturamento"
            registrar_evento_proposta(prop, f"Incluída no fechamento mensal {registro['competencia']} ({registro_id})", _i8111_usuario_nome())
    salvar_historico_completo(historico)
    registrar_auditoria("Fechar faturamento mensal", "Faturamento mensal", registro_id, {"cliente": registro["cliente_nome"], "competencia": registro["competencia"], "total": registro["total_fechado"], "propostas": len(propostas_snap)})
    return registro


def _i8111_registrar_historico_status(registro, acao, status_anterior="", status_novo="", motivo="", detalhes=None):
    historico = registro.setdefault("historico_status", [])
    if not isinstance(historico, list):
        historico = []
        registro["historico_status"] = historico
    item = {
        "em": agora_local().isoformat(timespec="seconds"),
        "por": _i8111_usuario_nome(),
        "acao": str(acao or "Atualização"),
        "status_anterior": str(status_anterior or ""),
        "status_novo": str(status_novo or ""),
    }
    if str(motivo or "").strip():
        item["motivo"] = str(motivo).strip()
    if isinstance(detalhes, dict) and detalhes:
        item["detalhes"] = detalhes
    historico.append(item)
    return item


def _i8111_localizar_registro(registros, registro_id):
    return next((r for r in registros if str(r.get("id")) == str(registro_id)), None)


def salvar_observacao_fechamento_mensal(registro_id, observacao):
    registros = carregar_faturamentos_mensais()
    registro = _i8111_localizar_registro(registros, registro_id)
    if not registro:
        raise ValueError("Fechamento mensal não localizado.")
    anterior = str(registro.get("observacao_cliente") or "")
    registro["observacao_cliente"] = str(observacao or "").strip()
    registro["atualizado_em"] = agora_local().isoformat(timespec="seconds")
    registro["atualizado_por"] = _i8111_usuario_nome()
    if anterior != registro["observacao_cliente"]:
        _i8111_registrar_historico_status(registro, "Observação comercial atualizada", registro.get("status"), registro.get("status"))
    salvar_faturamentos_mensais(registros)
    return registro


def reabrir_fechamento_mensal(registro_id, motivo):
    motivo = str(motivo or "").strip()
    if len(motivo) < 3:
        raise ValueError("Informe o motivo da reabertura para preservar a auditoria financeira.")
    registros = carregar_faturamentos_mensais()
    registro = _i8111_localizar_registro(registros, registro_id)
    if not registro:
        raise ValueError("Fechamento mensal não localizado.")
    atual = str(registro.get("status") or "")
    if atual not in {I8111_STATUS_FECHADO, I8111_STATUS_FATURADO, I8111_STATUS_RECEBIDO}:
        raise ValueError(f"O fechamento em status {atual or '—'} não pode ser reaberto por esta ação.")
    instante = agora_local()
    usuario = _i8111_usuario_nome()
    registro["status_antes_reabertura"] = atual
    registro["total_antes_reabertura"] = round(valor_float(registro.get("total_fechado")), 2)
    if atual == I8111_STATUS_RECEBIDO:
        registro["valor_recebido_preservado"] = round(valor_float(registro.get("total_fechado")), 2)
        registro["recebimento_preservado_em"] = registro.get("recebido_em")
        registro["recebimento_preservado_por"] = registro.get("recebido_por")
    registro["status"] = I8111_STATUS_REABERTO
    registro["reaberto_em"] = instante.isoformat(timespec="seconds")
    registro["reaberto_por"] = usuario
    registro["motivo_reabertura"] = motivo
    registro["atualizado_em"] = instante.isoformat(timespec="seconds")
    registro["atualizado_por"] = usuario
    _i8111_registrar_historico_status(registro, "Fechamento reaberto para correção", atual, I8111_STATUS_REABERTO, motivo, {"total_antes": registro["total_antes_reabertura"]})
    salvar_faturamentos_mensais(registros)

    numeros = {str(x.get("numero_proposta") or "") for x in registro.get("propostas", []) if str(x.get("numero_proposta") or "")}
    historico = carregar_historico(force_refresh=True)
    for prop in historico:
        if str(prop.get("numero_proposta") or "") not in numeros:
            continue
        prop["faturamento_mensal_id"] = registro_id
        prop["fechamento_mensal_reaberto"] = True
        if atual == I8111_STATUS_RECEBIDO and valor_bool(prop.get("pago")):
            prop["financeiro_status"] = "Recebido anteriormente · fechamento reaberto para correção"
        else:
            prop["financeiro_status"] = "Fechamento mensal reaberto para correção"
        registrar_evento_proposta(prop, f"Fechamento mensal {registro_id} reaberto para correção. Motivo: {motivo}", usuario)
    salvar_historico_completo(historico)
    registrar_auditoria("Reabrir faturamento mensal", "Faturamento mensal", registro_id, {"cliente": registro.get("cliente_nome"), "competencia": registro.get("competencia"), "motivo": motivo, "status_anterior": atual})
    return registro


def sincronizar_fechamento_reaberto(registro_id):
    registros = carregar_faturamentos_mensais()
    registro = _i8111_localizar_registro(registros, registro_id)
    if not registro:
        raise ValueError("Fechamento mensal não localizado.")
    if str(registro.get("status") or "") != I8111_STATUS_REABERTO:
        raise ValueError("Somente um fechamento reaberto pode ser sincronizado para correção.")
    historico = carregar_historico(force_refresh=True)
    por_numero = {str(p.get("numero_proposta") or ""): p for p in historico if isinstance(p, dict) and str(p.get("numero_proposta") or "")}
    novos = []
    faltantes = []
    for snap in registro.get("propostas", []) if isinstance(registro.get("propostas"), list) else []:
        numero = str(snap.get("numero_proposta") or "")
        prop = por_numero.get(numero)
        if not prop:
            faltantes.append(numero)
            continue
        total = calcular_valores_proposta(prop)[2]
        novos.append({"numero_proposta": numero, "valor": round(valor_float(total), 2), "data_entrega": str(prop.get("data_entrega") or snap.get("data_entrega") or "")})
    if faltantes:
        raise ValueError("Não foi possível atualizar o fechamento porque estas propostas não foram localizadas: " + ", ".join(faltantes))
    if not novos:
        raise ValueError("O fechamento não possui propostas válidas para sincronizar.")
    total_antigo = round(valor_float(registro.get("total_fechado")), 2)
    total_novo = round(sum(valor_float(x.get("valor")) for x in novos), 2)
    registro["propostas"] = novos
    registro["total_fechado"] = total_novo
    registro["atualizado_em"] = agora_local().isoformat(timespec="seconds")
    registro["atualizado_por"] = _i8111_usuario_nome()
    if registro.get("valor_recebido_preservado") not in (None, ""):
        registro["diferenca_ajuste"] = round(total_novo - valor_float(registro.get("valor_recebido_preservado")), 2)
    else:
        registro["diferenca_ajuste"] = round(total_novo - valor_float(registro.get("total_antes_reabertura")), 2)
    _i8111_registrar_historico_status(registro, "Fechamento recalculado com propostas atuais", I8111_STATUS_REABERTO, I8111_STATUS_REABERTO, detalhes={"total_anterior": total_antigo, "total_novo": total_novo, "diferenca": registro.get("diferenca_ajuste")})
    salvar_faturamentos_mensais(registros)
    registrar_auditoria("Recalcular faturamento mensal reaberto", "Faturamento mensal", registro_id, {"total_anterior": total_antigo, "total_novo": total_novo, "diferenca": registro.get("diferenca_ajuste")})
    return registro


def atualizar_status_faturamento_mensal(registro_id, novo_status):
    registros = carregar_faturamentos_mensais()
    registro = _i8111_localizar_registro(registros, registro_id)
    if not registro:
        raise ValueError("Fechamento mensal não localizado.")
    atual = str(registro.get("status") or "")
    permitidos = {
        I8111_STATUS_REABERTO: {I8111_STATUS_FECHADO},
        I8111_STATUS_FECHADO: {I8111_STATUS_FATURADO},
        I8111_STATUS_FATURADO: {I8111_STATUS_RECEBIDO},
    }
    if novo_status not in permitidos.get(atual, set()):
        raise ValueError(f"Transição não permitida: {atual} → {novo_status}.")
    instante = agora_local()
    usuario = _i8111_usuario_nome()
    registro["status"] = novo_status
    registro["atualizado_em"] = instante.isoformat(timespec="seconds")
    registro["atualizado_por"] = usuario
    if novo_status == I8111_STATUS_FECHADO and atual == I8111_STATUS_REABERTO:
        registro["correcao_fechada_em"] = instante.isoformat(timespec="seconds")
        registro["correcao_fechada_por"] = usuario
    elif novo_status == I8111_STATUS_FATURADO:
        registro["faturado_em"] = instante.isoformat(timespec="seconds")
        registro["faturado_por"] = usuario
    elif novo_status == I8111_STATUS_RECEBIDO:
        registro["recebido_em"] = instante.isoformat(timespec="seconds")
        registro["recebido_por"] = usuario
        if registro.get("valor_recebido_preservado") not in (None, ""):
            diferenca = round(valor_float(registro.get("total_fechado")) - valor_float(registro.get("valor_recebido_preservado")), 2)
            registro["diferenca_ajuste"] = diferenca
            if diferenca > 0:
                registro["saldo_adicional_recebido"] = diferenca
            elif diferenca < 0:
                registro["credito_cliente"] = abs(diferenca)
            else:
                registro["ajuste_sem_diferenca"] = True
    _i8111_registrar_historico_status(registro, f"Status alterado para {novo_status}", atual, novo_status, detalhes={"total": round(valor_float(registro.get("total_fechado")), 2), "diferenca_ajuste": registro.get("diferenca_ajuste")})
    salvar_faturamentos_mensais(registros)

    numeros = {str(x.get("numero_proposta") or "") for x in registro.get("propostas", []) if str(x.get("numero_proposta") or "")}
    historico = carregar_historico(force_refresh=True)
    for prop in historico:
        if str(prop.get("numero_proposta") or "") not in numeros:
            continue
        if novo_status == I8111_STATUS_FECHADO:
            prop["faturamento_mensal_id"] = registro_id
            prop["fechamento_mensal_reaberto"] = False
            if valor_bool(prop.get("pago")) and str(prop.get("pagamento_faturamento_mensal_id") or "") == str(registro_id):
                prop["financeiro_status"] = "Recebido anteriormente · correção fechada"
            else:
                prop["financeiro_status"] = "Fechado mensal · aguardando faturamento"
            registrar_evento_proposta(prop, f"Correção do fechamento mensal {registro_id} concluída", usuario)
        elif novo_status == I8111_STATUS_FATURADO:
            if valor_bool(prop.get("pago")) and str(prop.get("pagamento_faturamento_mensal_id") or "") == str(registro_id):
                prop["financeiro_status"] = "Recebido anteriormente · ajuste faturado"
            else:
                prop["financeiro_status"] = "Faturado mensal · aguardando recebimento"
            registrar_evento_proposta(prop, f"Fechamento mensal {registro_id} marcado como faturado", usuario)
        elif novo_status == I8111_STATUS_RECEBIDO:
            ja_recebido_mesmo_fechamento = valor_bool(prop.get("pago")) and str(prop.get("pagamento_faturamento_mensal_id") or "") == str(registro_id)
            prop["financeiro_status"] = "Recebido no fechamento mensal"
            prop["pago"] = True
            if not ja_recebido_mesmo_fechamento:
                prop["pago_em"] = instante.strftime("%d/%m/%Y %H:%M")
            else:
                prop["ajuste_faturamento_em"] = instante.strftime("%d/%m/%Y %H:%M")
            prop["pagamento_faturamento_mensal_id"] = registro_id
            prop["fechamento_mensal_reaberto"] = False
            registrar_evento_proposta(prop, f"Pagamento/ajuste concluído pelo fechamento mensal {registro_id}", usuario)
    salvar_historico_completo(historico)
    registrar_auditoria(f"Faturamento mensal: {novo_status}", "Faturamento mensal", registro_id, {"cliente": registro.get("cliente_nome"), "competencia": registro.get("competencia"), "total": registro.get("total_fechado"), "diferenca_ajuste": registro.get("diferenca_ajuste")})
    return registro
def _i8111_status_visual_registro(registro):
    status = str((registro or {}).get("status") or "")
    if status == I8111_STATUS_RECEBIDO:
        return "🟢 Recebido", "recebido"
    try:
        vencimento = date.fromisoformat(str((registro or {}).get("data_vencimento_prevista") or ""))
    except Exception:
        vencimento = None
    if status == I8111_STATUS_FATURADO and vencimento and vencimento < hoje_local():
        return "🔴 Vencido", "vencido"
    if status == I8111_STATUS_FATURADO:
        return "🟡 Faturado", "faturado"
    if status == I8111_STATUS_FECHADO:
        return "🔵 Fechado", "fechado"
    if status == I8111_STATUS_REABERTO:
        return "⚪ Reaberto", "reaberto"
    return status or "—", status.casefold()


def _i8111_formatar_data_iso(valor):
    try:
        return date.fromisoformat(str(valor)).strftime("%d/%m/%Y")
    except Exception:
        return str(valor or "—")


def _i8111_formatar_moeda(valor):
    return f"R$ {valor_float(valor):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

def _i8111_status_documento(registro):
    status = str((registro or {}).get("status") or "—")
    if status == I8111_STATUS_RECEBIDO:
        return "Recebido"
    if status == I8111_STATUS_FATURADO:
        return "Faturado"
    if status == I8111_STATUS_FECHADO:
        return "Fechado"
    if status == I8111_STATUS_REABERTO:
        return "Em correção"
    return status


def formatar_msg_whatsapp_fechamento_mensal(registro):
    reg = registro or {}
    linhas = [
        "*ALPHAFEST — FECHAMENTO MENSAL*",
        f"Cliente: {reg.get('cliente_nome') or 'Cliente'}",
        f"Competência: {_i8111_competencia_rotulo(reg.get('competencia'))}",
        f"Vencimento: {_i8111_formatar_data_iso(reg.get('data_vencimento_prevista'))}",
        "",
        "*Propostas incluídas:*",
    ]
    for item in reg.get("propostas") or []:
        linhas.append(f"• {item.get('numero_proposta') or 'Proposta'} — entrega {_i8111_formatar_data_iso(item.get('data_entrega'))} — {_i8111_formatar_moeda(item.get('valor'))}")
    linhas += ["", f"*Total do fechamento: {_i8111_formatar_moeda(reg.get('total_fechado'))}*", f"Status: {_i8111_status_documento(reg)}"]
    obs = str(reg.get("observacao_cliente") or "").strip()
    if obs:
        linhas += ["", f"Observação: {obs}"]
    if reg.get("valor_recebido_preservado") not in (None, ""):
        diferenca = round(valor_float(reg.get("total_fechado")) - valor_float(reg.get("valor_recebido_preservado")), 2)
        linhas += ["", f"Valor já registrado anteriormente: {_i8111_formatar_moeda(reg.get('valor_recebido_preservado'))}"]
        if diferenca > 0:
            linhas.append(f"Saldo adicional: {_i8111_formatar_moeda(diferenca)}")
        elif diferenca < 0:
            linhas.append(f"Crédito a favor do cliente: {_i8111_formatar_moeda(abs(diferenca))}")
        else:
            linhas.append("Correção sem diferença financeira.")
    linhas += ["", "Qualquer dúvida sobre este fechamento, estamos à disposição.", "AlphaFest Itatiba"]
    return "\n".join(linhas)


def gerar_html_fechamento_mensal(registro):
    reg = registro or {}
    empresa = carregar_config_empresa()
    logo_base64, logo_ext = encontrar_logo_base64()
    mime_logo = {".png":"image/png", ".jpg":"image/jpeg", ".jpeg":"image/jpeg", ".webp":"image/webp"}.get(logo_ext, "image/png")
    logo_html = f'<img class="logo" src="data:{mime_logo};base64,{logo_base64}" alt="AlphaFest">' if logo_base64 else '<div class="logo-text">AlphaFest</div>'
    linhas = []
    for item in reg.get("propostas") or []:
        linhas.append(
            '<tr><td>{}</td><td>{}</td><td class="money">{}</td></tr>'.format(
                html.escape(str(item.get("numero_proposta") or "")),
                html.escape(_i8111_formatar_data_iso(item.get("data_entrega"))),
                html.escape(_i8111_formatar_moeda(item.get("valor"))),
            )
        )
    obs = html.escape(str(reg.get("observacao_cliente") or "").strip())
