def _ler_bytes_midia(origem):
    """Converte uploads, bytes, caminhos, data URLs e URLs remotas em bytes.

    As imagens do catálogo podem estar salvas como caminho local, URL pública do
    Supabase ou data URL. O preview do Streamlit aceita todos esses formatos,
    mas o Pillow precisa receber os bytes reais do arquivo.
    """
    if origem is None:
        return b""
    if isinstance(origem, (bytes, bytearray, memoryview)):
        return bytes(origem)
    if hasattr(origem, "getbuffer"):
        try:
            return bytes(origem.getbuffer())
        except Exception:
            pass
    if hasattr(origem, "read"):
        try:
            posicao = origem.tell() if hasattr(origem, "tell") else None
            if hasattr(origem, "seek"):
                origem.seek(0)
            dados = origem.read()
            if posicao is not None and hasattr(origem, "seek"):
                origem.seek(posicao)
            if dados:
                return bytes(dados)
        except Exception:
            pass

    texto = str(origem).strip()
    if not texto:
        return b""

    if texto.startswith("data:image/") and "," in texto:
        try:
            cabecalho, conteudo = texto.split(",", 1)
            return base64.b64decode(conteudo) if ";base64" in cabecalho else urllib.parse.unquote_to_bytes(conteudo)
        except Exception:
            return b""

    if texto.lower().startswith(("http://", "https://")):
        try:
            resposta = requests.get(
                texto,
                timeout=20,
                allow_redirects=True,
                headers={"User-Agent": "FestManager/9.1 (+https://www.alphafest.com.br)"},
            )
            resposta.raise_for_status()
            tipo = str(resposta.headers.get("content-type", "")).lower()
            if tipo and not (tipo.startswith("image/") or "octet-stream" in tipo):
                return b""
            return resposta.content
        except Exception:
            return b""

    try:
        caminho = Path(texto)
        candidatos = [caminho]
        if not caminho.is_absolute():
            candidatos.extend([Path.cwd() / caminho, Path(__file__).resolve().parent / caminho])
        for candidato in candidatos:
            if candidato.exists() and candidato.is_file():
                return candidato.read_bytes()
    except Exception:
        pass
    return b""


def imagem_streamlit_catalogo(origem):
    """Normaliza a origem de uma imagem do catálogo para uso no st.image().

    Data URLs persistentes são decodificadas para bytes; URLs públicas e caminhos
    existentes continuam sendo entregues diretamente ao Streamlit.
    """
    if origem is None:
        return None
    texto = str(origem).strip() if not isinstance(origem, (bytes, bytearray, memoryview)) else ""
    if texto.startswith("data:image/"):
        bruto = _ler_bytes_midia(origem)
        return bruto or None
    if isinstance(origem, (bytes, bytearray, memoryview)):
        return bytes(origem)
    return origem

def converter_imagem_para_png(origem):
    """Aceita imagem enviada ou caminho e devolve PNG em bytes, preservando o original."""
    if Image is None:
        raise RuntimeError("Pillow não está instalado.")
    bruto = _ler_bytes_midia(origem)
    if not bruto:
        raise ValueError("Não foi possível ler a imagem selecionada.")
    with Image.open(io.BytesIO(bruto)) as img:
        img = ImageOps.exif_transpose(img).convert("RGBA")
        saida = io.BytesIO()
        img.save(saida, format="PNG", optimize=True)
        return saida.getvalue()

def _fonte_segura(tamanho=42, negrito=False):
    """Carrega a fonte portátil DejaVu distribuída pelo matplotlib."""
    if ImageFont is None:
        raise RuntimeError("Pillow/ImageFont não está disponível.")
    try:
        from alphafest_font_manager import get_font
        return get_font(max(8, int(tamanho)), bold=bool(negrito), serif=False, italic=False)
    except Exception as exc:
        raise RuntimeError(
            "Não foi possível carregar a fonte portátil. Confirme matplotlib>=3.8 "
            "no requirements.txt e reinicie o aplicativo."
        ) from exc

def _quebrar_texto(draw, texto, fonte, largura_max, limite_linhas=4):
    palavras = str(texto or "").split()
    linhas, atual = [], ""
    for palavra in palavras:
        teste = (atual + " " + palavra).strip()
        try:
            largura = draw.textbbox((0, 0), teste, font=fonte)[2]
        except Exception:
            largura = len(teste) * 12
        if largura <= largura_max or not atual:
            atual = teste
        else:
            linhas.append(atual)
            atual = palavra
            if len(linhas) >= limite_linhas:
                break
    if atual and len(linhas) < limite_linhas:
        linhas.append(atual)
    if len(linhas) == limite_linhas and len(" ".join(linhas)) < len(str(texto or "")):
        linhas[-1] = linhas[-1].rstrip(".,;:") + "…"
    return linhas

def _carregar_logo_alphafest(max_width=300):
    """Carrega a marca sem cartão branco e suaviza o fundo escuro do arquivo legado."""
    if Image is None:
        return None
    for caminho in (Path("logo.png"), Path("assets/logo.png")):
        try:
            if not caminho.exists():
                continue
            logo = Image.open(caminho).convert("RGBA")
            # O arquivo legado possui uma grande área escura ao redor da marca.
            # Recortamos a região central e convertemos os pixels escuros em transparência.
            w, h = logo.size
            recorte = logo.crop((int(w * .04), int(h * .12), int(w * .96), int(h * .88)))
            pixels = recorte.load()
            for y in range(recorte.height):
                for x in range(recorte.width):
                    r, g, b, a = pixels[x, y]
                    brilho = max(r, g, b)
                    minimo = min(r, g, b)
                    saturacao = brilho - minimo
                    if brilho < 38:
                        a = 0
                    elif brilho < 90 and saturacao < 24:
                        a = int(a * max(0, (brilho - 38) / 52))
                    elif brilho < 115:
                        a = int(a * max(.18, (brilho - 38) / 77))
                    pixels[x, y] = (r, g, b, a)
            bbox = recorte.getbbox()
            if bbox:
                recorte = recorte.crop(bbox)
            recorte.thumbnail((max_width, max_width), Image.Resampling.LANCZOS)
            return recorte
        except Exception:
            continue
    return None


def _desenhar_texto_centralizado(draw, texto, fonte, caixa, cor):
    bbox = draw.textbbox((0, 0), texto, font=fonte)
    tw, th = bbox[2] - bbox[0], bbox[3] - bbox[1]
    x1, y1, x2, y2 = caixa
    draw.text((x1 + (x2 - x1 - tw) // 2, y1 + (y2 - y1 - th) // 2 - bbox[1]), texto, font=fonte, fill=cor)


