def _thu_normalizar_campanha(valor):
    texto=str(valor or "").strip().casefold()
    mapa={
        "dia dos pais":"Dia dos Pais", "pais":"Dia dos Pais",
        "dia das mães":"Dia das Mães", "dia das maes":"Dia das Mães", "mães":"Dia das Mães", "maes":"Dia das Mães",
        "outubro rosa":"Outubro Rosa", "natal":"Natal", "páscoa":"Páscoa", "pascoa":"Páscoa",
        "dia das crianças":"Dia das Crianças", "dia das criancas":"Dia das Crianças",
        "halloween":"Halloween", "ano novo":"Ano Novo", "festa junina":"Festa Junina",
        "black friday":"Black Friday", "aniversário":"Aniversário", "aniversario":"Aniversário",
        "casamento":"Casamento", "batizado":"Batizado", "formatura":"Formatura",
    }
    for chave, oficial in mapa.items():
        if chave in texto:
            return oficial
    for opcao in CAMPANHAS_PRODUTO_OPCOES:
        if opcao.casefold()==texto:
            return opcao
    return str(valor or "").strip()

def thu_consultar_catalogo_produto(catalogo, consulta="", campanha=""):
    """20.4.9-C1 — relevância primeiro; elegibilidade de campanha depois."""
    def _norm(txt):
        import unicodedata
        txt = str(txt or "").strip().casefold()
        txt = unicodedata.normalize("NFKD", txt)
        return "".join(ch for ch in txt if not unicodedata.combining(ch))

    q = _norm(consulta)
    termos = [t for t in re.findall(r"[\w]+", q) if len(t) >= 2]
    stop = {"de", "da", "do", "das", "dos", "para", "com", "em", "e"}
    termos_relevantes = [t for t in termos if t not in stop]
    campanha_oficial = _thu_normalizar_campanha(campanha)
    encontrados = []

    for produto in catalogo or []:
        if produto.get("Ativo") is False:
            continue

        nome = _norm(produto.get("Nome"))
        aliases = [_norm(x) for x in (produto.get("Aliases", []) or []) if str(x).strip()]
        nomes_busca = [nome] + aliases
        categoria = _norm(produto.get("Categoria"))
        subcategoria = _norm(produto.get("Subcategoria"))
        descricao = _norm(
            " ".join(str(produto.get(k) or "") for k in ("Descricao","DescricaoCurta","DescricaoCompleta","PalavrasChave"))
        )

        # Regra de relevância:
        # 1) nome oficial OU alias exato é a melhor correspondência;
        # 2) frase no nome/alias vem logo depois;
        # 3) para várias palavras, usa o melhor nome/alias do produto.
        exato = bool(q and any(n == q for n in nomes_busca))
        frase_no_nome = bool(q and any(q in n for n in nomes_busca))
        nome_hits = max(
            [sum(1 for t in termos_relevantes if t in n) for n in nomes_busca] or [0]
        )
        apoio_hits = sum(1 for t in termos_relevantes if t in f"{categoria} {subcategoria} {descricao}")

        if termos_relevantes:
            if exato:
                classe = 3
            elif frase_no_nome:
                classe = 2
            elif len(termos_relevantes) == 1:
                classe = 1 if nome_hits == 1 else 0
            else:
                todos_no_nome = nome_hits == len(termos_relevantes)
                maioria_no_nome = nome_hits >= max(1, len(termos_relevantes) - 1)
                classe = 1 if (todos_no_nome or (maioria_no_nome and apoio_hits >= 1)) else 0
            if classe == 0:
                continue
        else:
            classe = 1

        permitidas = produto.get("CampanhasPermitidas", []) or []
        permanente = "Permanente / Todas as épocas" in permitidas
        elegivel = True
        if campanha_oficial:
            elegivel = permanente or campanha_oficial in permitidas

        pontos = classe * 1000 + nome_hits * 120 + apoio_hits * 20
        if produto.get("Destaque"):
            pontos += 15
        if permanente:
            pontos += 5

        encontrados.append((pontos, produto, elegivel, campanha_oficial, classe))

    # Relevância manda; elegibilidade não promove item irrelevante.
    encontrados.sort(key=lambda x: (x[0], x[2]), reverse=True)

    # Quando existe correspondência exata, ela deve ficar sozinha como melhor resposta.
    exatos = [x for x in encontrados if x[4] == 3]
    if exatos:
        return [(p, prod, eleg, camp) for p, prod, eleg, camp, _ in exatos]

    # Caso contrário, devolve apenas o nível de relevância mais alto encontrado.
    if encontrados:
        melhor_classe = max(x[4] for x in encontrados)
        encontrados = [x for x in encontrados if x[4] == melhor_classe]

    return [(p, prod, eleg, camp) for p, prod, eleg, camp, _ in encontrados]

def thu_correlacionar_catalogo_biblioteca(produto_catalogo, conteudos):
    """Procura artes pelo nome oficial e aliases confirmados no catálogo."""
    nome=str(produto_catalogo.get("Nome") or "").strip()
    categoria=str(produto_catalogo.get("Categoria") or "").strip()
    nomes=[nome] + [str(x).strip() for x in (produto_catalogo.get("Aliases", []) or []) if str(x).strip()]
    grupos_termos=[
        [t for t in re.findall(r"[\wÀ-ÿ]+", n.casefold()) if len(t)>=3]
        for n in nomes if n
    ]
    ranking=[]
    for arte in conteudos or []:
        texto=f"{arte.get('produto','')} {arte.get('categoria','')} {arte.get('campanha','')} {arte.get('tema_reuso','')}".casefold()
        acertos=max([sum(1 for t in termos if t in texto) for termos in grupos_termos] or [0])
        cat_match=bool(categoria and categoria.casefold() in texto)
        if acertos==0 and not cat_match:
            continue
        pontos=acertos*100+(35 if cat_match else 0)+(25 if arte.get("favorita") else 0)
        pontos+=min(int(arte.get("quantidade_reutilizacoes") or len(arte.get("historico_reutilizacoes") or []))*4,20)
        ranking.append((pontos,arte))
    ranking.sort(key=lambda x:x[0], reverse=True)
    return [a for _,a in ranking[:5]]


def thu_oportunidades_calendario(catalogo, conteudos, campanha_nome):
    """20.4.9-B — cruza campanha do Calendário com elegibilidade do Catálogo e artes da Biblioteca."""
    campanha=_thu_normalizar_campanha(campanha_nome)
    saida=[]
    for produto in catalogo or []:
        if produto.get("Ativo") is False:
            continue
        permitidas=produto.get("CampanhasPermitidas", []) or []
        elegivel=("Permanente / Todas as épocas" in permitidas) or (campanha in permitidas)
        if not elegivel:
            continue
        artes=thu_correlacionar_catalogo_biblioteca(produto, conteudos)
        saida.append({
            "produto": produto,
            "artes": artes,
            "tem_arte": bool(artes),
            "campanha": campanha,
        })
    saida.sort(key=lambda x:(x["tem_arte"], bool(x["produto"].get("Destaque")), str(x["produto"].get("Nome") or "")), reverse=True)
    return saida




def thu_priorizar_oportunidades(catalogo, conteudos, campanha_nome, dias_para_inicio=None):
    """20.4.9-I — classifica oportunidades sem inventar dados.

    O índice mede prontidão de divulgação, não previsão de vendas.
    Produtos com cadastro crítico incompleto nunca recebem status "Pronto para divulgar".
    """
    campanha = _thu_normalizar_campanha(campanha_nome)
    oportunidades = thu_oportunidades_calendario(catalogo, conteudos, campanha_nome)
    agora = agora_local()
    hoje = agora.date() if isinstance(agora, datetime) else hoje_local()

    def _data_uso_arte(valor):
        texto = str(valor or "").strip()
        if not texto:
            return None
        for formato in (
            "%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d %H:%M:%S", "%d/%m/%Y %H:%M", "%d/%m/%Y",
            "%Y-%m-%d",
        ):
            try:
                return datetime.strptime(texto[:26], formato).date()
            except (ValueError, TypeError):
                pass
        try:
            return datetime.fromisoformat(texto.replace("Z", "+00:00")).date()
        except (ValueError, TypeError):
            return None

    priorizadas = []
    for op in oportunidades:
        produto = op["produto"]
        artes = list(op.get("artes") or [])
        revisao = avaliar_pendencias_produto_catalogo(produto)
        criticas = list(revisao.get("criticas") or [])
        permitidas = list(produto.get("CampanhasPermitidas", []) or [])

        explicita = bool(campanha and campanha in permitidas)
        permanente = "Permanente / Todas as épocas" in permitidas
        arte = artes[0] if artes else None

        pontos = 0
        motivos = []
        alertas = []

        if not criticas:
            pontos += 42
            motivos.append("cadastro oficial completo")
        else:
            alertas.append("completar: " + ", ".join(criticas))

        if explicita:
            pontos += 14
            motivos.append("campanha marcada especificamente no Catálogo")
        elif permanente:
            pontos += 7
            motivos.append("produto permanente elegível")

        if arte:
            pontos += 28
            motivos.append("arte disponível")
            if arte.get("favorita"):
                pontos += 5
                motivos.append("arte favorita/oficial")

            reusos = int(
                arte.get("quantidade_reutilizacoes")
                or len(arte.get("historico_reutilizacoes") or [])
                or 0
            )
            if reusos:
                motivos.append(f"arte já reutilizada {reusos}x")

            ultima = _data_uso_arte(arte.get("ultima_reutilizacao_em"))
            if ultima:
                dias_sem_uso = (hoje - ultima).days
                if dias_sem_uso <= 14:
                    pontos -= 12
                    alertas.append(f"arte usada há {max(dias_sem_uso, 0)} dia(s)")
                elif dias_sem_uso <= 30:
                    pontos -= 6
                    alertas.append(f"arte usada há {dias_sem_uso} dias")
                elif dias_sem_uso >= 45:
                    pontos += 6
                    motivos.append("arte sem uso recente")
            else:
                pontos += 4
                motivos.append("sem reutilização recente registrada")
        else:
            alertas.append("falta arte aprovada na Biblioteca")

        if produto.get("Destaque"):
            pontos += 5
            motivos.append("produto em destaque")

        pontos = max(0, min(100, int(pontos)))

        pronto_cadastro = not criticas
        pronto_divulgar = pronto_cadastro and bool(arte)

        if pronto_divulgar:
            if dias_para_inicio is not None and int(dias_para_inicio) <= 30:
                prioridade = "Alta"
            else:
                prioridade = "Média"
            status = "Pronto para divulgar"
            icone = "🟢"
        elif pronto_cadastro:
            prioridade = "Preparar arte"
            status = "Cadastro pronto, falta arte"
            icone = "🟡"
        else:
            prioridade = "Revisar cadastro"
            status = "Cadastro incompleto"
            icone = "🟠"

        priorizadas.append({
            **op,
            "arte_recomendada": arte,
            "indice_prontidao": pontos,
            "motivos_prioridade": motivos,
            "alertas_prioridade": alertas,
            "criticas_cadastro": criticas,
            "pronto_cadastro": pronto_cadastro,
            "pronto_divulgar": pronto_divulgar,
            "prioridade_thu": prioridade,
            "status_thu": status,
            "icone_thu": icone,
            "dias_para_inicio": dias_para_inicio,
        })

    priorizadas.sort(
        key=lambda x: (
            bool(x.get("pronto_divulgar")),
            bool(x.get("pronto_cadastro")),
            int(x.get("indice_prontidao") or 0),
            bool(x.get("tem_arte")),
            bool((x.get("produto") or {}).get("Destaque")),
            str((x.get("produto") or {}).get("Nome") or "").casefold(),
        ),
        reverse=True,
    )
    return priorizadas



