def _thu_site_norm(valor):
    import unicodedata
    texto = unicodedata.normalize("NFKD", str(valor or "").strip())
    texto = "".join(c for c in texto if not unicodedata.combining(c)).casefold()
    texto = re.sub(r"[^a-z0-9]+", " ", texto)
    return " ".join(texto.split())


def _thu_site_url_segura(url, imagem=False):
    try:
        p = urllib.parse.urlparse(str(url or "").strip())
    except Exception:
        return False
    host = (p.hostname or "").casefold()
    if p.scheme not in ("http", "https"):
        return False
    if imagem:
        return (
            host in {"alphafest.com.br", "www.alphafest.com.br"}
            or host.endswith(".wixstatic.com")
            or host == "static.wixstatic.com"
        )
    return host in {"alphafest.com.br", "www.alphafest.com.br"}


def _thu_site_url_absoluta(url, base=ALPHAFEST_SITE_BASE):
    valor = urllib.parse.urljoin(base.rstrip("/") + "/", str(url or "").strip())
    parsed = urllib.parse.urlparse(valor)
    # Remove fragmentos e parâmetros de marketing; preserva query somente se indispensável.
    path = parsed.path or "/"
    return urllib.parse.urlunparse(("https", "www.alphafest.com.br", path, "", "", ""))


def _thu_site_classificar_link(texto, url):
    """Classificação inicial do link; a classificação final usa o conteúdo da página."""
    t = _thu_site_norm(texto)
    path = _thu_site_norm(urllib.parse.urlparse(str(url or "")).path.replace("/", " "))

    for chave, oficial in ALPHAFEST_SITE_CAMPANHAS.items():
        if chave == t or chave in t or chave in path:
            return "campanha", oficial

    if t in ALPHAFEST_SITE_RAIZES or not t:
        return "estrutura", ""
    if t in ALPHAFEST_SITE_CATEGORIAS:
        return "categoria", ""
    if t in ALPHAFEST_SITE_SERVICOS:
        return "servico", ""
    if t in ALPHAFEST_SITE_PRODUTOS_SEGUROS:
        return "produto", ""

    # Uma página específica dentro de "personalizados" é candidata a produto,
    # mas só recebe cadastro automático habilitado depois da classificação final.
    if "personalizados" in path:
        return "produto", ""

    return "estrutura", ""


class _ThuAlphaSiteParser:
    """Parser HTML mínimo usando apenas biblioteca padrão; evita nova dependência."""
    def __init__(self):
        from html.parser import HTMLParser

        outer = self

        class Parser(HTMLParser):
            def __init__(self):
                super().__init__(convert_charrefs=True)
                self.capture = None
                self.buffer = []
                self.anchor_href = ""
                self.anchor_buffer = []

            def handle_starttag(self, tag, attrs):
                attrs = dict(attrs or [])
                tag = str(tag).casefold()
                if tag in ("title", "h1", "h2", "h3"):
                    self.capture = tag
                    self.buffer = []
                if tag == "a":
                    self.anchor_href = str(attrs.get("href") or "").strip()
                    self.anchor_buffer = []
                if tag == "img":
                    src = (
                        attrs.get("src")
                        or attrs.get("data-src")
                        or attrs.get("data-image-info")
                        or ""
                    )
                    srcset = str(attrs.get("srcset") or "")
                    if srcset:
                        candidatos = []
                        for parte in srcset.split(","):
                            pedacos = parte.strip().split()
                            if not pedacos:
                                continue
                            url_cand = pedacos[0]
                            largura = 0
                            if len(pedacos) > 1 and pedacos[1].endswith("w"):
                                try:
                                    largura = int(pedacos[1][:-1])
                                except Exception:
                                    largura = 0
                            candidatos.append((largura, url_cand))
                        if candidatos:
                            candidatos.sort(key=lambda x: x[0])
                            src = candidatos[-1][1] or src
                    alt = str(attrs.get("alt") or "").strip()
                    if src:
                        outer.images.append({"url": str(src).strip(), "alt": alt})
                if tag == "meta":
                    prop = str(attrs.get("property") or attrs.get("name") or "").casefold()
                    content = str(attrs.get("content") or "").strip()
                    if prop in ("og:image", "twitter:image") and content:
                        outer.images.append({"url": content, "alt": "Imagem da página"})

            def handle_data(self, data):
                texto = str(data or "")
                if self.capture:
                    self.buffer.append(texto)
                if self.anchor_href:
                    self.anchor_buffer.append(texto)

            def handle_endtag(self, tag):
                tag = str(tag).casefold()
                if self.capture == tag:
                    texto = " ".join("".join(self.buffer).split())
                    if texto:
                        if tag == "title":
                            outer.title = texto
                        else:
                            outer.headings.append(texto)
                    self.capture = None
                    self.buffer = []
                if tag == "a" and self.anchor_href:
                    texto = " ".join("".join(self.anchor_buffer).split())
                    outer.links.append({
                        "url": self.anchor_href,
                        "texto": texto,
                    })
                    self.anchor_href = ""
                    self.anchor_buffer = []

        self.parser = Parser()
        self.title = ""
        self.headings = []
        self.links = []
        self.images = []

    def feed(self, html_text):
        self.parser.feed(html_text)


def _thu_site_url_imagem_original(url):
    """Retorna a melhor URL disponível; em Wix remove transformações /v1/... para acessar o arquivo original."""
    valor = str(url or "").strip()
    if not valor:
        return ""
    try:
        p = urllib.parse.urlparse(valor)
    except Exception:
        return valor

    host = (p.hostname or "").casefold()
    if "wixstatic.com" not in host:
        return valor

    path = urllib.parse.unquote(p.path or "")
    achou = re.search(r"(/media/[^/]+)", path)
    if not achou:
        return valor

    original_path = achou.group(1)
    return urllib.parse.urlunparse((
        p.scheme or "https",
        p.netloc,
        original_path,
        "",
        "",
        "",
    ))


def _thu_site_identidade_imagem(url):
    """Normaliza URL para reconhecer a mesma imagem Wix em páginas diferentes."""
    try:
        p = urllib.parse.urlparse(str(url or "").strip())
    except Exception:
        return ""
    host = (p.hostname or "").casefold()
    path = urllib.parse.unquote(p.path or "")
    if "wixstatic.com" in host:
        achou = re.search(r"/media/([^/]+)", path)
        if achou:
            return f"wix:{achou.group(1).casefold()}"
    return f"{host}:{path.casefold().rstrip('/')}"


def _thu_site_imagem_global_obvia(url, alt=""):
    alt_n = _thu_site_norm(alt)
    url_n = str(url or "").casefold()
    marcadores_alt = {
        "logo", "alpha fest", "alphafest", "alphafest itatiba",
        "facebook", "instagram", "tiktok", "whatsapp", "youtube",
    }
    if any(m in alt_n for m in marcadores_alt):
        return True
    if any(m in url_n for m in ("favicon", "/logo", "logo.", "social-icon")):
        return True
    return False


def _thu_site_filtrar_imagens(imagens, limite=18):
    saida = []
    vistos = set()
    for item in imagens or []:
        url = str((item or {}).get("url") or "").strip()
        alt = str((item or {}).get("alt") or "").strip()
        if not url:
            continue
        if url.startswith("//"):
            url = "https:" + url
        elif url.startswith("/"):
            url = urllib.parse.urljoin(ALPHAFEST_SITE_BASE, url)
        if not _thu_site_url_segura(url, imagem=True):
            continue
        if _thu_site_imagem_global_obvia(url, alt):
            continue

        original_url = _thu_site_url_imagem_original(url)
        chave = _thu_site_identidade_imagem(original_url or url) or url.split("?")[0]
        if chave in vistos:
            continue
        vistos.add(chave)
        saida.append({
            "url": url,
            "original_url": original_url or url,
            "alt": alt or Path(urllib.parse.urlparse(url).path).name or "Imagem",
            "identidade": chave,
        })
        if len(saida) >= limite:
            break
    return saida


def _thu_site_limpar_imagens_repetidas(paginas):
    """Remove ativos globais repetidos em muitas páginas, como logo/cabeçalho."""
    paginas = [dict(p) for p in (paginas or [])]
    validas = [p for p in paginas if p.get("ok")]
    if not validas:
        return paginas, []

    frequencia = {}
    for pagina in validas:
        ids_pagina = set()
        for img in (pagina.get("imagens") or []):
            ident = str(img.get("identidade") or _thu_site_identidade_imagem(img.get("url")) or "")
            if ident:
                ids_pagina.add(ident)
        for ident in ids_pagina:
            frequencia[ident] = frequencia.get(ident, 0) + 1

    # Só considera ativo global quando aparece em pelo menos 5 páginas e em >=35% do scan.
    limite_global = max(5, int((len(validas) * 35 + 99) // 100))
    globais = {ident for ident, qtd in frequencia.items() if qtd >= limite_global}

    for pagina in paginas:
        imagens = list(pagina.get("imagens") or [])
        limpas = []
        removidas = 0
        for img in imagens:
            ident = str(img.get("identidade") or _thu_site_identidade_imagem(img.get("url")) or "")
            if ident in globais or _thu_site_imagem_global_obvia(img.get("url"), img.get("alt")):
                removidas += 1
                continue
            limpas.append(img)
        pagina["imagens"] = limpas
        pagina["imagens_globais_removidas"] = removidas

    return paginas, sorted(globais)


def _thu_site_fetch(url, timeout=12):
    """Lê uma página pública do domínio oficial, sem executar JavaScript."""
    url = _thu_site_url_absoluta(url)
    if not _thu_site_url_segura(url):
        return {"ok": False, "url": url, "erro": "URL fora do domínio AlphaFest."}
    try:
        r = requests.get(
            url,
            timeout=timeout,
            allow_redirects=True,
            headers={
                "User-Agent": "AlphaFestManager/20.4.9-I3.1 (+acervo interno; alphafest.com.br)"
            },
        )
        r.raise_for_status()
        ctype = str(r.headers.get("Content-Type") or "").casefold()
        if "text/html" not in ctype:
            return {"ok": False, "url": url, "erro": "A página não retornou HTML."}
        conteudo = r.content[:4_000_000]
        texto = conteudo.decode(r.encoding or "utf-8", errors="ignore")

        parser = _ThuAlphaSiteParser()
        parser.feed(texto)

        links = []
        vistos_links = set()
        for link in parser.links:
            href = str(link.get("url") or "").strip()
            if not href or href.startswith(("#", "mailto:", "tel:", "javascript:")):
                continue
            absoluto = _thu_site_url_absoluta(href, url)
            if not _thu_site_url_segura(absoluto):
                continue
            if absoluto in vistos_links:
                continue
            vistos_links.add(absoluto)
            links.append({"url": absoluto, "texto": str(link.get("texto") or "").strip()})

        return {
            "ok": True,
            "url": url,
            "titulo_html": parser.title,
            "headings": list(dict.fromkeys(parser.headings))[:15],
            "links": links[:120],
            "imagens": _thu_site_filtrar_imagens(parser.images, limite=18),
            "lido_em": agora_local().isoformat(timespec="seconds"),
        }
    except requests.RequestException as exc:
        return {"ok": False, "url": url, "erro": f"Não foi possível acessar a página: {type(exc).__name__}"}
    except Exception as exc:
        return {"ok": False, "url": url, "erro": f"Falha ao interpretar página: {type(exc).__name__}"}


def _thu_site_nome_pagina(pagina, fallback=""):
    """Prefere o nome específico do menu e ignora headings genéricos como 'Páginas'."""
    pagina = pagina or {}
    fallback = str(fallback or "").strip()

    if fallback and _thu_site_norm(fallback) not in ALPHAFEST_SITE_TITULOS_GENERICOS:
        return fallback

    headings = list(pagina.get("headings") or [])
    for h in headings:
        h = str(h or "").strip()
        if (
            h
            and _thu_site_norm(h) not in ALPHAFEST_SITE_TITULOS_GENERICOS
            and len(h) <= 120
        ):
            return h

    titulo = str(pagina.get("titulo_html") or "").split("|")[0].strip()
    if titulo and _thu_site_norm(titulo) not in ALPHAFEST_SITE_TITULOS_GENERICOS:
        return titulo

    # Último recurso: transforma o slug em título legível.
    slug = urllib.parse.urlparse(str(pagina.get("url") or "")).path.rstrip("/").split("/")[-1]
    slug = urllib.parse.unquote(slug).replace("-", " ").replace("_", " ").strip()
    return slug.title() if slug else (fallback or "Página do site")


def _thu_site_classificar_pagina(pagina, fallback=""):
    """Classifica Produto/Categoria/Serviço/Campanha com motivo e confiança."""
    pagina = pagina or {}
    nome = _thu_site_nome_pagina(pagina, fallback)
    candidatos = [
        nome,
        str(fallback or ""),
        str(pagina.get("titulo_html") or "").split("|")[0].strip(),
        *[str(x or "").strip() for x in (pagina.get("headings") or [])[:6]],
    ]
    norm_candidatos = [x for x in {_thu_site_norm(c) for c in candidatos if c} if x]
    path = _thu_site_norm(urllib.parse.urlparse(str(pagina.get("url") or "")).path.replace("/", " "))

    for cand in norm_candidatos + [path]:
        for chave, oficial in ALPHAFEST_SITE_CAMPANHAS.items():
            if chave == cand or chave in cand:
                return {
                    "tipo": "campanha",
                    "campanha": oficial,
                    "confianca": 1.0,
                    "motivo": "data/campanha reconhecida no acervo",
                }

    for cand in norm_candidatos:
        if cand in ALPHAFEST_SITE_CATEGORIAS:
            return {
                "tipo": "categoria",
                "campanha": "",
                "confianca": 0.99,
                "motivo": "linha/categoria conhecida do site",
            }
        if cand in ALPHAFEST_SITE_SERVICOS:
            return {
                "tipo": "servico",
                "campanha": "",
                "confianca": 0.99,
                "motivo": "serviço conhecido do site",
            }
        if cand in ALPHAFEST_SITE_PRODUTOS_SEGUROS:
            return {
                "tipo": "produto",
                "campanha": "",
                "confianca": 0.99,
                "motivo": "produto específico conhecido do acervo",
            }

    if any(c in ALPHAFEST_SITE_RAIZES for c in norm_candidatos):
        return {
            "tipo": "estrutura",
            "campanha": "",
            "confianca": 0.98,
            "motivo": "página estrutural do site",
        }

    # Página específica em /personalizados-xxx: forte candidata a produto,
    # desde que o nome não seja genérico.
    nome_n = _thu_site_norm(nome)
    if (
        "personalizados" in path
        and nome_n
        and nome_n not in ALPHAFEST_SITE_TITULOS_GENERICOS
    ):
        return {
            "tipo": "produto",
            "campanha": "",
            "confianca": 0.86,
            "motivo": "página específica dentro da área de personalizados",
        }

    return {
        "tipo": "estrutura",
        "campanha": "",
        "confianca": 0.50,
        "motivo": "página não classificada com segurança",
    }


def thu_site_sugerir_produto(nome_pagina, catalogo, alternativas=None):
    """Sugere correspondência usando nome, menu, título e headings; nunca grava sozinho."""
    from difflib import SequenceMatcher

    nomes_busca = [str(nome_pagina or "").strip()]
    nomes_busca.extend(str(x or "").strip() for x in (alternativas or []) if str(x or "").strip())
    nomes_busca = list(dict.fromkeys([x for x in nomes_busca if x]))

    mapa = mapa_identidade_produtos(catalogo)
    for nome in nomes_busca:
        chave = normalizar_identidade_produto(nome)
        if chave in mapa:
            oficial = mapa[chave]
            idx = next(
                (
                    i for i, p in enumerate(catalogo or [])
                    if normalizar_identidade_produto(p.get("Nome"))
                    == normalizar_identidade_produto(oficial)
                ),
                None,
            )
            return {
                "status": "oficial",
                "nome": oficial,
                "indice": idx,
                "score": 1.0,
                "origem_match": nome,
            }

    stop = {
        "personalizado", "personalizada", "personalizados", "personalizadas",
        "ceramica", "produto", "produtos", "linha", "colecao",
    }

    def canon_token(token):
        t = str(token or "")
        if len(t) > 5 and t.endswith("oes"):
            return t[:-3] + "ao"
        if len(t) > 4 and t.endswith("s"):
            return t[:-1]
        return t

    def flex(v):
        termos = [
            canon_token(x)
            for x in normalizar_identidade_produto(v).split()
            if x not in stop
        ]
        return " ".join([x for x in termos if x])

    pares_busca = [
        (nome, flex(nome))
        for nome in nomes_busca
        if flex(nome)
    ]
    alvos = [alvo for _, alvo in pares_busca]
    melhor = {
        "status": "ausente",
        "nome": "",
        "indice": None,
        "score": 0.0,
        "origem_match": "",
    }

    for i, produto in enumerate(catalogo or []):
        candidatos = [str(produto.get("Nome") or "")] + [
            str(x) for x in (produto.get("Aliases", []) or [])
        ]
        for candidato in candidatos:
            base = flex(candidato)
            if not base:
                continue
            for origem, alvo in pares_busca:
                seq = SequenceMatcher(None, alvo, base).ratio()
                ta, tb = set(alvo.split()), set(base.split())
                jac = len(ta & tb) / max(len(ta | tb), 1)

                # Se todos os termos úteis de um lado estão contidos no outro,
                # aumenta a confiança sem depender só da distância textual.
                subset = 1.0 if (ta and tb and (ta <= tb or tb <= ta)) else 0.0
                score = max(seq, (seq * 0.55 + jac * 0.30 + subset * 0.15))

                if score > melhor["score"]:
                    melhor = {
                        "status": "provavel" if score >= 0.82 else "ausente",
                        "nome": str(produto.get("Nome") or ""),
                        "indice": i,
                        "score": score,
                        "origem_match": origem,
                    }

    if melhor["status"] != "provavel":
        melhor["nome"] = ""
        melhor["indice"] = None
        melhor["origem_match"] = ""
    return melhor


def thu_site_reprocessar_scan(scan):
    """Aplica regras I3.1 também em scans antigos já armazenados."""
    scan = dict(scan or {})
    paginas = []

    for original in (scan.get("paginas") or []):
        if not isinstance(original, dict):
            continue
        pagina = dict(original)
        fallback = str(pagina.get("texto_menu") or "").strip()
        pagina["nome"] = _thu_site_nome_pagina(pagina, fallback)
        cls = _thu_site_classificar_pagina(pagina, fallback)
        pagina["tipo"] = cls["tipo"]
        pagina["campanha"] = cls.get("campanha") or pagina.get("campanha") or ""
        pagina["classificacao_confianca"] = cls["confianca"]
        pagina["classificacao_motivo"] = cls["motivo"]
        # Reaplica filtro óbvio a scans antigos.
        pagina["imagens"] = _thu_site_filtrar_imagens(
            pagina.get("imagens") or [],
            limite=18,
        )
        paginas.append(pagina)

    paginas, globais = _thu_site_limpar_imagens_repetidas(paginas)
    scan["paginas"] = paginas
    scan["ativos_globais_filtrados"] = len(globais)
    scan["regra_acervo"] = "20.4.9-I3.1"
    return scan


def thu_site_analisar_acervo(max_paginas=42):
    """Descobre links no menu público e analisa páginas em paralelo, com limite."""
    home = _thu_site_fetch(ALPHAFEST_SITE_BASE)
    if not home.get("ok"):
        return {
            "ok": False,
            "erro": home.get("erro") or "Não foi possível ler o site.",
            "paginas": [],
            "lido_em": agora_local().isoformat(timespec="seconds"),
        }

    candidatos = []
    vistos = set()
    for link in home.get("links", []):
        url = str(link.get("url") or "")
        texto = str(link.get("texto") or "").strip()
        if not url or url in vistos:
            continue
        tipo, campanha = _thu_site_classificar_link(texto, url)
        if tipo == "estrutura" and _thu_site_norm(texto) in {
            "alpha fest", "contato", "quem somos", "loja", "mais itens"
        }:
            continue
        vistos.add(url)
        candidatos.append({
            "url": url,
            "texto_menu": texto,
            "tipo": tipo,
            "campanha": campanha,
        })

    # Prioriza produtos/campanhas e evita varrer o site inteiro sem necessidade.
    prioridade = {"produto": 0, "campanha": 1, "categoria": 2, "servico": 2, "estrutura": 3}
    candidatos.sort(key=lambda x: (prioridade.get(x["tipo"], 9), str(x["texto_menu"]).casefold()))
    candidatos = candidatos[:max(1, int(max_paginas))]

    resultados = {}
    try:
        from concurrent.futures import ThreadPoolExecutor, as_completed
        with ThreadPoolExecutor(max_workers=min(6, max(1, len(candidatos)))) as pool:
            futuros = {pool.submit(_thu_site_fetch, c["url"], 12): c for c in candidatos}
            for futuro in as_completed(futuros):
                meta = futuros[futuro]
                try:
                    pagina = futuro.result()
                except Exception as exc:
                    pagina = {"ok": False, "url": meta["url"], "erro": type(exc).__name__}
                resultados[meta["url"]] = {**meta, **pagina}
    except Exception:
        for meta in candidatos:
            resultados[meta["url"]] = {**meta, **_thu_site_fetch(meta["url"], 12)}

    paginas = []
    for meta in candidatos:
        pagina = resultados.get(meta["url"], dict(meta))
        pagina["texto_menu"] = meta.get("texto_menu") or pagina.get("texto_menu") or ""
        paginas.append(pagina)

    scan = {
        "ok": True,
        "base": ALPHAFEST_SITE_BASE,
        "paginas": paginas,
        "lido_em": agora_local().isoformat(timespec="seconds"),
        "home": {
            "titulo": home.get("titulo_html"),
            "url": home.get("url"),
        },
    }
    return thu_site_reprocessar_scan(scan)


def _thu_site_baixar_imagem(url, nome_ref="imagem_site", fallback_url=""):
    candidatos = []
    original = _thu_site_url_imagem_original(url)
    for cand in (original, url, fallback_url):
        cand = str(cand or "").strip()
        if cand and cand not in candidatos and _thu_site_url_segura(cand, imagem=True):
            candidatos.append(cand)

    if not candidatos:
        return None, "URL de imagem não autorizada."

    ultimo_erro = "Não foi possível baixar a imagem do site."
    for candidato in candidatos:
        try:
            r = requests.get(
                candidato,
                timeout=25,
                allow_redirects=True,
                headers={
                    "User-Agent": "AlphaFestManager/20.4.9-I3.2.1",
                    "Accept": "image/jpeg,image/png,image/webp;q=0.9,*/*;q=0.5",
                },
                stream=True,
            )
            r.raise_for_status()
            ctype = str(r.headers.get("Content-Type") or "").split(";")[0].strip().casefold()
            permitidos = {"image/png": "png", "image/jpeg": "jpg", "image/webp": "webp"}
            if ctype not in permitidos:
                ultimo_erro = "O arquivo remoto não é PNG/JPG/WEBP."
                continue

            content = r.content
            if len(content) > 25 * 1024 * 1024:
                ultimo_erro = "A imagem original ultrapassa 25 MB."
                continue

            ext = permitidos[ctype]

            largura = 0
            altura = 0
            try:
                from PIL import Image
                from io import BytesIO
                with Image.open(BytesIO(content)) as _im_thu:
                    largura, altura = _im_thu.size
            except Exception:
                largura, altura = 0, 0

            nome_limpo = re.sub(r"[^A-Za-z0-9_-]+", "_", str(nome_ref or "imagem_site"))[:80]
            upload = _DriveImageUpload(content, f"{nome_limpo}.{ext}", ctype)

            # Metadados auxiliares usados para auditoria de qualidade/origem.
            try:
                upload._thu_origem_url = candidato
                upload._thu_bytes = len(content)
                upload._thu_largura = int(largura or 0)
                upload._thu_altura = int(altura or 0)
                upload._thu_original = (
                    candidato == _thu_site_url_imagem_original(candidato)
                )
            except Exception:
                pass
            return upload, ""
        except requests.RequestException:
            ultimo_erro = "Não foi possível baixar uma das versões da imagem."
            continue
        except Exception:
            ultimo_erro = "Falha ao preparar a imagem para importação."
            continue

    return None, ultimo_erro


@st.dialog("🌐 Assistente THU • Importar imagens do Site AlphaFest", width="large")
def dialog_thu_importar_imagens_site(pagina):
    catalogo = carregar_catalogo()
    pagina = dict(pagina or {})
    nome_pagina = str(pagina.get("nome") or pagina.get("texto_menu") or "Página do site")
    imagens = list(pagina.get("imagens") or [])
    sugestao = thu_site_sugerir_produto(
        nome_pagina,
        catalogo,
        alternativas=[
            pagina.get("texto_menu", ""),
            pagina.get("titulo_html", ""),
            *(pagina.get("headings") or [])[:5],
        ],
    )

    st.markdown(f"### {nome_pagina}")
    st.caption(
        "Origem: Site AlphaFest legado. A prévia pode ser reduzida, mas na importação o THU tenta baixar o arquivo original do Wix em maior resolução. Nada é salvo sem confirmação."
    )

    nomes_oficiais = [str(p.get("Nome") or "").strip() for p in catalogo if str(p.get("Nome") or "").strip()]
    opcoes = ["— Escolha o produto oficial —"] + nomes_oficiais
    pre = sugestao.get("nome") if sugestao.get("status") in ("oficial", "provavel") else ""
    idx_pre = opcoes.index(pre) if pre in opcoes else 0
    produto_escolhido = st.selectbox(
        "Produto oficial do Catálogo",
        opcoes,
        index=idx_pre,
        key=f"thu_site_produto_{abs(hash(pagina.get('url','')))}",
    )

    if sugestao.get("status") == "provavel":
        st.info(
            f"💡 Possível correspondência: **{sugestao.get('nome')}** ({sugestao.get('score',0)*100:.0f}%). "
            "Confirme visualmente antes de importar."
        )
    elif sugestao.get("status") == "ausente":
        st.warning("Não encontrei correspondência segura no Catálogo.")

    if not imagens:
        st.info("Nenhuma imagem de produto utilizável foi encontrada nesta página.")
        return

    selecionadas = []
    st.markdown("#### Escolha as imagens")
    for pos in range(0, min(len(imagens), 12), 3):
        cols = st.columns(3)
        for desloc, img in enumerate(imagens[pos:pos+3]):
            real_pos = pos + desloc
            with cols[desloc]:
                try:
                    _preview_hd = (
                        img.get("original_url")
                        or _thu_site_url_imagem_original(img.get("url"))
                        or img.get("url")
                    )
                    st.image(_preview_hd, use_container_width=True)
                    if _preview_hd != img.get("url"):
                        st.caption("Prévia em maior resolução do arquivo original")
                except Exception:
                    try:
                        st.image(img.get("url"), use_container_width=True)
                        st.caption("Prévia reduzida • o original será tentado na importação")
                    except Exception:
                        st.caption("Prévia indisponível")
                rotulo = str(img.get("alt") or f"Imagem {real_pos+1}")[:55]
                if st.checkbox(
                    f"Importar • {rotulo}",
                    key=f"thu_site_img_{abs(hash(pagina.get('url','')))}_{real_pos}",
                ):
                    selecionadas.append(img)

    modo = st.selectbox(
        "Como salvar no banco de imagens?",
        [
            "Adicionar como referências históricas",
            "Adicionar e usar a primeira como foto principal",
            "Salvar como variação histórica",
        ],
        key=f"thu_site_modo_{abs(hash(pagina.get('url','')))}",
    )
    observacao = st.text_input(
        "Observação (opcional)",
        placeholder="Ex.: acervo antigo, modelo anterior, referência de estampa...",
        key=f"thu_site_obs_{abs(hash(pagina.get('url','')))}",
    )

    if st.button(
        "💾 Importar imagens selecionadas",
        type="primary",
        use_container_width=True,
        disabled=(produto_escolhido == "— Escolha o produto oficial —" or not selecionadas),
        key=f"thu_site_importar_{abs(hash(pagina.get('url','')))}",
    ):
        idx_prod = next(
            (
                i for i, p in enumerate(catalogo)
                if normalizar_identidade_produto(p.get("Nome"))
                == normalizar_identidade_produto(produto_escolhido)
            ),
            None,
        )
        if idx_prod is None:
            st.error("Produto oficial não localizado.")
            return

        caminhos = []
        erros = []
        avisos_resolucao = []
        fontes = []
        for pos, img in enumerate(selecionadas, 1):
            upload, erro = _thu_site_baixar_imagem(
                img.get("original_url") or img.get("url"),
                nome_ref=f"site_{produto_escolhido}_{pos}",
                fallback_url=img.get("url"),
            )
            if erro:
                erros.append(erro)
                continue
            caminho = salvar_upload_catalogo(upload)
            if caminho:
                caminhos.append(caminho)

                _lw = int(getattr(upload, "_thu_largura", 0) or 0)
                _lh = int(getattr(upload, "_thu_altura", 0) or 0)
                if _lw and _lh and max(_lw, _lh) < 900:
                    avisos_resolucao.append(
                        f"{img.get('alt') or f'Imagem {pos}'}: {_lw}×{_lh}px"
                    )

                fontes.append({
                    "url_origem": str(img.get("url") or ""),
                    "url_original": str(img.get("original_url") or img.get("url") or ""),
                    "alt": str(img.get("alt") or ""),
                    "bytes_importados": int(getattr(upload, "_thu_bytes", 0) or 0),
                    "largura_importada": int(getattr(upload, "_thu_largura", 0) or 0),
                    "altura_importada": int(getattr(upload, "_thu_altura", 0) or 0),
                })
            else:
                erros.append("Uma das imagens não pôde ser gravada no armazenamento.")

        if not caminhos:
            st.error("Nenhuma imagem foi importada. " + " ".join(dict.fromkeys(erros)))
            return

        produto = dict(catalogo[idx_prod])
        atuais = list(produto.get("Imagens", []) or [])

        if modo == "Adicionar e usar a primeira como foto principal":
            produto["Imagens"] = list(dict.fromkeys(caminhos + atuais))
            acao = "Acervo do site — nova foto principal"
        else:
            produto["Imagens"] = list(dict.fromkeys(atuais + caminhos))
            acao = (
                "Acervo do site — variação histórica"
                if modo == "Salvar como variação histórica"
                else "Acervo do site — referências históricas"
            )

        hist = list(produto.get("BancoImagensHistorico", []) or [])
        hist.append({
            "origem": "Site AlphaFest legado",
            "pagina": str(pagina.get("url") or ""),
            "titulo_pagina": nome_pagina,
            "acao": acao,
            "fotos": caminhos,
            "fontes": fontes,
            "observacao": str(observacao or "").strip(),
            "adicionado_em": agora_local().isoformat(timespec="seconds"),
            "usuario": obter_usuario_atual(),
        })
        produto["BancoImagensHistorico"] = hist[-150:]

        fontes_hist = list(produto.get("FontesHistoricas", []) or [])
        fonte_pagina = {
            "origem": "Site AlphaFest legado",
            "url": str(pagina.get("url") or ""),
            "titulo": nome_pagina,
            "registrado_em": agora_local().isoformat(timespec="seconds"),
        }
        if not any(str(x.get("url") or "") == fonte_pagina["url"] for x in fontes_hist if isinstance(x, dict)):
            fontes_hist.append(fonte_pagina)
        produto["FontesHistoricas"] = fontes_hist[-100:]

        if modo == "Salvar como variação histórica":
            variacoes = list(produto.get("VariacoesImagem", []) or [])
            variacoes.append({
                "origem": "Site AlphaFest legado",
                "pagina": str(pagina.get("url") or ""),
                "fotos": caminhos,
                "descricao": str(observacao or "").strip() or f"Variação histórica — {nome_pagina}",
                "criado_em": agora_local().isoformat(timespec="seconds"),
            })
            produto["VariacoesImagem"] = variacoes[-150:]

        produto["AtualizadoEm"] = agora_local().isoformat(timespec="seconds")
        catalogo[idx_prod] = produto
        salvar_catalogo(catalogo)
        st.session_state["_thu_auditar_produto_nome"] = produto_escolhido
        st.session_state["_mensagem_sucesso_pendente"] = (
            f"THU: {len(caminhos)} imagem(ns) do acervo do site adicionada(s) a {produto_escolhido}."
        )
        if erros:
            st.warning("Algumas imagens não foram importadas: " + " ".join(dict.fromkeys(erros)))
        if avisos_resolucao:
            st.session_state["_thu_site_aviso_resolucao_i321"] = (
                "Alguns arquivos originais do site já são pequenos: "
                + " • ".join(avisos_resolucao[:6])
                + ". O THU preservou a resolução real e não fez upscale artificial."
            )
        st.rerun()


def thu_montar_campanha_catalogo(produto, campanha_nome, arte=None, objetivo="Vender"):
    """20.4.9-C — monta briefing/copy usando exclusivamente dados oficiais do Catálogo."""
    nome=str(produto.get("Nome") or "Produto").strip()
    descricao=str(produto.get("DescricaoCompleta") or produto.get("DescricaoCurta") or produto.get("Descricao") or "").strip()
    material=str(produto.get("Material") or "").strip()
    preco=str(produto.get("Preco") or "").strip()
    campanha=_thu_normalizar_campanha(campanha_nome) or str(campanha_nome or "").strip()
    partes=[f"✨ {nome}"]
    if campanha: partes.append(f"🎉 Campanha: {campanha}")
    if descricao: partes.append(descricao)
    if material: partes.append(f"Material: {material}.")
    if preco: partes.append(f"💰 {formatar_preco_catalogo(preco)}")
    if objetivo=="Novidade": abertura=f"🆕 Novidade para {campanha}: {nome}!" if campanha else f"🆕 Novidade: {nome}!"
    elif objetivo=="Promoção": abertura=f"🔥 {nome} em destaque para {campanha}!" if campanha else f"🔥 {nome} em destaque!"
    elif objetivo=="Apresentar produto": abertura=f"✨ Conheça {nome}" + (f" para {campanha}" if campanha else "")
    elif objetivo=="Data comemorativa": abertura=f"🎉 Prepare-se para {campanha} com {nome}!" if campanha else f"🎉 {nome} para sua comemoração!"
    else: abertura=f"✨ {nome}" + (f" para {campanha}" if campanha else "")
    corpo="\n\n".join([x for x in [abertura,descricao,(f"Material: {material}." if material else ""),(f"💰 {formatar_preco_catalogo(preco)}" if preco else "")] if x])
    legenda=corpo+"\n\n📲 Chame a AlphaFest no WhatsApp e faça seu pedido!"
    story=f"{abertura}\n"+(f"{formatar_preco_catalogo(preco)}\n" if preco else "")+"📲 Faça seu pedido!"
    return {
        "produto":nome,"campanha":campanha,"objetivo":objetivo,"descricao":descricao,"material":material,
        "preco":preco,"arte_id":str((arte or {}).get("id") or ""),"arte_nome":str((arte or {}).get("produto") or ""),
        "legenda":legenda,"story":story,"status":story,"cta":"📲 Chame a AlphaFest no WhatsApp e faça seu pedido!",
        "gerado_em":agora_local().isoformat(),
    }

def thu_recomendar_artes_biblioteca(conteudos, consulta="", categoria="", tema="", limite=5):
    """20.4.8-A: relevancia obrigatoria antes de favorita/reuso."""
    q=str(consulta or "").strip().casefold()
    catq=str(categoria or "").strip().casefold()
    temaq=str(tema or "").strip().casefold()
    termos=[t for t in q.replace("/"," ").replace("-"," ").split() if len(t)>=2]
    ranking=[]
    for item in conteudos or []:
        produto=str(item.get("produto") or ""); cat=str(item.get("categoria") or "")
        tema_i=str(item.get("tema_reuso") or item.get("campanha") or "Permanente")
        texto=f"{produto} {cat} {tema_i} {item.get('origem_criativa') or ''}".casefold()
        acertos=sum(1 for t in termos if t in texto)
        if termos and acertos==0: continue
        if catq not in ("","todas") and cat.casefold()!=catq: continue
        if temaq not in ("","todos") and tema_i.casefold()!=temaq: continue
        pontos=acertos*100; motivos=[]
        if acertos: motivos.append("combina com a busca")
        if catq not in ("","todas"): pontos+=45; motivos.append("mesma categoria")
        if temaq not in ("","todos"): pontos+=40; motivos.append("mesmo tema")
        if item.get("favorita"): pontos+=28; motivos.append("oficial/favorita")
        reusos=int(item.get("quantidade_reutilizacoes") or len(item.get("historico_reutilizacoes") or []))
        if reusos: pontos+=min(reusos*4,24); motivos.append(f"reutilizada {reusos}x")
        if item.get("tipo_registro")=="arte_pronta_flat": pontos+=8
        if not termos and catq in ("","todas") and temaq in ("","todos"): pontos+=1
        ranking.append((pontos,item,motivos))
    ranking.sort(key=lambda x:(x[0],str(x[1].get("ultima_reutilizacao_em") or x[1].get("criado_em") or "")),reverse=True)
    return ranking[:max(1,int(limite or 5))]


def thu_preparar_divulgacao_arte(item, objetivo="Vender"):
    """20.4.8-D — THU Comercial: copy específica por produto e objetivo."""
    produto=str(item.get("produto") or "Produto personalizado").strip()
    categoria=str(item.get("categoria") or "").strip()
    tema=str(item.get("tema_reuso") or item.get("campanha") or "Permanente").strip()
    preco=str(item.get("preco_arte") or "").strip()
    nome_cf=f"{produto} {categoria}".casefold()

    if "carimbo" in nome_cf:
        beneficio="Transforme brigadeiros, doces e biscoitos em peças ainda mais bonitas e valorizadas, com detalhes personalizados para cada tema."
    elif "papel de arroz" in nome_cf:
        beneficio="Personalize bolos, doces e bolachas de forma prática, com impressão que leva seu tema e sua identidade para cada detalhe."
    elif "vela" in nome_cf:
        beneficio="Nome, idade e personagem em um detalhe personalizado que deixa o parabéns ainda mais especial."
    elif "chaveiro" in nome_cf:
        beneficio="Transforme logos, times, mascotes e temas em uma lembrança personalizada, criativa e marcante."
    elif "bal" in nome_cf:
        beneficio="Uma decoração personalizada para transformar o ambiente e deixar sua comemoração ainda mais marcante."
    elif "topo" in nome_cf:
        beneficio="Um topo personalizado para completar o tema da festa e destacar o bolo com nome, idade e detalhes especiais."
    else:
        beneficio="Personalização feita para valorizar cada detalhe da sua comemoração, presente ou lembrança."

    objetivo_cf=str(objetivo or "Vender").casefold()
    if "novidade" in objetivo_cf:
        abertura=f"🆕 Novidade na AlphaFest: {produto}!"
        fechamento="Quer conhecer essa novidade? Chame a gente no WhatsApp 📲"
    elif "promo" in objetivo_cf:
        abertura=f"🔥 Destaque especial: {produto}!"
        fechamento="Consulte as condições e faça seu pedido pelo WhatsApp 📲"
    elif "apresent" in objetivo_cf:
        abertura=f"✨ Conheça: {produto}"
        fechamento="Quer saber mais? Fale com a AlphaFest pelo WhatsApp 📲"
    elif "data" in objetivo_cf:
        abertura=f"🎉 {produto} para deixar sua ocasião ainda mais especial!"
        fechamento="Antecipe seu pedido e fale com a AlphaFest pelo WhatsApp 📲"
    elif "parceria" in objetivo_cf:
        abertura=f"🤝 {produto} em uma parceria feita para criar detalhes especiais."
        fechamento="Fale com a AlphaFest e conheça nosso trabalho 📲"
    else:
        abertura=f"✨ {produto}"
        fechamento="📲 Chame no WhatsApp e faça seu pedido!"

    tema_valido=tema.casefold() not in ("","permanente","diversos temas","campanha livre","todos")
    tema_linha=f"\n🎉 Tema: {tema}" if tema_valido else ""
    preco_linha=f"\n💰 {preco}" if preco else ""
    legenda=(f"{abertura}\n\n{beneficio}\n\nProdução personalizada AlphaFest, preparada de acordo com a sua necessidade."
             f"{tema_linha}{preco_linha}\n\n{fechamento}")
    story=f"{abertura}\n{beneficio}\n"+(f"💰 {preco}\n" if preco else "")+"📲 Peça pelo WhatsApp!"
    status=f"{produto} ✨\n"+(f"{preco}\n" if preco else "")+"Personalizado do seu jeito.\nChame no WhatsApp 📲"

    stop={"para","com","dos","das","uma","tema","temas","diversos","permanente","campanha","livre","arte","pronta","todos"}
    tags=[]
    for pedaco in (produto+" "+categoria+((" "+tema) if tema_valido else "")).replace("/"," ").replace("-"," ").split():
        limpo="".join(ch for ch in pedaco if ch.isalnum())
        if len(limpo)>=3 and limpo.casefold() not in stop:
            tag="#"+limpo
            if tag.casefold() not in [x.casefold() for x in tags]: tags.append(tag)
    hashtags=["#AlphaFest","#Personalizados","#FestasPersonalizadas"]+tags[:7]
    return {"legenda":legenda,"story":story,"status":status,"cta":fechamento,
            "hashtags":" ".join(hashtags),"objetivo":objetivo,"gerado_em":agora_local().isoformat()}

def gerar_conteudo_marketing(produto, objetivo, campanha, canais, observacoes="", tom="Venda direta", imagem_png=None):
    pacote_ia, motor = _gerar_pacote_copy_ia(produto, objetivo, campanha, canais, observacoes, tom, imagem_png)
    if pacote_ia:
        return pacote_ia, motor
    return ({canal: gerar_copy_comercial(produto, objetivo, campanha, canal, observacoes, tom) for canal in canais}, motor)

def _icone_plataforma_data_uri(plataforma):
    caminho = Path(PLATFORM_ICON_FILES.get(plataforma, ""))
    try:
        bruto = caminho.read_bytes()
        return "data:image/svg+xml;base64," + base64.b64encode(bruto).decode("ascii")
    except Exception:
        return ""

def renderizar_cabecalho_canal(canal, aprovado=False, fila=False):
    cfg = CANAL_MIDIA_CONFIG.get(canal, {})
    uri = _icone_plataforma_data_uri(cfg.get("plataforma", ""))
    largura, altura = cfg.get("size", (0,0))
    status = "NA FILA" if fila else ("APROVADO" if aprovado else "REVISAR")
    status_cor = "#2563eb" if fila else ("#16a34a" if aprovado else "#d97706")
    logo_html = f'<img src="{uri}" style="width:36px;height:36px;object-fit:contain;">' if uri else ""
    st.markdown(f"""<div style="display:flex;align-items:center;justify-content:space-between;padding:12px 15px;border-radius:14px;background:#ffffff;border:1px solid #e5e7eb;border-left:6px solid {cfg.get('cor','#64748b')};margin-bottom:10px;box-shadow:0 2px 8px rgba(15,23,42,.05)"><div style="display:flex;align-items:center;gap:11px">{logo_html}<div><div style="font-size:1.08rem;font-weight:800;color:#111827">{html.escape(cfg.get('rotulo',canal))}</div><div style="font-size:.82rem;color:#6b7280">{largura} × {altura} • {cfg.get('arquivo','')}</div></div></div><span style="font-size:.72rem;font-weight:800;color:white;background:{status_cor};padding:6px 10px;border-radius:999px">{status}</span></div>""", unsafe_allow_html=True)

def _nome_arquivo_seguro(texto):
    limpo = re.sub(r"[^A-Za-z0-9_-]+", "_", str(texto or "campanha")).strip("_")
    return limpo[:80] or "campanha"


def _bytes_video_exportacao(referencia):
    """Lê o vídeo vinculado quando ele estiver disponível como arquivo local."""
    texto = str(referencia or "").strip()
    if not texto or texto.lower().startswith(("http://", "https://")):
        return b"", ""
    try:
        caminho = Path(texto)
        candidatos = [caminho]
        if not caminho.is_absolute():
            candidatos.extend([Path.cwd() / caminho, Path(__file__).resolve().parent / caminho])
        for candidato in candidatos:
            if candidato.exists() and candidato.is_file():
                return candidato.read_bytes(), candidato.suffix.lower() or ".mp4"
    except Exception:
        pass
    return b"", ""


def _checklist_publicacao(canal):
    cfg = CANAL_MIDIA_CONFIG.get(canal, {})
    largura, altura = cfg.get("size", (0, 0))
    tipo = cfg.get("tipo", "imagem")
    passos = [
        f"[ ] Conferir formato: {largura} x {altura}",
        "[ ] Revisar texto, preço, prazo e contato",
        "[ ] Conferir margens e legibilidade no celular",
        "[ ] Publicar manualmente no canal indicado",
    ]
    if tipo == "video":
        passos.extend([
            "[ ] Exportar em MP4 H.264, sem música",
            "[ ] Adicionar a música manualmente dentro da rede social",
            "[ ] Selecionar uma capa legível antes de publicar",
        ])
    else:
        passos.append("[ ] Usar o arquivo PNG da pasta deste canal")
    if canal.startswith("Instagram") or canal in ("Reel", "Carrossel"):
        passos.append("[ ] Confirmar se a replicação no Facebook está ativada na Meta")
    return "\n".join(passos) + "\n"


def gerar_zip_campanha(item):
    """Monta um kit offline organizado por canal para publicação manual."""
    pacote = io.BytesIO()
    nome_base = _nome_arquivo_seguro(item.get("produto") or item.get("id") or "campanha")
    campanha = item.get("campanha") or item.get("objetivo") or ""
    with zipfile.ZipFile(pacote, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        manifesto = [
            "ALPHAFEST MARKETING STUDIO",
            f"Campanha: {campanha}",
            f"Produto: {item.get('produto') or ''}",
            f"Criada em: {item.get('criado_em') or ''}",
            f"Motor de texto: {item.get('motor_copy') or 'Alpha local'}",
            "",
            "PUBLICAÇÃO MANUAL",
            "O Instagram é o canal principal. O Facebook recebe apenas a replicação configurada na Meta.",
            "Os vídeos são entregues sem música; adicione a trilha dentro da própria rede social.",
        ]
        zf.writestr("00_LEIA-ME.txt", "\n".join(manifesto))

        for indice, canal in enumerate(item.get("canais", []), start=1):
            cfg = CANAL_MIDIA_CONFIG.get(canal, {})
            slug = _nome_arquivo_seguro(canal)
            pasta = f"{indice:02d}_{slug}"
            largura, altura = cfg.get("size", (0, 0))
            especificacao = (
                f"Canal: {canal}\n"
                f"Formato: {largura} x {altura}\n"
                f"Tipo: {cfg.get('tipo', '')}\n"
                f"Arquivo recomendado: {cfg.get('arquivo', '')}\n"
                "Publicação: manual\n"
                "Música: adicionar manualmente na plataforma\n"
            )
            zf.writestr(f"{pasta}/01_ESPECIFICACOES.txt", especificacao)
            zf.writestr(f"{pasta}/02_CHECKLIST.txt", _checklist_publicacao(canal))

            arte_b64 = item.get("artes_png", {}).get(canal)
            if arte_b64:
                try:
                    zf.writestr(f"{pasta}/{nome_base}_{slug}.png", base64.b64decode(arte_b64))
                except Exception:
                    zf.writestr(f"{pasta}/ERRO_ARTE.txt", "A arte não pôde ser decodificada. Gere novamente este formato no Studio.")

            texto_canal = str(item.get("conteudos", {}).get(canal, "")).strip()
            if texto_canal:
                zf.writestr(f"{pasta}/03_TEXTO_PRONTO.txt", texto_canal)

        video_ref = str(item.get("video_original") or "").strip()
        if video_ref:
            video_bytes, extensao = _bytes_video_exportacao(video_ref)
            if video_bytes:
                zf.writestr(f"MIDIA_ORIGINAL/{nome_base}_video_original{extensao}", video_bytes)
            else:
                zf.writestr(
                    "MIDIA_ORIGINAL/REFERENCIA_VIDEO.txt",
                    "O vídeo está vinculado à campanha, mas não estava disponível como arquivo local durante a exportação.\n"
                    f"Referência registrada: {video_ref}\n",
                )

        zf.writestr(
            "99_FORMATOS_OFICIAIS.txt",
            "Instagram Feed: 1080x1350 PNG\n"
            "Instagram Story: 1080x1920 PNG\n"
            "Status WhatsApp: 1080x1920 PNG\n"
            "Instagram Reel: 1080x1920 MP4 H.264, sem música\n"
            "TikTok: 1080x1920 MP4 H.264, sem música\n"
            "YouTube Shorts: 1080x1920 MP4 H.264, sem música\n",
        )
    pacote.seek(0)
    return pacote.getvalue()


