def renderizar_caixa_projeto(proposta, prefixo="historico"):
    """Caixa do Projeto: arquivos, observações e reutilização ligados ao pedido."""
    projeto, _ = obter_ou_criar_projeto(proposta)
    projeto = dict(projeto)
    st.markdown("#### 📦 Caixa do Projeto")
    st.caption("Guarde artes, arquivos de produção, fotos finais e observações deste pedido.")
    kbase = f"{prefixo}_{projeto.get('id')}"

    c1, c2, c3 = st.columns(3)
    c1.write(f"**Projeto:** {projeto.get('id', '—')}")
    c2.write(f"**Tema:** {projeto.get('tema') or 'Não informado'}")
    c3.write(f"**Arquivos:** {len([a for a in projeto.get('arquivos', []) if not a.get('arquivado')])}")

    observacoes = st.text_area(
        "Observações internas do projeto",
        value=str(projeto.get("observacoes", "")),
        key=f"proj_obs_{kbase}",
        height=90,
    )
    o1, o2, o3 = st.columns(3)
    modelo = o1.checkbox("♻️ Modelo reutilizável", value=bool(projeto.get("modelo")), key=f"proj_modelo_{kbase}")
    favorito = o2.checkbox("⭐ Projeto favorito", value=bool(projeto.get("favorito")), key=f"proj_fav_{kbase}")
    if o3.button("💾 Salvar projeto", key=f"proj_salvar_{kbase}", use_container_width=True):
        projeto["observacoes"] = observacoes.strip()
        projeto["modelo"] = bool(modelo)
        projeto["favorito"] = bool(favorito)
        atualizar_projeto(projeto)
        st.success("Caixa do Projeto atualizada.")
        st.rerun()

    with st.expander("➕ Adicionar arquivo ao projeto", expanded=False):
        upload = st.file_uploader("Escolher arquivo", type=None, key=f"proj_upload_{kbase}")
        u1, u2 = st.columns(2)
        categoria = u1.selectbox(
            "Classificação",
            ["Arte", "Arquivo de produção", "Foto final", "Referência", "Vídeo", "Manual/Dica", "Outro"],
            key=f"proj_cat_{kbase}",
        )
        tags = u2.text_input("Tags", placeholder="Ex.: Stitch, azul, corte", key=f"proj_tags_{kbase}")
        descricao = st.text_input("Descrição", placeholder="Ex.: arte final aprovada", key=f"proj_desc_{kbase}")
        mestre = st.checkbox("⭐ Marcar como arquivo mestre", key=f"proj_mestre_{kbase}")
        if st.button("📤 Enviar arquivo", key=f"proj_enviar_{kbase}", type="primary", use_container_width=True):
            if upload is None:
                st.warning("Escolha um arquivo.")
            else:
                caminho = upload_library_file(upload, produto_nome=f"projetos/{projeto.get('id', 'projeto')}", local_upload_dir="projetos_uploads")
                if not caminho:
                    st.error("Não foi possível salvar o arquivo.")
                else:
                    arquivos = list(projeto.get("arquivos", []) or [])
                    if mestre:
                        for arq in arquivos:
                            arq["mestre"] = False
                    arquivos.append({
                        "id": f"PARQ-{agora_local().strftime('%Y%m%d%H%M%S%f')}",
                        "nome": str(upload.name),
                        "url": caminho,
                        "tipo": nome_tipo_arquivo(upload.name),
                        "categoria": categoria,
                        "tags": [x.strip() for x in tags.split(",") if x.strip()],
                        "descricao": descricao.strip(),
                        "mestre": bool(mestre),
                        "arquivado": False,
                        "criado_em": agora_local().strftime("%d/%m/%Y %H:%M"),
                    })
                    projeto["arquivos"] = arquivos
                    atualizar_projeto(projeto)
                    st.success("Arquivo adicionado ao projeto.")
                    st.rerun()

    ativos = [(i, a) for i, a in enumerate(projeto.get("arquivos", []) or []) if not a.get("arquivado")]
    if ativos:
        for i, arq in ativos:
            a1, a2, a3 = st.columns([1, 5, 2])
            a1.write("⭐" if arq.get("mestre") else ("📷" if arq.get("categoria") == "Foto final" else "📄"))
            a2.markdown(f"**{html.escape(str(arq.get('nome', 'Arquivo')))}**")
            a2.caption(f"{arq.get('categoria', 'Arquivo')} • {arq.get('criado_em', '')}")
            if arq.get("descricao"):
                a2.write(arq.get("descricao"))
            if arq.get("tags"):
                a2.caption("Tags: " + " • ".join(arq.get("tags", [])))
            if arq.get("url"):
                a3.link_button("Abrir / baixar", arq.get("url"), use_container_width=True)
            if a3.button("📦 Arquivar", key=f"proj_arq_{kbase}_{i}", use_container_width=True):
                projeto["arquivos"][i]["arquivado"] = True
                projeto["arquivos"][i]["mestre"] = False
                atualizar_projeto(projeto)
                st.rerun()
    else:
        st.info("Nenhum arquivo vinculado a este projeto ainda.")


def carregar_catalogo():
    """Carrega catálogo do Supabase, com fallback automático para JSON local."""
    dados = load_document("catalogo_db", ARQUIVO_CATALOGO, [])
    return dados if isinstance(dados, list) else []


def salvar_catalogo(lista):
    if not isinstance(lista, list):
        raise ValueError("O catálogo precisa ser uma lista de produtos.")
    save_document("catalogo_db", lista, ARQUIVO_CATALOGO)
    st.session_state.pop("_thu_i7_analise", None)
    st.session_state.pop("_thu_i7_periodo_analisado", None)


def normalizar_identidade_produto(valor):
    """20.4.9-H — normalização estrita para nome oficial/alias."""
    import unicodedata
    texto = unicodedata.normalize("NFKD", str(valor or "").strip())
    texto = "".join(c for c in texto if not unicodedata.combining(c)).casefold()
    texto = re.sub(r"[^a-z0-9]+", " ", texto)
    return " ".join(texto.split())


def mapa_identidade_produtos(catalogo):
    """Retorna nome/alias normalizado -> nome oficial. Nome oficial sempre tem prioridade."""
    catalogo = catalogo or []
    mapa = {}

    # Primeiro os nomes oficiais: um alias nunca pode sobrescrever um produto real.
    for produto in catalogo:
        nome = str(produto.get("Nome") or "").strip()
        chave = normalizar_identidade_produto(nome)
        if chave and nome:
            mapa[chave] = nome

    # Depois aliases livres.
    for produto in catalogo:
        oficial = str(produto.get("Nome") or "").strip()
        if not oficial:
            continue
        for alias in (produto.get("Aliases", []) or []):
            chave = normalizar_identidade_produto(alias)
            if chave and chave not in mapa:
                mapa[chave] = oficial
    return mapa


def nome_produto_oficial_catalogo(nome, catalogo):
    """Resolve um nome histórico/alternativo sem modificar a proposta original."""
    original = str(nome or "").strip() or "Não informado"
    chave = normalizar_identidade_produto(original)
    return mapa_identidade_produtos(catalogo).get(chave, original)


def conflito_alias_catalogo(alias, produto_oficial, catalogo):
    """Explica se um alias já pertence a outro produto oficial."""
    chave_alias = normalizar_identidade_produto(alias)
    chave_oficial = normalizar_identidade_produto(produto_oficial)
    if not chave_alias or chave_alias == chave_oficial:
        return ""

    for produto in catalogo or []:
        nome = str(produto.get("Nome") or "").strip()
        if normalizar_identidade_produto(nome) == chave_alias and normalizar_identidade_produto(nome) != chave_oficial:
            return f"'{alias}' já é nome oficial de '{nome}'."
        if normalizar_identidade_produto(nome) == chave_oficial:
            continue
        for existente in (produto.get("Aliases", []) or []):
            if normalizar_identidade_produto(existente) == chave_alias:
                return f"'{alias}' já está vinculado como alias de '{nome}'."
    return ""



def filtrar_aliases_validos_produto(produto_oficial, aliases, catalogo, indice_ignorar=None):
    """Valida aliases antes de salvar; conflitos são rejeitados sem afetar outros campos."""
    chave_oficial = normalizar_identidade_produto(produto_oficial)
    validos = []
    conflitos = []
    vistos = set()

    for alias in aliases or []:
        alias = str(alias or "").strip()
        chave_alias = normalizar_identidade_produto(alias)
        if not alias or not chave_alias or chave_alias == chave_oficial or chave_alias in vistos:
            continue
        vistos.add(chave_alias)

        conflito = ""
        for idx, produto in enumerate(catalogo or []):
            if indice_ignorar is not None and idx == indice_ignorar:
                continue
            nome_outro = str(produto.get("Nome") or "").strip()
            if normalizar_identidade_produto(nome_outro) == chave_alias:
                conflito = f"'{alias}' é nome oficial de '{nome_outro}'"
                break
            for alias_outro in (produto.get("Aliases", []) or []):
                if normalizar_identidade_produto(alias_outro) == chave_alias:
                    conflito = f"'{alias}' já é alias de '{nome_outro}'"
                    break
            if conflito:
                break

        if conflito:
            conflitos.append(conflito)
        else:
            validos.append(alias)

    return validos, conflitos



def produtos_proposta_sem_catalogo(proposta, catalogo=None):
    """20.4.9-I1 — retorna produtos da proposta sem correspondência oficial/alias no Catálogo."""
    catalogo = carregar_catalogo() if catalogo is None else (catalogo or [])
    mapa = mapa_identidade_produtos(catalogo)
    ausentes = []
    vistos = set()

    for item in (proposta or {}).get("itens", []) or []:
        nome = str(item.get("produto") or "").strip()
        chave = normalizar_identidade_produto(nome)
        if not nome or not chave:
            continue
        if chave in {"produto nao informado", "nao informado"}:
            continue
        if chave in mapa:
            continue
        if chave in vistos:
            continue
        vistos.add(chave)
        ausentes.append(nome)

    return ausentes


def renderizar_alerta_thu_produto_sem_catalogo(proposta, prefixo="thu_sem_catalogo"):
    """Mostra para a operação um aviso persistente enquanto houver item não cadastrado."""
    ausentes = produtos_proposta_sem_catalogo(proposta)
    if not ausentes:
        return False

    numero = str((proposta or {}).get("numero_proposta") or "").strip()
    plural = len(ausentes) > 1
    texto_produtos = " • ".join(ausentes)

    st.info(
        "💙 **THU informa:** "
        + ("Esta proposta contém produtos que ainda não estão cadastrados no Catálogo: "
           if plural else
           "Esta proposta contém um produto que ainda não está cadastrado no Catálogo: ")
        + f"**{texto_produtos}**. "
        + "Cadastre para que preço, material, campanhas, relatórios e próximas sugestões usem a fonte oficial."
    )

    if len(ausentes) == 1:
        nome = ausentes[0]
        if st.button(
            "➕ Cadastrar no Catálogo",
            key=f"{prefixo}_cadastrar_{abs(hash((numero, nome)))}",
            use_container_width=True,
        ):
            dialog_catalogo_cadastro_anna(nome_prefill=nome)
    else:
        st.caption("Cadastre os itens ausentes individualmente:")
        cols = st.columns(min(len(ausentes), 3))
        for idx, nome in enumerate(ausentes):
            with cols[idx % len(cols)]:
                if st.button(
                    f"➕ {nome}",
                    key=f"{prefixo}_cadastrar_{idx}_{abs(hash((numero, nome)))}",
                    use_container_width=True,
                ):
                    dialog_catalogo_cadastro_anna(nome_prefill=nome)

    return True


def avaliar_pendencias_produto_catalogo(produto):
    """20.4.9-E — mede se o cadastro possui os dados mínimos para o THU."""
    produto = produto or {}
    criticas = []
    avisos = []

    descricao = str(
        produto.get("DescricaoCompleta")
        or produto.get("DescricaoCurta")
        or produto.get("Descricao")
        or ""
    ).strip()

    if not str(produto.get("Nome") or "").strip():
        criticas.append("Nome")
    if not str(produto.get("Categoria") or "").strip():
        criticas.append("Categoria")
    if not descricao:
        criticas.append("Descrição")
    if not str(produto.get("Material") or "").strip():
        if not (
            bool(produto.get("MaterialNaoSeAplicaTHU"))
            or thu_i861_alerta_aceito(produto, "critica:material")
        ):
            criticas.append("Material")
    if not str(produto.get("Preco") or "").strip():
        criticas.append("Valor")
    if not (produto.get("CampanhasPermitidas", []) or []):
        criticas.append("Campanhas/Datas")
    if not (produto.get("Imagens", []) or []):
        if not thu_i861_alerta_aceito(produto, "visual:foto"):
            avisos.append("Foto")

    return {
        "criticas": criticas,
        "avisos": avisos,
        "pronto_thu": not criticas,
        "completo_visual": not criticas and not avisos,
    }



def auditar_dados_antigos_catalogo(produto):
    """Detecta sinais de migração antiga e respeita revisões humanas registradas."""
    produto = produto or {}
    alertas = thu_i861_alertas_legado_brutos(produto)
    return [
        alerta
        for alerta in alertas
        if not thu_i861_alerta_aceito(
            produto,
            thu_i861_chave_legado(produto, alerta),
        )
    ]



def thu_i861_chave_alerta(tipo, texto="", outro=""):
    """Cria uma chave estável para uma decisão humana de saneamento."""
    tipo_txt = re.sub(r"[^a-z0-9]+", "_", str(tipo or "").casefold()).strip("_")
    texto_txt = normalizar_identidade_produto(str(texto or "")).replace(" ", "_")
    outro_txt = normalizar_identidade_produto(str(outro or "")).replace(" ", "_")
    partes = [x for x in (tipo_txt, texto_txt, outro_txt) if x]
    return ":".join(partes)


def thu_i861_chave_legado(produto, alerta):
    """Chave do alerta inclui o conteúdo revisado; se o conteúdo mudar, ele volta à fila."""
    import hashlib
    produto = produto or {}
    alerta_txt = str(alerta or "")

    if "Material parece conter" in alerta_txt:
        contexto = str(produto.get("Material") or "")
    elif "imagem local" in alerta_txt:
        contexto = "|".join(
            str(x) for x in (produto.get("Imagens", []) or [])
        )
    elif "Nome e categoria" in alerta_txt:
        contexto = (
            str(produto.get("Nome") or "")
            + "|"
            + str(produto.get("Categoria") or "")
        )
    elif "Descrição muito longa" in alerta_txt:
        contexto = str(
            produto.get("DescricaoCompleta")
            or produto.get("DescricaoCurta")
            or produto.get("Descricao")
            or ""
        )
    else:
        contexto = str(produto.get("Nome") or "")

    digest = hashlib.sha1(
        contexto.encode("utf-8", errors="ignore")
    ).hexdigest()[:12]
    return thu_i861_chave_alerta("legado", alerta_txt, digest)


def thu_i861_revisoes_ativas(produto):
    """Retorna a última decisão ativa por alerta, preservando todo o histórico."""
    ultimas = {}
    for reg in list((produto or {}).get("RevisoesSaneamentoTHU", []) or []):
        if not isinstance(reg, dict):
            continue
        chave = str(reg.get("chave_alerta") or "").strip()
        if chave:
            ultimas[chave] = reg
    return {
        chave: reg
        for chave, reg in ultimas.items()
        if str(reg.get("decisao") or "") in {
            "aceito_como_esta",
            "nao_se_aplica",
            "nao_sao_duplicados",
        }
    }


def thu_i861_alerta_aceito(produto, chave_alerta):
    return str(chave_alerta or "") in thu_i861_revisoes_ativas(produto)


def thu_i861_registrar_decisao(
    indice_produto,
    chave_alerta,
    tipo,
    texto,
    decisao,
    justificativa="",
):
    """Registra decisão humana sem apagar decisões anteriores."""
    catalogo = carregar_catalogo()
    if indice_produto is None or not (0 <= int(indice_produto) < len(catalogo)):
        raise ValueError("Produto não localizado no Catálogo Oficial.")

    idx = int(indice_produto)
    produto = dict(catalogo[idx] or {})
    hist = list(produto.get("RevisoesSaneamentoTHU", []) or [])
    hist.append({
        "chave_alerta": str(chave_alerta or ""),
        "tipo": str(tipo or ""),
        "texto": str(texto or ""),
        "decisao": str(decisao or ""),
        "justificativa": str(justificativa or "").strip(),
        "revisado_em": agora_local().isoformat(timespec="seconds"),
        "usuario": obter_usuario_atual(),
        "versao_regra": "20.4.9-I8.6.1",
    })
    produto["RevisoesSaneamentoTHU"] = hist[-250:]
    if (
        str(chave_alerta or "") == "critica:material"
        and str(decisao or "") == "nao_se_aplica"
    ):
        produto["MaterialNaoSeAplicaTHU"] = True
    produto["AtualizadoEm"] = agora_local().isoformat(timespec="seconds")
    catalogo[idx] = produto
    salvar_catalogo(catalogo)
    return produto


def thu_i861_reabrir_decisao(indice_produto, chave_alerta):
    catalogo = carregar_catalogo()
    if indice_produto is None or not (0 <= int(indice_produto) < len(catalogo)):
        raise ValueError("Produto não localizado.")
    idx = int(indice_produto)
    produto = dict(catalogo[idx] or {})
    ativa = thu_i861_revisoes_ativas(produto).get(str(chave_alerta or ""))
    if not ativa:
        return produto

    hist = list(produto.get("RevisoesSaneamentoTHU", []) or [])
    hist.append({
        "chave_alerta": str(chave_alerta or ""),
        "tipo": str(ativa.get("tipo") or ""),
        "texto": str(ativa.get("texto") or ""),
        "decisao": "reaberto",
        "justificativa": "Decisão reaberta para nova conferência",
        "revisado_em": agora_local().isoformat(timespec="seconds"),
        "usuario": obter_usuario_atual(),
        "versao_regra": "20.4.9-I8.6.1",
    })
    produto["RevisoesSaneamentoTHU"] = hist[-250:]
    if str(chave_alerta or "") == "critica:material":
        produto["MaterialNaoSeAplicaTHU"] = False
    produto["AtualizadoEm"] = agora_local().isoformat(timespec="seconds")
    catalogo[idx] = produto
    salvar_catalogo(catalogo)
    return produto


def thu_i861_alertas_legado_brutos(produto):
    """Mesmas regras de legado da auditoria, sem ocultar decisões humanas."""
    produto = produto or {}
    alertas = []

    material = str(produto.get("Material") or "").strip()
    if material:
        material_cf = material.casefold()
        marcadores = [
            "itemdetalhes", "tamanhorecomendado", "usoindicado",
            "altura da estampa", "tamanho recomendado", "uso indicado",
            "materialpla", "materialacrilico", "materialpapel"
        ]
        if len(material) > 120 or sum(1 for m in marcadores if m in material_cf) >= 2:
            alertas.append("Material parece conter dados antigos concatenados")

    imagens = [
        str(x).strip()
        for x in (produto.get("Imagens", []) or [])
        if str(x).strip()
    ]
    for img in imagens:
        if img.startswith(("http://", "https://", "data:image/")):
            continue
        if not Path(img).exists():
            alertas.append("Há referência de imagem local que não existe mais")
            break

    nome = str(produto.get("Nome") or "").strip()
    categoria = str(produto.get("Categoria") or "").strip()
    if nome and categoria and nome.casefold() == categoria.casefold():
        alertas.append("Nome e categoria são idênticos; revisar classificação")

    descricao = str(
        produto.get("DescricaoCompleta")
        or produto.get("DescricaoCurta")
        or produto.get("Descricao")
        or ""
    ).strip()
    if descricao and len(descricao) > 700:
        alertas.append("Descrição muito longa; pode conter dados de migração")

    return list(dict.fromkeys(alertas))


def thu_i861_aplicar_permanente(indice_produto):
    """Confirma explicitamente elegibilidade permanente no campo oficial."""
    catalogo = carregar_catalogo()
    if indice_produto is None or not (0 <= int(indice_produto) < len(catalogo)):
        raise ValueError("Produto não localizado.")

    idx = int(indice_produto)
    produto = dict(catalogo[idx] or {})
    campanhas = [
        str(x).strip()
        for x in (produto.get("CampanhasPermitidas", []) or [])
        if str(x).strip()
    ]
    permanente = "Permanente / Todas as épocas"
    if permanente not in campanhas:
        campanhas.insert(0, permanente)
    produto["CampanhasPermitidas"] = list(dict.fromkeys(campanhas))

    hist = list(produto.get("RevisoesSaneamentoTHU", []) or [])
    hist.append({
        "chave_alerta": "critica:campanhas_datas",
        "tipo": "Campanhas/Datas",
        "texto": "Campanhas/Datas",
        "decisao": "corrigido_no_cadastro",
        "justificativa": "Elegibilidade confirmada como Permanente / Todas as épocas",
        "revisado_em": agora_local().isoformat(timespec="seconds"),
        "usuario": obter_usuario_atual(),
        "versao_regra": "20.4.9-I8.6.1",
    })
    produto["RevisoesSaneamentoTHU"] = hist[-250:]
    produto["AtualizadoEm"] = agora_local().isoformat(timespec="seconds")
    catalogo[idx] = produto
    salvar_catalogo(catalogo)
    return produto


def thu_i861_chave_duplicidade(nome_a, nome_b):
    nomes = sorted([
        normalizar_identidade_produto(nome_a),
        normalizar_identidade_produto(nome_b),
    ])
    return "duplicidade:" + "|".join(nomes)


def thu_i861_confirmar_nao_duplicados(indice_a, indice_b, justificativa):
    catalogo = carregar_catalogo()
    if not (0 <= int(indice_a) < len(catalogo)) or not (0 <= int(indice_b) < len(catalogo)):
        raise ValueError("Um dos produtos não foi localizado.")
    if not str(justificativa or "").strip():
        raise ValueError("Informe por que os produtos são diferentes.")

    a = int(indice_a)
    b = int(indice_b)
    nome_a = str((catalogo[a] or {}).get("Nome") or "")
    nome_b = str((catalogo[b] or {}).get("Nome") or "")
    chave = thu_i861_chave_duplicidade(nome_a, nome_b)

    for idx, outro in ((a, nome_b), (b, nome_a)):
        produto = dict(catalogo[idx] or {})
        hist = list(produto.get("RevisoesSaneamentoTHU", []) or [])
        hist.append({
            "chave_alerta": chave,
            "tipo": "Possível duplicidade",
            "texto": f"Produto revisado em relação a: {outro}",
            "decisao": "nao_sao_duplicados",
            "justificativa": str(justificativa or "").strip(),
            "revisado_em": agora_local().isoformat(timespec="seconds"),
            "usuario": obter_usuario_atual(),
            "versao_regra": "20.4.9-I8.6.1",
        })
        produto["RevisoesSaneamentoTHU"] = hist[-250:]
        produto["AtualizadoEm"] = agora_local().isoformat(timespec="seconds")
        catalogo[idx] = produto

    salvar_catalogo(catalogo)
    return True



def thu_i86_nome_flexivel(nome):
    """Normalização conservadora para localizar possíveis duplicidades de cadastro."""
    import unicodedata
    texto = unicodedata.normalize("NFKD", str(nome or ""))
    texto = "".join(c for c in texto if not unicodedata.combining(c)).casefold()
    texto = re.sub(r"[^a-z0-9]+", " ", texto)
    palavras = [
        p for p in texto.split()
        if p not in {"de", "do", "da", "dos", "das", "para", "com"}
    ]
    return " ".join(palavras).strip()


def thu_i86_possiveis_duplicidades(catalogo):
    """Retorna somente sinais fortes. Não une, apaga ou altera cadastros."""
    catalogo = list(catalogo or [])
    pares = []
    vistos = set()

    for i, produto_a in enumerate(catalogo):
        nome_a = str((produto_a or {}).get("Nome") or "").strip()
        if not nome_a:
            continue
        estrita_a = normalizar_identidade_produto(nome_a)
        flex_a = thu_i86_nome_flexivel(nome_a)
        aliases_a = {
            normalizar_identidade_produto(x)
            for x in ((produto_a or {}).get("Aliases", []) or [])
            if str(x).strip()
        }

        for j in range(i + 1, len(catalogo)):
            produto_b = catalogo[j] or {}
            nome_b = str(produto_b.get("Nome") or "").strip()
            if not nome_b:
                continue

            estrita_b = normalizar_identidade_produto(nome_b)
            flex_b = thu_i86_nome_flexivel(nome_b)
            aliases_b = {
                normalizar_identidade_produto(x)
                for x in (produto_b.get("Aliases", []) or [])
                if str(x).strip()
            }

            motivo = ""
            nivel = ""

            if estrita_a and estrita_a == estrita_b:
                motivo = "Mesmo nome após normalização"
                nivel = "forte"
            elif (
                estrita_a in aliases_b
                or estrita_b in aliases_a
            ):
                motivo = "Nome de um cadastro aparece como alias do outro"
                nivel = "forte"
            elif flex_a and flex_a == flex_b and estrita_a != estrita_b:
                motivo = "Nomes equivalentes após remover palavras de ligação"
                nivel = "provável"

            if not motivo:
                continue

            chave_revisao = thu_i861_chave_duplicidade(nome_a, nome_b)
            if (
                thu_i861_alerta_aceito(produto_a, chave_revisao)
                and thu_i861_alerta_aceito(produto_b, chave_revisao)
            ):
                continue

            chave = tuple(sorted((i, j)))
            if chave in vistos:
                continue
            vistos.add(chave)
            pares.append({
                "indices": (i, j),
                "nomes": (nome_a, nome_b),
                "motivo": motivo,
                "nivel": nivel,
            })

    return pares


def thu_i86_diagnosticar_catalogo(catalogo):
    """Cria a fila de saneamento sem modificar o Catálogo Oficial."""
    catalogo = list(catalogo or [])
    duplicidades = thu_i86_possiveis_duplicidades(catalogo)
    dup_por_indice = {}
    for par in duplicidades:
        for idx in par["indices"]:
            dup_por_indice.setdefault(idx, []).append(par)

    diagnosticos = []
    for idx, produto in enumerate(catalogo):
        produto = produto or {}
        rev = avaliar_pendencias_produto_catalogo(produto)
        legado = auditar_dados_antigos_catalogo(produto)
        duplicados = dup_por_indice.get(idx, [])

        peso = 0
        motivos = []

        for item in rev["criticas"]:
            peso += 18
            motivos.append({
                "chave": thu_i861_chave_alerta("critica", item),
                "tipo": item,
                "severidade": "critica",
                "texto": f"Completar: {item}",
            })

        for item in rev["avisos"]:
            peso += 7
            motivos.append({
                "chave": thu_i861_chave_alerta("visual", item),
                "tipo": item,
                "severidade": "visual",
                "texto": f"Revisar: {item}",
            })

        for alerta in legado:
            peso += 10
            motivos.append({
                "chave": thu_i861_chave_legado(produto, alerta),
                "tipo": "Dados antigos",
                "severidade": "legado",
                "texto": alerta,
            })

        for par in duplicados:
            peso += 20 if par.get("nivel") == "forte" else 12
            outro = (
                par["nomes"][1]
                if par["indices"][0] == idx
                else par["nomes"][0]
            )
            motivos.append({
                "chave": thu_i861_chave_duplicidade(
                    par["nomes"][0],
                    par["nomes"][1],
                ),
                "tipo": "Possível duplicidade",
                "severidade": "duplicidade",
                "texto": f"{par.get('motivo')}: {outro}",
                "outro_indice": (
                    par["indices"][1]
                    if par["indices"][0] == idx
                    else par["indices"][0]
                ),
            })

        score = max(0, 100 - min(100, peso))

        if rev["criticas"] or any(
            x.get("nivel") == "forte" for x in duplicados
        ):
            status = "🔴 Prioridade alta"
            ordem = 0
        elif legado or duplicados:
            status = "🟠 Revisar legado"
            ordem = 1
        elif rev["avisos"]:
            status = "🟡 Ajuste visual"
            ordem = 2
        else:
            status = "🟢 Saneado"
            ordem = 3

        fontes = list(produto.get("FontesHistoricasCatalogos", []) or [])
        recortes = list(produto.get("RecortesCatalogosHistoricos", []) or [])

        diagnosticos.append({
            "indice": idx,
            "produto": produto,
            "status": status,
            "ordem": ordem,
            "score": score,
            "motivos": motivos,
            "criticas": list(rev["criticas"]),
            "avisos": list(rev["avisos"]),
            "legado": list(legado),
            "duplicidades": list(duplicados),
            "fontes_historicas": len(fontes),
            "recortes_historicos": len(recortes),
        })

    diagnosticos.sort(
        key=lambda d: (
            d["ordem"],
            d["score"],
            normalizar_identidade_produto((d["produto"] or {}).get("Nome", "")),
        )
    )
    return {
        "diagnosticos": diagnosticos,
        "duplicidades": duplicidades,
    }


def thu_i86_progresso_acervo():
    """Resumo do tratamento das páginas históricas para apoiar o saneamento."""
    acervo = thu_i8_carregar_acervo_estatico()
    status_db = carregar_catalogos_legados_status()
    paginas_total = 0
    revisadas = 0
    ignoradas = 0
    em_andamento = 0

    for cat in (acervo.get("catalogos") or []):
        catalogo_id = str(cat.get("id") or "")
        for pg in (cat.get("paginas") or []):
            paginas_total += 1
            stat = thu_i8_status_pagina(
                catalogo_id,
                pg.get("pagina"),
                status_db=status_db,
            )
            estado = str(stat.get("status") or "Pendente")
            if estado == "Revisada":
                revisadas += 1
            elif estado == "Ignorada":
                ignoradas += 1
            elif estado in ("Em cadastro", "Em revisão"):
                em_andamento += 1

    pendentes = max(
        0,
        paginas_total - revisadas - ignoradas - em_andamento,
    )
    return {
        "total": paginas_total,
        "revisadas": revisadas,
        "ignoradas": ignoradas,
        "em_andamento": em_andamento,
        "pendentes": pendentes,
    }





@st.dialog("✅ THU • Revisão humana do saneamento", width="large")
def dialog_thu_i861_revisar_saneamento(indice_produto):
    catalogo = carregar_catalogo()
    if indice_produto is None or not (0 <= int(indice_produto) < len(catalogo)):
        st.error("Produto não localizado no Catálogo Oficial.")
        return

    idx = int(indice_produto)
    produto = dict(catalogo[idx] or {})
    nome = str(produto.get("Nome") or "Produto")

    st.markdown(f"### {nome}")
    st.caption(
        "Aqui você pode corrigir no cadastro oficial ou registrar uma decisão humana. "
        "Decisões aceitas ficam auditadas com usuário, data e justificativa."
    )

    analise = thu_i86_diagnosticar_catalogo(catalogo)
    diag = next(
        (d for d in (analise.get("diagnosticos") or []) if d.get("indice") == idx),
        None,
    )
    motivos = list((diag or {}).get("motivos") or [])

    if not motivos:
        st.success("Nenhuma pendência ativa foi detectada para este produto.")
    else:
        labels = []
        mapa = {}
        for pos_m, motivo in enumerate(motivos, 1):
            label = f"{pos_m}. {motivo.get('texto') or motivo.get('tipo') or 'Alerta'}"
            labels.append(label)
            mapa[label] = motivo

        escolhido = st.selectbox(
            "Alerta para revisar",
            labels,
            key=f"thu_i861_alerta_{idx}",
        )
        motivo = mapa[escolhido]
        tipo = str(motivo.get("tipo") or "")
        severidade = str(motivo.get("severidade") or "")
        texto = str(motivo.get("texto") or "")
        chave = str(motivo.get("chave") or "")

        if severidade in ("critica", "duplicidade"):
            st.warning(texto)
        elif severidade == "legado":
            st.info("🧹 " + texto)
        else:
            st.info(texto)

        justificativa = st.text_area(
            "Justificativa da revisão",
            placeholder=(
                "Ex.: classificação está correta para a operação atual; "
                "serviço não utiliza material físico; foto será mantida fora por enquanto..."
            ),
            key=f"thu_i861_justificativa_{idx}_{abs(hash(chave))}",
        ).strip()

        ac1, ac2 = st.columns(2)

        if tipo == "Campanhas/Datas":
            st.caption(
                "Se este produto pode ser divulgado durante todo o ano, use a opção abaixo. "
                "Ela grava **Permanente / Todas as épocas** no campo oficial CampanhasPermitidas."
            )
            if ac1.button(
                "🌐 Definir Permanente / Todas as épocas",
                type="primary",
                use_container_width=True,
                key=f"thu_i861_permanente_{idx}",
            ):
                thu_i861_aplicar_permanente(idx)
                st.session_state["_thu_i861_feedback"] = (
                    f"📅 {nome}: elegibilidade confirmada como Permanente / Todas as épocas."
                )
                st.rerun()

            if ac2.button(
                "✏️ Abrir cadastro e escolher datas",
                use_container_width=True,
                key=f"thu_i861_editar_campanhas_{idx}",
            ):
                st.session_state.catalogo_edit_index = idx
                st.rerun()

        elif tipo == "Material":
            st.caption(
                "Material continua sendo um dado importante para produtos físicos. "
                "Use **Não se aplica** somente quando este cadastro realmente representar "
                "um serviço ou situação sem material físico."
            )
            if ac1.button(
                "🚫 Confirmar que Material não se aplica",
                type="primary",
                use_container_width=True,
                disabled=not bool(justificativa),
                key=f"thu_i861_nao_aplica_material_{idx}",
            ):
                thu_i861_registrar_decisao(
                    idx,
                    "critica:material",
                    "Material",
                    "Material não informado",
                    "nao_se_aplica",
                    justificativa,
                )
                st.session_state["_thu_i861_feedback"] = (
                    f"✅ {nome}: Material marcado como não aplicável com justificativa."
                )
                st.rerun()

            if ac2.button(
                "✏️ Informar material no cadastro",
                use_container_width=True,
                key=f"thu_i861_editar_material_{idx}",
            ):
                st.session_state.catalogo_edit_index = idx
                st.rerun()

        elif tipo == "Foto":
            st.caption(
                "Foto é um ajuste visual. Você pode manter o produto sem foto por enquanto, "
                "desde que registre a razão."
            )
            if ac1.button(
                "✅ Revisado — manter sem foto",
                type="primary",
                use_container_width=True,
                disabled=not bool(justificativa),
                key=f"thu_i861_aceitar_foto_{idx}",
            ):
                thu_i861_registrar_decisao(
                    idx,
                    "visual:foto",
                    "Foto",
                    "Produto sem foto",
                    "aceito_como_esta",
                    justificativa,
                )
                st.session_state["_thu_i861_feedback"] = (
                    f"✅ {nome}: ausência de foto revisada e aceita."
                )
                st.rerun()

            if ac2.button(
                "✏️ Adicionar foto no cadastro",
                use_container_width=True,
                key=f"thu_i861_editar_foto_{idx}",
            ):
                st.session_state.catalogo_edit_index = idx
                st.rerun()

        elif tipo == "Dados antigos":
            st.caption(
                "Este é um alerta de revisão, não uma prova de erro. "
                "Se você conferir o cadastro e concluir que a informação está correta, "
                "registre a decisão para o alerta não voltar."
            )
            if ac1.button(
                "✅ Revisado e aceito como está",
                type="primary",
                use_container_width=True,
                disabled=not bool(justificativa),
                key=f"thu_i861_aceitar_legado_{idx}_{abs(hash(chave))}",
            ):
                thu_i861_registrar_decisao(
                    idx,
                    chave,
                    "Dados antigos",
                    texto,
                    "aceito_como_esta",
                    justificativa,
                )
                st.session_state["_thu_i861_feedback"] = (
                    f"✅ {nome}: alerta revisado e aceito com registro de auditoria."
                )
                st.rerun()

            if ac2.button(
                "✏️ Corrigir no cadastro",
                use_container_width=True,
                key=f"thu_i861_editar_legado_{idx}_{abs(hash(chave))}",
            ):
                st.session_state.catalogo_edit_index = idx
                st.rerun()

        elif tipo == "Possível duplicidade":
            outro_idx = motivo.get("outro_indice")
            outro_nome = ""
            if outro_idx is not None and 0 <= int(outro_idx) < len(catalogo):
                outro_nome = str((catalogo[int(outro_idx)] or {}).get("Nome") or "")
            st.caption(
                f"Se **{nome}** e **{outro_nome or 'o outro cadastro'}** são realmente produtos diferentes, "
                "registre isso para o par não voltar como duplicidade."
            )
            if ac1.button(
                "✅ Confirmar que são produtos diferentes",
                type="primary",
                use_container_width=True,
                disabled=not bool(justificativa) or outro_idx is None,
                key=f"thu_i861_nao_dup_{idx}_{outro_idx}",
            ):
                thu_i861_confirmar_nao_duplicados(
                    idx,
                    int(outro_idx),
                    justificativa,
                )
                st.session_state["_thu_i861_feedback"] = (
                    f"✅ Revisão registrada: {nome} e {outro_nome} não são duplicados."
                )
                st.rerun()

            if ac2.button(
                "✏️ Abrir este cadastro",
                use_container_width=True,
                key=f"thu_i861_editar_dup_{idx}_{outro_idx}",
            ):
                st.session_state.catalogo_edit_index = idx
                st.rerun()

        else:
            st.caption(
                "Este campo é estrutural para o Catálogo Oficial e não deve ser ocultado "
                "por uma simples aceitação. Corrija no cadastro."
            )
            if st.button(
                "✏️ Abrir cadastro oficial",
                type="primary",
                use_container_width=True,
                key=f"thu_i861_editar_estrutural_{idx}_{abs(hash(chave))}",
            ):
                st.session_state.catalogo_edit_index = idx
                st.rerun()

    ativos = thu_i861_revisoes_ativas(produto)
    if ativos:
        st.divider()
        with st.expander(
            f"🧾 Decisões humanas ativas ({len(ativos)})",
            expanded=False,
        ):
            st.caption(
                "Uma decisão pode ser reaberta a qualquer momento. "
                "O histórico anterior permanece preservado."
            )
            for pos_a, (chave_a, reg) in enumerate(ativos.items(), 1):
                st.markdown(
                    f"**{reg.get('tipo') or 'Revisão'}** — "
                    f"{reg.get('texto') or chave_a}"
                )
                st.caption(
                    f"Decisão: {reg.get('decisao')} • "
                    f"{reg.get('usuario') or '—'} • "
                    f"{reg.get('revisado_em') or '—'}"
                )
                if reg.get("justificativa"):
                    st.caption("Justificativa: " + str(reg.get("justificativa")))
                if st.button(
                    "↩️ Reabrir este alerta",
                    key=f"thu_i861_reabrir_{idx}_{pos_a}_{abs(hash(chave_a))}",
                    use_container_width=True,
                ):
                    thu_i861_reabrir_decisao(idx, chave_a)
                    st.session_state["_thu_i861_feedback"] = (
                        f"↩️ {nome}: decisão reaberta para nova conferência."
                    )
                    st.rerun()



def renderizar_saneamento_catalogo(catalogo):
    """I8.6.1 — saneamento com decisões humanas auditáveis."""
    catalogo = list(catalogo or [])
    st.subheader("🧹 THU • Saneamento do Catálogo Oficial")
    st.caption(
        "Organiza as pendências do Catálogo por prioridade. "
        "O THU não corrige, apaga, une ou inventa dados sozinho. "
        "Alertas revisáveis podem ser aceitos com justificativa e ficam registrados no histórico."
    )

    _feedback_i861 = st.session_state.pop("_thu_i861_feedback", "")
    if _feedback_i861:
        st.success(_feedback_i861)

    if not catalogo:
        st.info("Cadastre produtos para iniciar o saneamento.")
        return

    analise = thu_i86_diagnosticar_catalogo(catalogo)
    diagnosticos = list(analise.get("diagnosticos") or [])
    duplicidades = list(analise.get("duplicidades") or [])
    progresso_acervo = thu_i86_progresso_acervo()

    saneados = sum(1 for d in diagnosticos if d["ordem"] == 3)
    alta = sum(1 for d in diagnosticos if d["ordem"] == 0)
    legado = sum(1 for d in diagnosticos if d["ordem"] == 1)
    visual = sum(1 for d in diagnosticos if d["ordem"] == 2)
    sem_foto = sum(
        1
        for d in diagnosticos
        if "Foto" in (d.get("avisos") or [])
    )

    m1, m2, m3, m4, m5, m6 = st.columns(6)
    m1.metric("Produtos", len(catalogo))
    m2.metric("🟢 Saneados", saneados)
    m3.metric("🔴 Prioridade alta", alta)
    m4.metric("🟠 Revisar legado", legado)
    m5.metric("📷 Sem foto", sem_foto)
    m6.metric("🔁 Possíveis duplicidades", len(duplicidades))

    decisoes_humanas = sum(
        len(thu_i861_revisoes_ativas(p))
        for p in catalogo
    )
    if decisoes_humanas:
        st.caption(
            f"✅ {decisoes_humanas} decisão(ões) humana(s) ativa(s) de saneamento. "
            "Todas possuem usuário, data e histórico reabrível."
        )

    percentual = saneados / len(catalogo) if catalogo else 0.0
    st.progress(percentual)
    st.caption(
        f"Catálogo saneado: {saneados}/{len(catalogo)} produto(s) "
        f"({percentual * 100:.0f}%). "
        "O índice considera somente integridade e revisão do cadastro, não desempenho de vendas."
    )

    with st.expander("📚 Progresso do Acervo Histórico", expanded=False):
        a1, a2, a3, a4, a5 = st.columns(5)
        a1.metric("Páginas", progresso_acervo["total"])
        a2.metric("Revisadas", progresso_acervo["revisadas"])
        a3.metric("Em andamento", progresso_acervo["em_andamento"])
        a4.metric("Pendentes", progresso_acervo["pendentes"])
        a5.metric("Institucionais", progresso_acervo["ignoradas"])
        tratados = (
            progresso_acervo["revisadas"]
            + progresso_acervo["ignoradas"]
        )
        total_pag = max(1, progresso_acervo["total"])
        st.progress(min(1.0, tratados / total_pag))
        st.caption(
            "O Acervo e o Catálogo são controles diferentes: uma página pode estar revisada "
            "e ainda existir produto oficial com material, descrição, foto ou campanha a revisar."
        )

    st.markdown("#### Fila de saneamento")
    st.caption(
        "Para produtos válidos o ano inteiro, **Permanente / Todas as épocas** é uma elegibilidade oficial válida "
        "e pode ser confirmada diretamente na revisão humana."
    )

    f1, f2, f3 = st.columns([1.35, 1.55, 2.3])
    filtro_status = f1.selectbox(
        "Prioridade",
        [
            "Precisam atenção",
            "Todas",
            "🔴 Prioridade alta",
            "🟠 Revisar legado",
            "🟡 Ajuste visual",
            "🟢 Saneado",
        ],
        key="thu_i86_filtro_status",
    )
    filtro_tipo = f2.selectbox(
        "Tipo de revisão",
        [
            "Todos",
            "Material",
            "Campanhas/Datas",
            "Descrição",
            "Valor",
            "Foto",
            "Categoria",
            "Nome",
            "Dados antigos",
            "Possível duplicidade",
        ],
        key="thu_i86_filtro_tipo",
    )
    busca = f3.text_input(
        "Pesquisar produto, categoria ou alias",
        placeholder="Ex.: papel de arroz, copo, cortador...",
        key="thu_i86_busca",
    ).strip().casefold()

    somente_com_acervo = st.checkbox(
        "📚 Mostrar somente produtos vinculados ao Acervo Histórico",
        value=False,
        key="thu_i86_so_acervo",
    )

    lista = []
    for d in diagnosticos:
        produto = d["produto"] or {}
        status = d["status"]

        if filtro_status == "Precisam atenção" and d["ordem"] == 3:
            continue
        if filtro_status not in ("Precisam atenção", "Todas") and status != filtro_status:
            continue

        if filtro_tipo != "Todos":
            tipos = {str(m.get("tipo") or "") for m in d.get("motivos", [])}
            if filtro_tipo == "Dados antigos":
                if not d.get("legado"):
                    continue
            elif filtro_tipo not in tipos:
                continue

        if somente_com_acervo and not d.get("fontes_historicas"):
            continue

        texto_busca = " ".join([
            str(produto.get("Nome") or ""),
            str(produto.get("Categoria") or ""),
            str(produto.get("Subcategoria") or ""),
            " ".join(str(x) for x in (produto.get("Aliases", []) or [])),
        ]).casefold()
        if busca and busca not in texto_busca:
            continue

        lista.append(d)

    st.caption(
        f"{len(lista)} produto(s) nesta fila • ordenação: prioridade → menor índice de saneamento → alfabética."
    )

    if not lista:
        st.success("Nenhum produto encontrado com esses filtros.")
    else:
        limite = 60
        for d in lista[:limite]:
            produto = d["produto"] or {}
            idx = d["indice"]
            imagens = [
                str(x).strip()
                for x in (produto.get("Imagens", []) or [])
                if str(x).strip()
            ]

            with st.container(border=True):
                cimg, cinfo, cacoes = st.columns([0.9, 4.7, 1.55])

                with cimg:
                    if imagens:
                        try:
                            st.image(
                                imagem_streamlit_catalogo(imagens[0]),
                                width=105,
                            )
                        except Exception:
                            st.caption("📷 Imagem indisponível")
                    else:
                        st.caption("📷 Sem foto")

                with cinfo:
                    st.markdown(
                        f"**{produto.get('Nome') or 'Produto sem nome'}** "
                        f"— {d['status']}"
                    )
                    cat_txt = str(produto.get("Categoria") or "Sem categoria")
                    sub_txt = str(produto.get("Subcategoria") or "").strip()
                    if sub_txt:
                        cat_txt += f" / {sub_txt}"
                    st.caption(
                        f"{cat_txt} • Índice de saneamento: **{d['score']}/100**"
                    )

                    motivos = list(d.get("motivos") or [])
                    if motivos:
                        for motivo in motivos[:6]:
                            sev = str(motivo.get("severidade") or "")
                            texto = str(motivo.get("texto") or "")
                            if sev in ("critica", "duplicidade"):
                                st.warning(texto)
                            elif sev == "legado":
                                st.info("🧹 " + texto)
                            else:
                                st.caption("• " + texto)
                        if len(motivos) > 6:
                            st.caption(f"+ {len(motivos) - 6} ponto(s) adicional(is)")

                    extras = []
                    if d.get("fontes_historicas"):
                        extras.append(
                            f"📚 {d['fontes_historicas']} fonte(s) histórica(s)"
                        )
                    if d.get("recortes_historicos"):
                        extras.append(
                            f"✂️ {d['recortes_historicos']} recorte(s)"
                        )
                    if produto.get("CampanhasPermitidas"):
                        extras.append(
                            f"📅 {len(produto.get('CampanhasPermitidas') or [])} campanha(s)"
                        )
                    if extras:
                        st.caption(" • ".join(extras))

                with cacoes:
                    if st.button(
                        "✏️ Corrigir cadastro",
                        key=f"thu_i86_editar_{idx}",
                        use_container_width=True,
                        type="primary" if d["ordem"] == 0 else "secondary",
                    ):
                        st.session_state.catalogo_edit_index = idx
                        st.rerun()

                    if st.button(
                        "✅ Revisar / aceitar",
                        key=f"thu_i861_revisar_{idx}",
                        use_container_width=True,
                    ):
                        dialog_thu_i861_revisar_saneamento(idx)

                    if d.get("duplicidades"):
                        st.caption("🔁 Conferir duplicidade antes de excluir ou unir qualquer cadastro.")

        if len(lista) > limite:
            st.caption(
                f"Mostrando {limite} de {len(lista)} produto(s). "
                "Use os filtros para reduzir a fila."
            )

    if duplicidades:
        with st.expander(
            f"🔁 Possíveis duplicidades para conferência ({len(duplicidades)})",
            expanded=False,
        ):
            st.warning(
                "São apenas sinais de nomes equivalentes/aliases. "
                "O Manager não une nem exclui produtos automaticamente."
            )
            for pos_dup, par in enumerate(duplicidades[:30], 1):
                i, j = par["indices"]
                p1 = catalogo[i] or {}
                p2 = catalogo[j] or {}
                with st.container(border=True):
                    d1, d2, d3 = st.columns([3.1, 3.1, 1.8])
                    d1.markdown(f"**A:** {p1.get('Nome') or '—'}")
                    d2.markdown(f"**B:** {p2.get('Nome') or '—'}")
                    d1.caption(str(p1.get("Categoria") or "Sem categoria"))
                    d2.caption(str(p2.get("Categoria") or "Sem categoria"))
                    d3.caption(par.get("motivo") or "")
                    b1, b2, b3 = st.columns(3)
                    if b1.button(
                        "✏️ Abrir A",
                        key=f"thu_i86_dup_a_{pos_dup}_{i}_{j}",
                        use_container_width=True,
                    ):
                        st.session_state.catalogo_edit_index = i
                        st.rerun()
                    if b2.button(
                        "✏️ Abrir B",
                        key=f"thu_i86_dup_b_{pos_dup}_{i}_{j}",
                        use_container_width=True,
                    ):
                        st.session_state.catalogo_edit_index = j
                        st.rerun()
                    if b3.button(
                        "✅ Revisar par",
                        key=f"thu_i861_dup_revisar_{pos_dup}_{i}_{j}",
                        use_container_width=True,
                    ):
                        dialog_thu_i861_revisar_saneamento(i)


def imagem_data_uri(path):
    if not path:
        return ""
    texto = str(path).strip()
    if texto.startswith("data:image/"):
        return texto
    if not os.path.exists(texto):
        return ""
    ext = os.path.splitext(texto)[1].lower().replace(".", "") or "png"
    if ext == "jpg":
        ext = "jpeg"
    return f"data:image/{ext};base64,{get_image_base64(texto)}"


def slug_html(texto):
    texto = re.sub(r"[^a-zA-Z0-9_-]+", "_", str(texto).strip())
    return texto.strip("_") or "categoria"


def pesquisar_global(termo, limite_por_tipo=8):
    """Pesquisa sob demanda em clientes, propostas, catálogo, atendimentos e projetos.

    A função só deve ser chamada quando o usuário digitar ao menos dois caracteres,
    evitando consultas desnecessárias ao Supabase durante os reruns do Streamlit.
    """
    termo = str(termo or "").strip().lower()
    resultado = {"clientes": [], "propostas": [], "produtos": [], "atendimentos": [], "projetos": [], "componentes": []}
    if len(termo) < 2:
        return resultado

    for cliente in carregar_clientes():
        base = " ".join(str(cliente.get(c, "")) for c in [
            "nome", "documento", "whatsapp", "email", "cidade", "observacoes",
            "segmentos", "interesses", "campanhas_interesse"
        ]).lower()
        if termo in base:
            resultado["clientes"].append(cliente)
            if len(resultado["clientes"]) >= limite_por_tipo:
                break

    for proposta in carregar_historico():
        if termo in normalizar_texto_busca(proposta):
            resultado["propostas"].append(proposta)
            if len(resultado["propostas"]) >= limite_por_tipo:
                break

    for indice, produto in enumerate(carregar_catalogo()):
        base = (
            " ".join(str(produto.get(c, "")) for c in [
                "Nome", "Categoria", "Subcategoria", "CodigoInterno", "Descricao",
                "DescricaoCurta", "DescricaoCompleta", "PalavrasChave", "Tags"
            ])
            + " "
            + " ".join(str(x) for x in (produto.get("Aliases", []) or []))
        ).lower()
        if termo in base:
            registro = dict(produto)
            registro["_indice_catalogo"] = indice
            resultado["produtos"].append(registro)
            if len(resultado["produtos"]) >= limite_por_tipo:
                break

    dados_at = carregar_atendimentos()
    for atendimento in dados_at.get("itens", []):
        base = " ".join(str(atendimento.get(c, "")) for c in [
            "cliente", "telefone", "mensagem", "status", "assunto", "responsavel"
        ]).lower()
        if termo in base:
            resultado["atendimentos"].append(atendimento)
            if len(resultado["atendimentos"]) >= limite_por_tipo:
                break

    for categoria, valores in carregar_componentes().items():
        for valor in valores:
            if termo in f"{categoria} {valor}".lower():
                resultado["componentes"].append({"categoria": categoria, "valor": valor})
                if len(resultado["componentes"]) >= limite_por_tipo:
                    break
        if len(resultado["componentes"]) >= limite_por_tipo:
            break

    for projeto in carregar_projetos():
        arquivos = projeto.get("arquivos", []) if isinstance(projeto.get("arquivos"), list) else []
        partes = [
            projeto.get("cliente", ""), projeto.get("tema", ""), projeto.get("produto", ""),
            projeto.get("numero_proposta", ""), projeto.get("observacoes", ""),
            texto_componentes_projeto(projeto), projeto.get("caracteristicas_livres", ""), projeto.get("necessidade", ""), projeto.get("detalhes", "")
        ]
        for arquivo in arquivos:
            partes.extend([arquivo.get("nome", ""), arquivo.get("descricao", ""), arquivo.get("tags", "")])
        if termo in " ".join(map(str, partes)).lower():
            resultado["projetos"].append(projeto)
            if len(resultado["projetos"]) >= limite_por_tipo:
                break
    return resultado


def montar_fila_operacional(historico, tarefas, atendimentos, limite=10):
    """Cria uma fila única de próximas ações, ordenada por urgência."""
    hoje = hoje_local()
    itens = []
    config_at = atendimentos.get("config", {}) if isinstance(atendimentos, dict) else {}
    for atendimento in atendimentos.get("itens", []) if isinstance(atendimentos, dict) else []:
        if atendimento.get("status") in ("Entregue", "Pós-venda", "Arquivado"):
            continue
        nivel = faixa_sla_atendimento(atendimento, config_at)[2]
        minutos = minutos_aguardando(atendimento)
        itens.append({
            "peso": 500 + nivel * 100 + min(minutos, 180),
            "tipo": "Atendimento",
            "titulo": atendimento.get("cliente", "Contato"),
            "detalhe": f"{atendimento.get('status', 'Novo contato')} · {tempo_aguardando_formatado(atendimento)}",
            "acao": proxima_acao_atendimento(atendimento),
            "referencia": atendimento.get("id", ""),
        })
    for proposta in historico:
        if proposta.get("entregue", False):
            continue
        entrega = data_entrega_segura(proposta.get("data_entrega"))
        if entrega:
            dias = (entrega - hoje).days
            if dias < 0:
                peso = 900 + min(abs(dias), 30)
                detalhe = f"Atrasado há {abs(dias)} dia(s)"
            elif dias == 0:
                peso = 800
                detalhe = "Entrega hoje"
            elif dias <= 2:
                peso = 650 - dias
                detalhe = f"Entrega em {dias} dia(s)"
            else:
                continue
            itens.append({
                "peso": peso,
                "tipo": "Pedido",
                "titulo": f"{proposta.get('numero_proposta', '—')} · {proposta.get('cliente_nome', 'Cliente')}",
                "detalhe": detalhe,
                "acao": "Revisar pedido e confirmar próxima etapa",
                "referencia": proposta.get("numero_proposta", ""),
            })
    for tarefa in tarefas:
        if not tarefa.get("ativa", True):
            continue
        status = normalizar_status_fluxo(tarefa.get("status"))
        mapa = {
            "Aguardando aprovação": (620, "Cobrar ou registrar aprovação da arte"),
            "Arte aprovada": (610, "Iniciar impressão/produção"),
            "Pronto para produzir": (600, "Iniciar produção"),
            "Em produção": (520, "Continuar produção"),
            "Montagem/acabamento": (540, "Concluir montagem e conferência"),
            "Pronto": (700, "Avisar cliente e organizar entrega"),
        }
        if status not in mapa:
            continue
        peso, acao = mapa[status]
        itens.append({
            "peso": peso,
            "tipo": "Produção",
            "titulo": f"{tarefa.get('numero_proposta', '—')} · {tarefa.get('cliente_nome', 'Cliente')}",
            "detalhe": status,
            "acao": acao,
            "referencia": tarefa.get("numero_proposta", ""),
        })
    itens.sort(key=lambda x: x.get("peso", 0), reverse=True)
    return itens[:limite]


def proxima_acao_proposta(proposta):
    """Retorna a ação operacional mais útil para uma proposta."""
    if proposta.get("entregue", False):
        return "Registrar pós-venda"
    if proposta.get("aprovado", False):
        if not proposta.get("pago", False):
            return "Confirmar pagamento e acompanhar produção"
        return "Acompanhar produção e entrega"
    if proposta.get("enviado", False):
        return "Aguardar ou registrar aprovação do cliente"
    return "Revisar e enviar orçamento"


def resumo_cliente_operacional(cliente, propostas):
    """Calcula um cartão operacional sem alterar nenhum dado do cliente."""
    propostas = propostas or []
    totais = [calcular_valores_proposta(p)[2] for p in propostas]
    total = sum(totais)
    ticket = total / len(totais) if totais else 0.0
    ordenadas = sorted(
        propostas,
        key=lambda p: data_entrega_segura(p.get("data_geracao")) or date.min,
        reverse=True,
    )
    ultima = ordenadas[0] if ordenadas else None
    produtos = {}
    temas = {}
    for proposta in propostas:
        for item in proposta.get("itens", []) if isinstance(proposta.get("itens"), list) else []:
            nome = str(item.get("produto") or item.get("nome") or item.get("descricao") or "").strip()
            if nome:
                produtos[nome] = produtos.get(nome, 0) + 1
            especificacoes = str(item.get("especificacoes") or "")
            tema = ""
            for trecho in especificacoes.replace("\n", ";").split(";"):
                if "tema" in trecho.lower() and ":" in trecho:
                    tema = trecho.split(":", 1)[1].strip()
                    break
            if tema:
                temas[tema] = temas.get(tema, 0) + 1
    favoritos_produtos = [k for k, _ in sorted(produtos.items(), key=lambda kv: (-kv[1], kv[0].lower()))[:3]]
    favoritos_temas = [k for k, _ in sorted(temas.items(), key=lambda kv: (-kv[1], kv[0].lower()))[:3]]
    return {
        "quantidade": len(propostas),
        "total": total,
        "ticket": ticket,
        "ultima_data": ultima.get("data_geracao", "—") if ultima else "—",
        "ultima_proposta": ultima.get("numero_proposta", "—") if ultima else "—",
        "produtos": favoritos_produtos,
        "temas": favoritos_temas,
    }


def montar_assistente_do_dia(fila, limite=5):
    """Transforma a fila operacional em recomendações curtas e objetivas."""
    recomendacoes = []
    for item in (fila or [])[:limite]:
        recomendacoes.append({
            "titulo": item.get("titulo", "Pendência"),
            "motivo": item.get("detalhe", "Requer atenção"),
            "acao": item.get("acao", "Verificar"),
            "tipo": item.get("tipo", "Operação"),
            "referencia": item.get("referencia", ""),
        })
    return recomendacoes


def formatar_preco_catalogo(valor):
    texto = str(valor or "").strip().replace("R$", "").strip()
    try:
        numero = float(texto.replace(".", "").replace(",", ".")) if "," in texto else float(texto)
        return f"R$ {numero:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    except (TypeError, ValueError):
        return f"R$ {texto}" if texto else "Preço sob consulta"


# --- 20.4.9-I8.8.4: Validade comercial dos catálogos ---
I884_VALIDADE_DIAS = 30


def _i884_usuario_geracao(usuario=None):
    usuario = usuario or obter_usuario_atual()
    nome = str((usuario or {}).get("nome") or "").strip()
    return nome or "Usuário não informado"


def _i884_datetime_seguro(valor=None):
    if isinstance(valor, datetime):
        dt = valor
    elif valor:
        try:
            dt = datetime.fromisoformat(str(valor).replace("Z", "+00:00"))
        except Exception:
            dt = agora_local()
    else:
        dt = agora_local()
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=agora_local().tzinfo)
    else:
        try:
            dt = dt.astimezone(agora_local().tzinfo)
        except Exception:
            pass
    return dt


def _i884_metadados_geracao(gerado_em=None, gerado_por=None):
    """Metadados imutáveis de uma geração comercial de catálogo."""
    dt = _i884_datetime_seguro(gerado_em)
    validade = dt + timedelta(days=I884_VALIDADE_DIAS)
    return {
        "gerado_em": dt.isoformat(timespec="seconds"),
        "gerado_por": str(gerado_por or _i884_usuario_geracao()).strip() or "Usuário não informado",
        "data": dt.strftime("%d/%m/%Y"),
        "hora": dt.strftime("%H:%M"),
        "validade_ate": validade.date().isoformat(),
        "validade_texto": validade.strftime("%d/%m/%Y"),
    }


def _i884_metadados_registro_catalogo(registro):
    registro = registro or {}
    return _i884_metadados_geracao(
        registro.get("ultima_geracao_em") or registro.get("atualizado_em") or registro.get("criado_em"),
        registro.get("ultima_geracao_por") or registro.get("atualizado_por") or registro.get("criado_por"),
    )


def _i884_status_validade(metadados):
    metadados = metadados or {}
    try:
        limite = date.fromisoformat(str(metadados.get("validade_ate") or ""))
    except Exception:
        limite = hoje_local()
    dias = (limite - hoje_local()).days
    if dias < 0:
        return "🔴 Vencido", dias
    if dias <= 5:
        return "🟡 Próximo do vencimento", dias
    return "🟢 Válido", dias


def _i884_rodape_comercial_html(metadados):
    meta = metadados or _i884_metadados_geracao()
    gerado_por = html.escape(str(meta.get("gerado_por") or "Usuário não informado"))
    return (
        '<div class="validade-comercial">'
        f'<p><strong>Gerado em:</strong> {html.escape(str(meta.get("data") or ""))} às {html.escape(str(meta.get("hora") or ""))}</p>'
        f'<p><strong>Responsável:</strong> {gerado_por}</p>'
        f'<p><strong>Validade do catálogo:</strong> até {html.escape(str(meta.get("validade_texto") or ""))}</p>'
        f'<p class="aviso-validade">Este catálogo possui validade de {I884_VALIDADE_DIAS} dias. '
        'Após esse período, valores e condições devem ser reconfirmados junto à AlphaFest.</p>'
        '</div>'
    )


def _i884_atualizar_ultima_geracao(catalogo_id, metadados):
    """Persiste somente a rastreabilidade da geração; não cria snapshot comercial."""
    catalogo_id = str(catalogo_id or "")
    lista = carregar_catalogos_gerados()
    alterou = False
    for item in lista:
        if str(item.get("id") or "") == catalogo_id:
            item["ultima_geracao_em"] = str((metadados or {}).get("gerado_em") or "")
            item["ultima_geracao_por"] = str((metadados or {}).get("gerado_por") or "")
            item["validade_ate"] = str((metadados or {}).get("validade_ate") or "")
            alterou = True
            break
    if alterou:
        salvar_catalogos_gerados(lista)
    return alterou


