# --- 20.4.9-I8.9.2.1: Link público renderizado via GitHub Pages ---
def _i89_qr_png_bytes(conteudo):
    texto = str(conteudo or "").strip()
    if not texto or qrcode is None:
        return b""
    try:
        qr = qrcode.QRCode(version=None, error_correction=qrcode.constants.ERROR_CORRECT_M, box_size=8, border=3)
        qr.add_data(texto)
        qr.make(fit=True)
        img = qr.make_image(fill_color="black", back_color="white")
        saida = io.BytesIO()
        img.save(saida, format="PNG")
        return saida.getvalue()
    except Exception:
        return b""


def _i89_qr_data_uri(conteudo):
    bruto = _i89_qr_png_bytes(conteudo)
    return f"data:image/png;base64,{base64.b64encode(bruto).decode('ascii')}" if bruto else ""


def _i89_normalizar_telefone(valor):
    numero = re.sub(r"\D", "", str(valor or ""))
    if numero and len(numero) in (10, 11):
        numero = "55" + numero
    return numero


def _i89_link_whatsapp_compartilhar(url_publica, metadados, titulo="Catálogo AlphaFest", telefone=""):
    meta = dict(metadados or {})
    url = str(url_publica or "").strip()
    texto = (
        f"Olá! Segue o {str(titulo or 'Catálogo AlphaFest').strip()}.\n\n"
        f"{url}\n\n"
        f"Gerado em {meta.get('data', '')} às {meta.get('hora', '')}. "
        f"Válido até {meta.get('validade_texto', '')}.\n"
        "Após a validade, valores e condições devem ser reconfirmados junto à AlphaFest."
    )
    numero = _i89_normalizar_telefone(telefone)
    base = f"https://wa.me/{numero}" if numero else "https://wa.me/"
    return f"{base}?text={quote(texto)}"


def _i89_objeto_publicacao(registro, metadados):
    reg_id = re.sub(r"[^A-Za-z0-9_-]", "", str((registro or {}).get("id") or "catalogo")) or "catalogo"
    meta = dict(metadados or _i884_metadados_geracao())
    stamp = re.sub(r"\D", "", str(meta.get("gerado_em") or agora_local().isoformat()))[:14]
    titulo = slug_html((registro or {}).get("titulo") or (registro or {}).get("nome_interno") or "catalogo").lower()
    token = secrets.token_hex(4)
    return f"catalogos-publicos/{reg_id}/{stamp}_{titulo}_{token}.html"


def _i89_publicacoes(registro):
    itens = (registro or {}).get("publicacoes") or []
    return [x for x in itens if isinstance(x, dict)]


def _i891_url_cliente(publicacao):
    """Converte qualquer publicação com object_path para o link GitHub Pages I8.9.2."""
    publicacao = publicacao or {}
    caminho = str(publicacao.get("object_path") or "").strip()
    if caminho:
        render = catalog_render_url(caminho)
        if render:
            return render
    return str(publicacao.get("url") or "").strip()


def _i89_registrar_publicacao(catalogo_id, publicacao):
    catalogo_id = str(catalogo_id or "")
    lista = carregar_catalogos_gerados()
    for item in lista:
        if str(item.get("id") or "") == catalogo_id:
            historico = _i89_publicacoes(item)
            historico.insert(0, dict(publicacao or {}))
            item["publicacoes"] = historico[:30]
            item["ultimo_link_publico"] = str((publicacao or {}).get("url") or "")
            item["ultima_publicacao_em"] = str((publicacao or {}).get("gerado_em") or "")
            item["ultima_publicacao_por"] = str((publicacao or {}).get("gerado_por") or "")
            item["atualizado_em"] = agora_local().isoformat(timespec="seconds")
            item["atualizado_por"] = _usuario_auditoria()
            salvar_catalogos_gerados(lista)
            return True
    return False


# --- 20.4.9-I8.10: Inteligência Comercial dos Catálogos ---
def _i810_token_assinatura(valor):
    texto = str(valor or "").strip()
    if len(texto) > 512:
        return "sha256:" + hashlib.sha256(texto.encode("utf-8")).hexdigest()
    return texto


def _i810_lista_estavel(valor):
    itens = [_i810_token_assinatura(x) for x in _i871_lista_textos(valor) if str(x).strip()]
    return sorted(itens, key=normalizar_identidade_produto)


def _i810_assinatura_catalogo(registro, catalogo_oficial):
    """Assina apenas o estado comercial atual; nunca guarda preço/foto antigos.

    A assinatura permite detectar se o Catálogo Oficial mudou depois de uma
    publicação. É um hash irreversível, não um snapshot comercial.
    """
    registro = registro or {}
    opcoes = dict(registro.get("opcoes") or {})
    indices, ausentes = _i88_resolver_catalogo_salvo(registro, catalogo_oficial)
    produtos = []
    inativos = 0
    fora_campanha = 0
    for idx in indices:
        produto = (catalogo_oficial or [])[idx] or {}
        if not bool(produto.get("Ativo", True)):
            inativos += 1
            continue
        if not _i88_produto_elegivel_campanha(registro, produto):
            fora_campanha += 1
            continue
        if not bool(opcoes.get("mostrar_sem_foto", True)) and not _i871_lista_textos(produto.get("Imagens")):
            continue
        imagens_i810 = [_i810_token_assinatura(x) for x in _i871_lista_textos(produto.get("Imagens")) if str(x).strip()]
        variacoes_i810 = [str(x).strip() for x in _i871_lista_textos(produto.get("Variacoes")) if str(x).strip()]
        item = {
            "codigo": str(produto.get("CodigoInterno") or "").strip(),
            "nome": str(produto.get("Nome") or "").strip(),
            "categoria": str(produto.get("Categoria") or "").strip(),
            "subcategoria": str(produto.get("Subcategoria") or "").strip(),
            # O HTML I8.7 exibe somente a primeira imagem e até 8 variações.
            "imagem_principal": imagens_i810[0] if imagens_i810 else "",
            "variacoes": variacoes_i810[:8],
            "tem_mais_variacoes": len(variacoes_i810) > 8,
        }
        if bool(opcoes.get("mostrar_precos", True)):
            item["preco"] = formatar_preco_catalogo(produto.get("Preco"))
        if bool(opcoes.get("mostrar_descricao", True)):
            item["descricao"] = str(produto.get("DescricaoCurta", produto.get("Descricao", "")) or "").strip()
        if bool(opcoes.get("mostrar_material", True)):
            item["material"] = str(produto.get("Material") or "").strip()
        produtos.append(item)

    produtos.sort(key=lambda x: (
        normalizar_identidade_produto(x.get("categoria")),
        normalizar_identidade_produto(x.get("nome")),
        x.get("codigo", ""),
    ))
    payload = {
        "titulo": str(registro.get("titulo") or "").strip(),
        "subtitulo": str(registro.get("subtitulo") or "").strip(),
        "observacao_rodape": str(registro.get("observacao_rodape") or "").strip(),
        "campanha_chave": str(registro.get("campanha_chave") or "__todas__"),
        "categorias_chaves": sorted(str(x) for x in (registro.get("categorias_chaves") or [])),
        "opcoes": {
            "mostrar_precos": bool(opcoes.get("mostrar_precos", True)),
            "mostrar_descricao": bool(opcoes.get("mostrar_descricao", True)),
            "mostrar_material": bool(opcoes.get("mostrar_material", True)),
            "mostrar_whatsapp": bool(opcoes.get("mostrar_whatsapp", True)),
            "mostrar_sem_foto": bool(opcoes.get("mostrar_sem_foto", True)),
        },
        "produtos": produtos,
    }
    bruto = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    assinaturas_produtos_i8101 = []
    for item_i8101 in produtos:
        chave_i8101 = str(item_i8101.get("codigo") or "").strip()
        if chave_i8101:
            chave_i8101 = "codigo:" + chave_i8101.casefold()
        else:
            chave_i8101 = "nome:" + normalizar_identidade_produto(
                f"{item_i8101.get('categoria','')}|{item_i8101.get('nome','')}"
            )
        bruto_item_i8101 = json.dumps(
            item_i8101, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
        assinaturas_produtos_i8101.append({
            "chave": chave_i8101,
            "codigo": str(item_i8101.get("codigo") or "").strip(),
            "nome": str(item_i8101.get("nome") or "").strip(),
            "categoria": str(item_i8101.get("categoria") or "").strip(),
            "hash": hashlib.sha256(bruto_item_i8101).hexdigest(),
        })

    return {
        "assinatura": hashlib.sha256(bruto).hexdigest(),
        "produtos_saida": len(produtos),
        "referencias_pendentes": len(ausentes),
        "inativos": inativos,
        "fora_campanha": fora_campanha,
        # I8.10.1: hashes por produto permitem localizar o item alterado sem
        # armazenar preço, descrição, material ou foto antigos.
        "assinaturas_produtos": assinaturas_produtos_i8101,
    }


def _i8101_detalhar_mudancas(assinaturas_publicadas, assinaturas_atuais):
    publicadas = {
        str(x.get("chave") or ""): dict(x)
        for x in (assinaturas_publicadas or [])
        if isinstance(x, dict) and str(x.get("chave") or "").strip()
    }
    atuais = {
        str(x.get("chave") or ""): dict(x)
        for x in (assinaturas_atuais or [])
        if isinstance(x, dict) and str(x.get("chave") or "").strip()
    }
    alterados = []
    adicionados = []
    removidos = []
    for chave in sorted(set(publicadas) & set(atuais)):
        if str(publicadas[chave].get("hash") or "") != str(atuais[chave].get("hash") or ""):
            item = dict(atuais[chave])
            item["tipo_mudanca"] = "alterado"
            alterados.append(item)
    for chave in sorted(set(atuais) - set(publicadas)):
        item = dict(atuais[chave])
        item["tipo_mudanca"] = "adicionado"
        adicionados.append(item)
    for chave in sorted(set(publicadas) - set(atuais)):
        item = dict(publicadas[chave])
        item["tipo_mudanca"] = "removido_da_saida"
        removidos.append(item)
    return {
        "alterados": alterados,
        "adicionados": adicionados,
        "removidos": removidos,
        "todos": alterados + adicionados + removidos,
    }


def _i8101_indice_produto_catalogo(produto_ref, catalogo_oficial):
    produto_ref = produto_ref or {}
    codigo = str(produto_ref.get("codigo") or "").strip()
    if codigo:
        for idx, produto in enumerate(catalogo_oficial or []):
            if str((produto or {}).get("CodigoInterno") or "").strip().casefold() == codigo.casefold():
                return idx
    nome = normalizar_identidade_produto(produto_ref.get("nome"))
    categoria = normalizar_identidade_produto(produto_ref.get("categoria"))
    candidatos = []
    for idx, produto in enumerate(catalogo_oficial or []):
        if normalizar_identidade_produto((produto or {}).get("Nome")) != nome:
            continue
        if categoria and normalizar_identidade_produto((produto or {}).get("Categoria")) != categoria:
            continue
        candidatos.append(idx)
    return candidatos[0] if len(candidatos) == 1 else None


def _i8101_publicar_agora(registro, catalogo_oficial):
    """Publica uma nova versão direto da fila inteligente usando o mesmo motor da Central."""
    registro = dict(registro or {})
    catalogo_id = str(registro.get("id") or "")
    if not catalogo_id:
        return False, "Catálogo inválido."
    if not catalog_public_url("catalogos-publicos/verificacao.html"):
        return False, "Supabase indisponível para publicação."
    if not catalog_render_available():
        return False, "Visualizador público do GitHub Pages indisponível."

    meta = _i884_metadados_geracao()
    object_path = _i89_objeto_publicacao(registro, meta)
    url_planejada = catalog_render_url(object_path)
    qr_data = _i89_qr_data_uri(url_planejada)
    html_publico, _, _, _ = _i88_html_catalogo_salvo(
        registro,
        catalogo_oficial,
        metadados_geracao=meta,
        url_publica=url_planejada,
        qr_data_uri=qr_data,
    )
    storage_url = publish_catalog_html(html_publico, object_path)
    url_publicada = catalog_render_url(object_path) if storage_url else ""
    if not url_publicada:
        return False, "Não foi possível publicar no armazenamento online."

    assinatura = _i810_assinatura_catalogo(registro, catalogo_oficial)
    publicacao = {
        "id": f"PUB-{agora_local().strftime('%Y%m%d%H%M%S%f')}",
        "url": url_publicada,
        "storage_url": storage_url,
        "object_path": object_path,
        "gerado_em": meta["gerado_em"],
        "gerado_por": meta["gerado_por"],
        "validade_ate": meta["validade_ate"],
        "assinatura_conteudo": assinatura.get("assinatura", ""),
        "assinaturas_produtos": assinatura.get("assinaturas_produtos", []),
        "revisao_catalogo": int(registro.get("revisao", 1) or 1),
        "produtos_publicados": int(assinatura.get("produtos_saida", 0) or 0),
    }
    _i89_registrar_publicacao(catalogo_id, publicacao)
    _i884_atualizar_ultima_geracao(catalogo_id, meta)
    registrar_auditoria(
        "Republicar catálogo pela Inteligência",
        "Catálogo gerado",
        catalogo_id,
        {
            "url": url_publicada,
            "validade_ate": meta["validade_ate"],
            "gerado_por": meta["gerado_por"],
            "origem": "Inteligência I8.10.1",
        },
    )
    return True, f"Nova versão publicada e válida até {meta['validade_texto']}."


def _i810_diagnostico_catalogo(registro, catalogo_oficial):
    registro = registro or {}
    pubs = _i89_publicacoes(registro)
    ultima = pubs[0] if pubs else None
    atual = _i810_assinatura_catalogo(registro, catalogo_oficial)
    status_registro = str(registro.get("status") or "ativo")
    resultado = {
        "id": str(registro.get("id") or ""),
        "nome": str(registro.get("nome_interno") or registro.get("titulo") or "Catálogo"),
        "status_registro": status_registro,
        "publicacoes": len(pubs),
        "ultima_publicacao": ultima,
        "assinatura_atual": atual.get("assinatura"),
        "produtos_saida": atual.get("produtos_saida", 0),
        "pendentes": atual.get("referencias_pendentes", 0) + atual.get("inativos", 0),
        "fora_campanha": atual.get("fora_campanha", 0),
        "mudou_conteudo": None,
        "detalhes_mudanca": {"alterados": [], "adicionados": [], "removidos": [], "todos": []},
        "dias_validade": None,
        "status_validade": "⚪ Nunca publicado",
        "prioridade": 0,
        "acao": "Sem ação",
        "motivos": [],
    }
    if status_registro == "arquivado":
        resultado["acao"] = "Arquivado"
        return resultado

    if not ultima:
        resultado["prioridade"] = 80
        resultado["acao"] = "Publicar primeira versão"
        resultado["motivos"].append("Catálogo ativo ainda não possui link público.")
    else:
        meta = _i884_metadados_geracao(ultima.get("gerado_em"), ultima.get("gerado_por"))
        status_val, dias = _i884_status_validade(meta)
        resultado["status_validade"] = status_val
        resultado["dias_validade"] = dias
        resultado["meta_publicacao"] = meta
        assinatura_publicada = str(ultima.get("assinatura_conteudo") or "").strip()
        if assinatura_publicada:
            resultado["mudou_conteudo"] = assinatura_publicada != atual.get("assinatura")
            if resultado["mudou_conteudo"] is True and ultima.get("assinaturas_produtos"):
                resultado["detalhes_mudanca"] = _i8101_detalhar_mudancas(
                    ultima.get("assinaturas_produtos"),
                    atual.get("assinaturas_produtos"),
                )
        if dias < 0:
            resultado["prioridade"] = max(resultado["prioridade"], 100)
            resultado["acao"] = "Republicar agora"
            resultado["motivos"].append(f"Link comercial vencido há {abs(dias)} dia(s).")
        elif dias <= 5:
            resultado["prioridade"] = max(resultado["prioridade"], 70)
            resultado["acao"] = "Renovar em breve"
            resultado["motivos"].append(f"Validade termina em {dias} dia(s).")
        if resultado["mudou_conteudo"] is True:
            resultado["prioridade"] = max(resultado["prioridade"], 95)
            resultado["acao"] = "Republicar com dados atuais"
            resultado["motivos"].append("O conteúdo comercial do Catálogo Oficial mudou após a última publicação.")
        elif resultado["mudou_conteudo"] is None:
            resultado["motivos"].append("Publicação anterior à I8.10: comparação automática de alterações ainda sem baseline.")

    if resultado["pendentes"]:
        resultado["prioridade"] = max(resultado["prioridade"], 90)
        if resultado["acao"] in ("Sem ação", "Renovar em breve"):
            resultado["acao"] = "Revisar referências"
        resultado["motivos"].append(f"{resultado['pendentes']} referência(s) ausente(s) ou inativa(s) no Catálogo Oficial.")
    if resultado["fora_campanha"]:
        resultado["prioridade"] = max(resultado["prioridade"], 75)
        resultado["motivos"].append(f"{resultado['fora_campanha']} produto(s) deixaram de ser elegíveis para a campanha salva.")
    if resultado["prioridade"] == 0:
        resultado["acao"] = "Em dia"
    return resultado


def _i810_diagnosticos(catalogos, catalogo_oficial):
    itens = [_i810_diagnostico_catalogo(x, catalogo_oficial) for x in (catalogos or [])]
    itens.sort(key=lambda x: (int(x.get("prioridade", 0)), str(x.get("nome") or "").casefold()), reverse=True)
    return itens


def _i89_imagem_bytes(origem):
    origem = str(origem or "").strip()
    if not origem:
        return b""
    try:
        if origem.startswith("data:image/") and "," in origem:
            return base64.b64decode(origem.split(",", 1)[1])
        if origem.startswith(("http://", "https://")):
            resposta = requests.get(origem, timeout=8)
            resposta.raise_for_status()
            return resposta.content
        caminho = Path(origem)
        if caminho.exists() and caminho.is_file():
            return caminho.read_bytes()
    except Exception:
        return b""
    return b""


def _i89_rl_imagem(origem, max_w, max_h):
    if RLImage is None:
        return Spacer(1, 1) if Spacer else None
    bruto = _i89_imagem_bytes(origem)
    if not bruto:
        estilo_placeholder = ParagraphStyle(
            "i89_img_placeholder", fontName="Helvetica-Bold", fontSize=7.5, leading=9,
            alignment=TA_CENTER, textColor=rl_colors.HexColor("#6d7f8f")
        )
        caixa = Table([[Paragraph("Imagem disponível no catálogo online", estilo_placeholder)]], colWidths=[max_w], rowHeights=[max_h * 0.7])
        caixa.setStyle(TableStyle([
            ("VALIGN", (0,0), (-1,-1), "MIDDLE"), ("ALIGN", (0,0), (-1,-1), "CENTER"),
            ("BACKGROUND", (0,0), (-1,-1), rl_colors.HexColor("#edf3f7")),
            ("BOX", (0,0), (-1,-1), 0.4, rl_colors.HexColor("#dce8f1")),
        ]))
        return caixa
    try:
        w = h = 1
        if Image is not None:
            with Image.open(io.BytesIO(bruto)) as img:
                w, h = img.size
        escala = min(float(max_w) / max(float(w), 1.0), float(max_h) / max(float(h), 1.0))
        return RLImage(io.BytesIO(bruto), width=max(1, w * escala), height=max(1, h * escala))
    except Exception:
        return Spacer(max_w, max_h * 0.28)


def gerar_pdf_catalogo_i89(
    produtos,
    titulo="Catálogo AlphaFest",
    subtitulo="",
    mostrar_precos=True,
    mostrar_material=True,
    mostrar_descricao=True,
    observacao_rodape="",
    metadados_geracao=None,
    url_publica="",
):
    """PDF comercial estável, derivado da seleção atual do Catálogo Oficial."""
    if SimpleDocTemplate is None or A4 is None:
        return b""
    meta = dict(metadados_geracao or _i884_metadados_geracao())
    empresa = carregar_config_empresa()
    itens = [dict(p or {}) for p in (produtos or []) if (p or {}).get("Ativo", True)]
    itens.sort(key=lambda p: (_i871_categoria_chave(p), normalizar_identidade_produto(p.get("Nome", ""))))
    saida = io.BytesIO()
    doc = SimpleDocTemplate(
        saida,
        pagesize=A4,
        leftMargin=15 * mm,
        rightMargin=15 * mm,
        topMargin=17 * mm,
        bottomMargin=20 * mm,
        title=str(titulo or "Catálogo AlphaFest"),
        author="AlphaFest",
    )
    estilos = getSampleStyleSheet()
    azul = rl_colors.HexColor("#0f4c81")
    rosa = rl_colors.HexColor("#ed4f91")
    texto = rl_colors.HexColor("#17324a")
    muted = rl_colors.HexColor("#536a7d")
    estilo_titulo = ParagraphStyle("i89_titulo", parent=estilos["Title"], fontName="Helvetica-Bold", fontSize=25, leading=29, textColor=azul, spaceAfter=7)
    estilo_sub = ParagraphStyle("i89_sub", parent=estilos["BodyText"], fontName="Helvetica", fontSize=11, leading=15, textColor=muted, spaceAfter=10)
    estilo_cat = ParagraphStyle("i89_cat", parent=estilos["Heading2"], fontName="Helvetica-Bold", fontSize=17, leading=20, textColor=azul, spaceBefore=10, spaceAfter=7)
    estilo_nome = ParagraphStyle("i89_nome", parent=estilos["Heading3"], fontName="Helvetica-Bold", fontSize=12, leading=14, textColor=texto, spaceAfter=4)
    estilo_corpo = ParagraphStyle("i89_corpo", parent=estilos["BodyText"], fontName="Helvetica", fontSize=8.8, leading=11.5, textColor=muted)
    estilo_preco = ParagraphStyle("i89_preco", parent=estilos["BodyText"], fontName="Helvetica-Bold", fontSize=12, leading=14, textColor=rosa, spaceBefore=5)
    estilo_centro = ParagraphStyle("i89_centro", parent=estilos["BodyText"], fontName="Helvetica", fontSize=8.5, leading=11, alignment=TA_CENTER, textColor=muted)

    story = []
    logo_path = Path("logo.png")
    if logo_path.exists():
        try:
            logo_flow = _i89_rl_imagem(str(logo_path), 38 * mm, 24 * mm)
            story.append(Table([[Paragraph("AlphaFest", estilo_titulo), logo_flow]], colWidths=[125 * mm, 40 * mm], style=[("VALIGN", (0,0), (-1,-1), "MIDDLE")]))
        except Exception:
            story.append(Paragraph(html.escape(str(titulo or "Catálogo AlphaFest")), estilo_titulo))
    else:
        story.append(Paragraph(html.escape(str(titulo or "Catálogo AlphaFest")), estilo_titulo))
    if str(subtitulo or "").strip():
        story.append(Paragraph(html.escape(str(subtitulo).strip()), estilo_sub))
    story.append(Paragraph(f"<b>Gerado em:</b> {meta.get('data','')} às {meta.get('hora','')} &nbsp;&nbsp; <b>Responsável:</b> {html.escape(str(meta.get('gerado_por','')))}", estilo_sub))
    story.append(Paragraph(f"<b>Validade comercial:</b> até {meta.get('validade_texto','')} - após essa data, valores e condições devem ser reconfirmados.", estilo_sub))
    if str(url_publica or "").strip():
        qr_abertura_i89 = _i89_qr_png_bytes(url_publica)
        if qr_abertura_i89:
            qr_flow_i89 = RLImage(io.BytesIO(qr_abertura_i89), width=23 * mm, height=23 * mm)
            link_flow_i89 = Paragraph(
                "<b>Acesse a versão online</b><br/>" + html.escape(str(url_publica)),
                ParagraphStyle("i89_link_top", parent=estilo_corpo, fontSize=7.8, leading=10)
            )
            tabela_link_i89 = Table([[qr_flow_i89, link_flow_i89]], colWidths=[28 * mm, 137 * mm], hAlign="LEFT")
            tabela_link_i89.setStyle(TableStyle([("VALIGN", (0,0), (-1,-1), "MIDDLE"), ("BOX", (0,0), (-1,-1), 0.45, rl_colors.HexColor("#dce8f1")), ("BACKGROUND", (0,0), (-1,-1), rl_colors.HexColor("#f4f8fb")), ("LEFTPADDING", (0,0), (-1,-1), 7), ("RIGHTPADDING", (0,0), (-1,-1), 7), ("TOPPADDING", (0,0), (-1,-1), 6), ("BOTTOMPADDING", (0,0), (-1,-1), 6)]))
            story.append(tabela_link_i89)
            story.append(Spacer(1, 6))
    story.append(HRFlowable(width="100%", thickness=1.3, color=azul, spaceAfter=8))

    rotulos = _i871_mapa_rotulos([p.get("Categoria") for p in itens], fallback="Sem categoria")
    grupos = {}
    for prod in itens:
        grupos.setdefault(_i871_categoria_chave(prod), []).append(prod)
    for chave in sorted(grupos, key=lambda k: normalizar_identidade_produto(rotulos.get(k, k))):
        categoria = rotulos.get(chave, "Sem categoria")
        story.append(Paragraph(html.escape(categoria), estilo_cat))
        for prod in grupos[chave]:
            nome = html.escape(str(prod.get("Nome") or "Produto"))
            desc = html.escape(str(prod.get("DescricaoCurta") or prod.get("Descricao") or "").strip()).replace("\n", "<br/>")
            material = html.escape(str(prod.get("Material") or "").strip())
            variacoes = _i871_lista_textos(prod.get("Variacoes"))[:8]
            blocos = [Paragraph(nome, estilo_nome)]
            if mostrar_material and material:
                blocos.append(Paragraph(f"<b>Material:</b> {material}", estilo_corpo))
            if mostrar_descricao and desc:
                blocos.append(Paragraph(desc, estilo_corpo))
            if variacoes:
                blocos.append(Paragraph("<b>Opções:</b> " + html.escape(" • ".join(variacoes)), estilo_corpo))
            if mostrar_precos:
                blocos.append(Paragraph(html.escape(formatar_preco_catalogo(prod.get("Preco"))), estilo_preco))
            imagens = _i871_lista_textos(prod.get("Imagens"))
            img = _i89_rl_imagem(imagens[0] if imagens else "", 44 * mm, 38 * mm)
            card = Table([[img, blocos]], colWidths=[49 * mm, 116 * mm], hAlign="LEFT")
            card.setStyle(TableStyle([
                ("VALIGN", (0,0), (-1,-1), "TOP"),
                ("BOX", (0,0), (-1,-1), 0.55, rl_colors.HexColor("#dce8f1")),
                ("BACKGROUND", (0,0), (-1,-1), rl_colors.white),
                ("LEFTPADDING", (0,0), (-1,-1), 8),
                ("RIGHTPADDING", (0,0), (-1,-1), 8),
                ("TOPPADDING", (0,0), (-1,-1), 8),
                ("BOTTOMPADDING", (0,0), (-1,-1), 8),
            ]))
            story.append(KeepTogether([card, Spacer(1, 5)]))

    if str(observacao_rodape or "").strip():
        story.append(Spacer(1, 7))
        story.append(Paragraph(html.escape(str(observacao_rodape).strip()), estilo_centro))
    def rodape(canvas, doc_obj):
        canvas.saveState()
        canvas.setStrokeColor(rl_colors.HexColor("#dce8f1"))
        canvas.line(15 * mm, 14 * mm, A4[0] - 15 * mm, 14 * mm)
        canvas.setFillColor(rl_colors.HexColor("#536a7d"))
        canvas.setFont("Helvetica", 7.3)
        texto_footer = (
            f"{empresa.get('nome','AlphaFest')} | Gerado {meta.get('data','')} {meta.get('hora','')} | "
            f"Responsável: {meta.get('gerado_por','')} | Válido até {meta.get('validade_texto','')} | Página {doc_obj.page}"
        )
        canvas.drawCentredString(A4[0] / 2, 9 * mm, texto_footer[:155])
        canvas.restoreState()

    try:
        doc.build(story, onFirstPage=rodape, onLaterPages=rodape)
        return saida.getvalue()
    except Exception:
        return b""


def _i89_pdf_catalogo_salvo(registro, catalogo_oficial, metadados_geracao=None, url_publica=""):
    _, _, _, produtos = _i88_html_catalogo_salvo(registro, catalogo_oficial, metadados_geracao=metadados_geracao)
    opcoes = dict((registro or {}).get("opcoes") or {})
