    mostrar_orientacao_thu(
        "atualizar_orcamento" if numero_original else "novo_orcamento",
        token=chave_modal,
    )
    if not st.session_state.get(chave_modal):
        st.session_state[chave_modal] = True
        st.session_state["anna_modal_cliente"] = str(proposta.get("cliente_nome", proposta.get("cliente", "")))
        st.session_state["anna_modal_documento"] = str(proposta.get("documento", proposta.get("cliente_cpf_cnpj", "")))
        st.session_state["anna_modal_whatsapp"] = str(proposta.get("whatsapp", proposta.get("cliente_wa", "")))
        st.session_state["anna_modal_evento"] = str(proposta.get("evento", ""))
        st.session_state["anna_modal_itens"] = [dict(x) for x in proposta.get("itens", []) or []]
        st.session_state["anna_modal_item_key"] = int(st.session_state.get("anna_modal_item_key", 0)) + 1
        st.session_state["anna_modal_desconto"] = float(valor_float(proposta.get("desconto", proposta.get("desconto_valor", 0))))
        try:
            st.session_state["anna_modal_entrega"] = datetime.strptime(str(proposta.get("data_entrega", "")), "%d/%m/%Y").date()
        except Exception:
            st.session_state["anna_modal_entrega"] = hoje_local()
        st.session_state["anna_modal_prazo"] = str(proposta.get("prazo_dias", "10"))
        _frete_modal_salvo = str(proposta.get("frete_tipo", "Retirada")).strip()
        st.session_state["anna_modal_frete"] = "Entrega" if _frete_modal_salvo.casefold() == "entrega" else "Retirada"
        st.session_state["anna_modal_taxa_entrega"] = valor_float(proposta.get("taxa_entrega", 0))
        st.session_state["anna_modal_validade"] = str(proposta.get("validade_dias", "5"))
        st.session_state.pop("_i811hf2_anna_cliente_reconhecido_msg", None)
        st.session_state.pop("_i811hf2_anna_cliente_reconhecido_id", None)

    logo_b64, _ = encontrar_logo_base64()
    if logo_b64:
        le, lc, ld = st.columns([1, 1, 1])
        with lc:
            try:
                st.image(base64.b64decode(logo_b64), use_container_width=True)
            except Exception:
                pass
    st.markdown(
        "<p style='text-align:center; margin-top:-8px; color:#6b7280;'>"
        "Personalizados • Impressão 3D • Papelaria</p>",
        unsafe_allow_html=True,
    )

    if numero_original:
        st.info(f"✏️ Editando a proposta {numero_original}")

    ultima = st.session_state.get("_ultima_proposta_salva_anna")
    if ultima:
        with st.container(border=True):
            st.success(f"Proposta {ultima.get('numero_proposta', '')} salva com sucesso.")
            a1, a2, a3 = st.columns([2, 2, 1])
            destino = re.sub(r"\D", "", str(ultima.get("whatsapp") or ultima.get("cliente_wa") or ""))
            if destino and not destino.startswith("55"):
                destino = "55" + destino
            link = f"https://wa.me/{destino}?text={quote(formatar_msg_whatsapp(ultima))}" if destino else f"https://wa.me/?text={quote(formatar_msg_whatsapp(ultima))}"
            a1.link_button("📱 Enviar orçamento por WhatsApp", link, use_container_width=True)
            a2.download_button("📄 Gerar HTML", gerar_html(ultima), file_name=f"{ultima.get('numero_proposta','orcamento')}.html", mime="text/html", use_container_width=True, key=f"anna_html_salvo_{ultima.get('numero_proposta','orcamento')}")
            if a3.button("✖ Fechar", key="anna_modal_fechar_sucesso", use_container_width=True):
                st.session_state.pop("_ultima_proposta_salva_anna", None)
                st.rerun()

    # HF2 — extensão do fluxo homologado no Jorge para a Anna.
    # A identificação do cliente fica fora do form de item para permitir o callback
    # do WhatsApp sem recalcular tema, personalização e demais campos do produto.
    st.markdown("#### 👤 Cliente")
    nome = st.text_input("Nome / Razão Social", key="anna_modal_cliente")
    c1, c2 = st.columns(2)
    doc = c1.text_input("CPF / CNPJ", key="anna_modal_documento")
    wa = c2.text_input(
        "WhatsApp",
        key="anna_modal_whatsapp",
        on_change=autopreencher_cliente_whatsapp_anna_i811hf2,
        help="Ao confirmar um número já cadastrado, os dados e o Perfil Comercial do cliente são carregados automaticamente.",
    )
    evento = st.text_input(
        "🎉 Evento",
        key="anna_modal_evento",
        placeholder="Ex.: Chá Revelação, Aniversário da Maria, Confraternização Empresa X",
        help="Identifica o orçamento inteiro. Tema/Ocasião continua sendo uma informação de cada item.",
    )

    cliente_modal_i811 = localizar_cliente_comercial(nome, doc, wa)
    msg_modal_i811 = st.session_state.pop("_i811hf2_anna_cliente_reconhecido_msg", None)
    if cliente_modal_i811:
        resumo_modal_rec_i811 = resumo_cliente_reconhecido_i8111(cliente_modal_i811)
        st.success(f"✅ Cliente cadastrado reconhecido: **{cliente_modal_i811.get('nome', 'Cliente')}**")
        if resumo_modal_rec_i811:
            st.caption(resumo_modal_rec_i811)
        perfil_modal_i811 = resumo_perfil_comercial(cliente_modal_i811)
        if perfil_modal_i811.get("faturamento_mensal"):
            st.info(
                f"💳 **{cliente_modal_i811.get('nome', 'Cliente')} é mensalista.** "
                f"Fechamento dia {perfil_modal_i811.get('dia_fechamento')} · vencimento dia {perfil_modal_i811.get('dia_vencimento')}. "
                "Esta proposta ficará identificada para o controle mensal."
            )
        if perfil_modal_i811.get("qtd_regras_ativas", 0):
            st.caption(f"💰 Perfil Comercial encontrado: {perfil_modal_i811.get('qtd_regras_ativas')} abatimento(s) fixo(s) ativo(s) por produto.")
    elif msg_modal_i811 == "nao_encontrado":
        st.info("ℹ️ WhatsApp ainda não localizado nos Relacionamentos. A proposta pode ser criada normalmente e o cliente pode ser cadastrado depois.")

    # I8.11.3 — digitação viva do item no modal da Anna. O diálogo do Streamlit
    # já executa isoladamente; por isso quantidade e valor podem recalcular a prévia
    # sem atualizar os indicadores e sem sair da janela.
    chave_item_i8113 = st.session_state.get("anna_modal_item_key", 0)
    prod = st.text_input("Produto", key=f"anna_modal_prod_{chave_item_i8113}")
    with st.expander("🎨 Personalização & Especificações", expanded=True):
        e1, e2 = st.columns(2)
        tema = e1.text_input("Tema / Ocasião", key=f"anna_modal_tema_{chave_item_i8113}")
        nome_item = e1.text_input("Nome(s) Personalizado(s)", key=f"anna_modal_nome_item_{chave_item_i8113}")
        cor = e1.text_input("Cor / Material", key=f"anna_modal_cor_{chave_item_i8113}")
        idade = e2.text_input("Idade / Data do Evento", key=f"anna_modal_idade_{chave_item_i8113}")
        obs = e2.text_input("Outros Detalhes", key=f"anna_modal_obs_{chave_item_i8113}")
    q = st.number_input("Qtd", min_value=1, value=1, key=f"anna_modal_qtd_{chave_item_i8113}")
    v = st.number_input("Valor Unitário (R$)", min_value=0.0, value=0.0, step=0.5, key=f"anna_modal_valor_{chave_item_i8113}")

    itens_previa_i8113 = st.session_state.get("anna_modal_itens", []) or []
    subtotal_atual_i8113 = sum(valor_float(i.get("quantidade")) * valor_float(i.get("valor_unitario")) for i in itens_previa_i8113)
    cliente_previa_i8113 = localizar_cliente_comercial(nome, doc, wa)
    preco_previa_i8113 = calcular_preco_cliente_item(cliente_previa_i8113, prod.strip(), v) if cliente_previa_i8113 and prod.strip() else None
    valor_unitario_previa_i8113 = valor_float(v)
    if preco_previa_i8113 and not preco_previa_i8113.get("bloqueado"):
        valor_unitario_previa_i8113 = valor_float(preco_previa_i8113.get("preco_final"))
    total_item_previa_i8113 = valor_float(q) * valor_unitario_previa_i8113
    subtotal_com_item_i8113 = subtotal_atual_i8113 + total_item_previa_i8113
    desc_previa_i8113 = valor_float(st.session_state.get("anna_modal_desconto", 0))
    frete_previa_i8113 = str(st.session_state.get("anna_modal_frete", "Retirada"))
    taxa_previa_i8113 = valor_float(st.session_state.get("anna_modal_taxa_entrega", 0)) if frete_previa_i8113 == "Entrega" else 0.0
    total_proposta_previa_i8113 = max(subtotal_com_item_i8113 - desc_previa_i8113, 0.0) + taxa_previa_i8113

    st.caption("💡 Prévia enquanto você digita — o item ainda não foi adicionado à proposta.")
    pv1, pv2, pv3 = st.columns(3)
    pv1.metric("Total deste item", _anna_fmt_moeda(total_item_previa_i8113))
    pv2.metric("Itens já adicionados", _anna_fmt_moeda(subtotal_atual_i8113))
    pv3.metric("Prévia do total da proposta", _anna_fmt_moeda(total_proposta_previa_i8113))
    if preco_previa_i8113 and preco_previa_i8113.get("bloqueado"):
        st.error("🛑 A prévia detectou abatimento maior que o preço oficial. Revise o Perfil Comercial antes de adicionar o item.")
    elif preco_previa_i8113:
        st.caption((f"💼 Prévia com preço especial: R$ {preco_previa_i8113['preco_base']:.2f} - R$ {preco_previa_i8113['abatimento']:.2f} = R$ {preco_previa_i8113['preco_final']:.2f} por unidade").replace(".", ","))

    adicionar = st.button("➕ Adicionar Item", use_container_width=True, key=f"anna_modal_adicionar_{chave_item_i8113}")

    if adicionar:
        registrar_atividade(obter_usuario_atual(), "Adicionando item ao orçamento", "Orçamentos")
        if not prod.strip():
            st.warning("Informe o produto antes de adicionar.")
        else:
            detalhes = f"Tema: {tema} | Nome: {nome_item} | Idade: {idade} | Cor: {cor} | Obs: {obs}"
            item_novo = {"produto": prod.strip(), "especificacoes": detalhes, "quantidade": q, "valor_unitario": v}
            cliente_item_i811 = localizar_cliente_comercial(nome, doc, wa)
            preco_item_i811 = calcular_preco_cliente_item(cliente_item_i811, prod.strip(), v) if cliente_item_i811 else None
            if preco_item_i811 and preco_item_i811.get("bloqueado"):
                st.error(
                    f"🛑 Não foi possível aplicar o preço especial de {preco_item_i811.get('produto_oficial', prod.strip())}. "
                    f"Preço oficial R$ {preco_item_i811.get('preco_base', 0):.2f} e abatimento R$ {preco_item_i811.get('abatimento', 0):.2f}. "
                    "Revise o Perfil Comercial do cliente antes de adicionar este item."
                )
            else:
                if preco_item_i811:
                    item_novo.update({
                        "produto": preco_item_i811["produto_oficial"],
                        "valor_unitario": preco_item_i811["preco_final"],
                        "valor_base_oficial": preco_item_i811["preco_base"],
                        "abatimento_fixo_cliente": preco_item_i811["abatimento"],
                        "preco_especial_aplicado": True,
                        "perfil_comercial_cliente_id": (cliente_item_i811 or {}).get("id", ""),
                    })
                    st.success(
                        (f"💰 Preço especial aplicado a {preco_item_i811['produto_oficial']}: "
                         f"R$ {preco_item_i811['preco_base']:.2f} - R$ {preco_item_i811['abatimento']:.2f} = R$ {preco_item_i811['preco_final']:.2f}").replace(".", ",")
                    )
                st.session_state["anna_modal_itens"].append(item_novo)
                st.session_state["anna_modal_item_key"] += 1
                # Não executar rerun global dentro do diálogo: a lista abaixo já
                # usa o session_state atualizado e mostra o item imediatamente.

    itens = st.session_state.get("anna_modal_itens", [])
    if itens:
        cliente_itens_i811 = localizar_cliente_comercial(nome, doc, wa)
        perfil_itens_i811 = resumo_perfil_comercial(cliente_itens_i811) if cliente_itens_i811 else resumo_perfil_comercial({})
        if cliente_itens_i811 and perfil_itens_i811.get("qtd_regras_ativas", 0):
            if st.button("💼 Recalcular itens pelo Perfil Comercial", key="anna_i811hf2_recalcular_itens", use_container_width=True):
                alterados_i811 = 0
                bloqueados_i811 = []
                for item_i811 in itens:
                    calc_i811 = calcular_preco_cliente_item(cliente_itens_i811, item_i811.get("produto"), item_i811.get("valor_unitario", 0))
                    if calc_i811 and calc_i811.get("bloqueado"):
                        bloqueados_i811.append(calc_i811.get("produto_oficial") or item_i811.get("produto"))
                        continue
                    if calc_i811:
                        item_i811.update({
                            "produto": calc_i811["produto_oficial"],
                            "valor_unitario": calc_i811["preco_final"],
                            "valor_base_oficial": calc_i811["preco_base"],
                            "abatimento_fixo_cliente": calc_i811["abatimento"],
                            "preco_especial_aplicado": True,
                            "perfil_comercial_cliente_id": cliente_itens_i811.get("id", ""),
                        })
                        alterados_i811 += 1
                if bloqueados_i811:
                    st.error("🛑 Revise o Perfil Comercial antes de continuar: abatimento maior que o preço oficial em " + ", ".join(bloqueados_i811))
                elif alterados_i811:
                    st.success(f"{alterados_i811} item(ns) recalculado(s) com abatimento fixo em R$.")
                else:
                    st.info("Nenhum item atual possui regra de abatimento ativa para este cliente.")

        st.write("📋 **Itens da proposta:**")
        for idx, item in enumerate(itens):
            ci, cr = st.columns([8, 1])
            qtd_item_i8113 = valor_float(item.get("quantidade"))
            unit_item_i8113 = valor_float(item.get("valor_unitario"))
            total_item_i8113 = qtd_item_i8113 * unit_item_i8113
            ci.markdown(
                f"<strong>{idx + 1}. {html.escape(str(item.get('produto') or 'Produto'))}</strong> "
                f"— Qtd: {html.escape(str(item.get('quantidade')))} × "
                f"{_anna_fmt_moeda_html(unit_item_i8113)} = "
                f"<strong>{_anna_fmt_moeda_html(total_item_i8113)}</strong>",
                unsafe_allow_html=True,
            )
            ci.caption(item.get("especificacoes", ""))
            if valor_bool(item.get("preco_especial_aplicado")):
                base_i811 = valor_float(item.get("valor_base_oficial"))
                abat_i811 = valor_float(item.get("abatimento_fixo_cliente"))
                final_i811 = valor_float(item.get("valor_unitario"))
                ci.caption(
                    (f"💼 Preço especial: R$ {base_i811:.2f} - abatimento fixo R$ {abat_i811:.2f} = R$ {final_i811:.2f}").replace(".", ",")
                )
            if cr.button("🗑️", key=f"anna_modal_remover_{idx}", help="Remover item"):
                itens.pop(idx)
                try:
                    st.rerun(scope="fragment")
                except Exception:
                    pass

        st.divider()
        d1, d2, d3 = st.columns(3)
        desconto = d1.number_input("Desconto adicional da proposta (R$)", min_value=0.0, step=0.5, key="anna_modal_desconto", help="Separado dos abatimentos fixos por produto do Perfil Comercial do Cliente.")
        entrega = d2.date_input("📅 Data Entrega", key="anna_modal_entrega")
        prazo = d3.text_input("Prazo de Produção (dias úteis)", key="anna_modal_prazo")
        f1, f2 = st.columns(2)
        frete = f1.selectbox(
            "Entrega / Retirada",
            ["Retirada", "Entrega"],
            key="anna_modal_frete",
        )
        validade = f2.text_input("Validade (dias corridos)", key="anna_modal_validade")

        taxa_entrega = 0.0
        if frete == "Entrega":
            taxa_entrega = st.number_input(
                "🚚 Taxa de Entrega (R$)",
                min_value=0.0,
                step=0.50,
                key="anna_modal_taxa_entrega",
                help="Digite o valor cobrado pela entrega.",
            )

        subtotal = sum(valor_float(i.get("quantidade")) * valor_float(i.get("valor_unitario")) for i in itens)
        total = max(subtotal - desconto, 0.0) + valor_float(taxa_entrega)

        t1, t2, t3, t4 = st.columns(4)
        t1.metric("Subtotal", f"R$ {subtotal:,.2f}".replace(",", "X").replace(".", ",").replace("X", "."))
        t2.metric("Desconto", f"R$ {valor_float(desconto):,.2f}".replace(",", "X").replace(".", ",").replace("X", "."))
        t3.metric("Taxa de entrega", f"R$ {valor_float(taxa_entrega):,.2f}".replace(",", "X").replace(".", ",").replace("X", "."))
        t4.metric("Valor total", f"R$ {total:,.2f}".replace(",", "X").replace(".", ",").replace("X", "."))

        salvar_rotulo = "💾 SALVAR ALTERAÇÕES" if numero_original else "🚀 SALVAR PROPOSTA"
        if st.button(salvar_rotulo, type="primary", use_container_width=True, key="anna_modal_salvar_orcamento"):
            if not nome.strip():
                st.error("Informe o nome do cliente.")
                return
            numero = numero_original or ""
            cliente_comercial_i811 = localizar_cliente_comercial(nome, doc, wa)
            perfil_salvar_i811 = resumo_perfil_comercial(cliente_comercial_i811) if cliente_comercial_i811 else resumo_perfil_comercial({})
            mensal_salvar_i811 = bool(perfil_salvar_i811.get("faturamento_mensal"))
            modalidade_salvar_i811 = I811_MODALIDADE_MENSAL if mensal_salvar_i811 else I811_MODALIDADE_NORMAL
            dados = {
                **proposta,
                "numero_proposta": numero,
                "data_geracao": proposta.get("data_geracao", agora_local().strftime("%d/%m/%Y")),
                "data_entrega": entrega.strftime("%d/%m/%Y"),
                "cliente_nome": nome.strip(), "documento": doc.strip(), "whatsapp": wa.strip(),
                "evento": evento.strip(),
                "cliente_cpf_cnpj": doc.strip(), "cliente_wa": wa.strip(),
                "relacionamento_id": (cliente_comercial_i811 or {}).get("id", proposta.get("relacionamento_id", "")),
                "modalidade_cobranca": modalidade_salvar_i811,
                "faturamento_mensal": mensal_salvar_i811,
                "financeiro_status": (proposta.get("financeiro_status") or "Aguardando fechamento mensal") if mensal_salvar_i811 else proposta.get("financeiro_status", ""),
                "pagamento": "Faturamento mensal conforme condição comercial cadastrada." if mensal_salvar_i811 else proposta.get("pagamento", "Pagamento via PIX: https://linkspix.app/alphafestitatiba"),
                "itens": list(itens), "subtotal": subtotal, "desconto": desconto, "desconto_valor": desconto,
                "valor_total": total, "prazo_dias": prazo, "frete_tipo": frete,
                "taxa_entrega": valor_float(taxa_entrega) if frete == "Entrega" else 0.0,
                "validade_dias": validade,
                "pago": proposta.get("pago", False), "entregue": proposta.get("entregue", False),
                "aprovado": proposta.get("aprovado", False),
                "timeline": proposta.get("timeline", []) if isinstance(proposta.get("timeline", []), list) else [],
                "atendimento_id": proposta.get("atendimento_id") or st.session_state.get("_atendimento_origem_id", ""),
                "projeto_id": proposta.get("projeto_id") or st.session_state.get("_projeto_origem_id", ""),
            }
            ok_salvar, retorno_salvar = _anna_salvar_proposta(dados, numero_original)
            if ok_salvar:
                registrar_atividade(obter_usuario_atual(), "Proposta salva", "Orçamentos", detalhe=f"{retorno_salvar} · {nome.strip()}", evento=True)
                st.session_state["anna_modal_itens"] = []
                st.session_state[chave_modal] = False
                st.rerun()
            else:
                st.error(retorno_salvar)
    else:
        st.info("Adicione pelo menos um item para concluir o orçamento.")


