def salvar_andamento_proposta(numero, aprovado, pago, entregue):
    """HF3: atualiza status sobre leitura fresca, com autoria real e confirmação."""
    novos = {"aprovado": valor_bool(aprovado), "pago": valor_bool(pago), "entregue": valor_bool(entregue)}
    usuario_status = str((obter_usuario_atual() or {}).get("nome") or "Sistema")
    controle = {"anteriores": None, "nova_conclusao": False, "aprovou_agora": False, "mudancas": []}

    def _mutar(proposta):
        anteriores = {
            "aprovado": valor_bool(proposta.get("aprovado", False)),
            "pago": valor_bool(proposta.get("pago", False)),
            "entregue": valor_bool(proposta.get("entregue", False)),
        }
        controle["anteriores"] = anteriores
        antes_concluida = proposta_concluida(proposta)
        proposta.update(novos)
        agora_status = agora_local().strftime("%d/%m/%Y %H:%M")
        for campo, campo_data in (("aprovado", "aprovado_em"), ("pago", "pago_em"), ("entregue", "entregue_em")):
            if novos[campo] and not anteriores[campo] and not proposta.get(campo_data):
                proposta[campo_data] = agora_status
            elif not novos[campo] and anteriores[campo]:
                proposta.pop(campo_data, None)

        rotulos = {
            "aprovado": "Orçamento aprovado",
            "pago": "Pagamento confirmado",
            "entregue": "Entrega concluída",
        }
        for campo, valor in novos.items():
            if anteriores[campo] != valor:
                texto = rotulos[campo] if valor else f"{rotulos[campo]} desmarcado"
                controle["mudancas"].append(texto)
                registrar_evento_proposta(proposta, texto, usuario=usuario_status)

        controle["aprovou_agora"] = novos["aprovado"] and not anteriores["aprovado"]
        depois_concluida = proposta_concluida(proposta)
        controle["nova_conclusao"] = depois_concluida and not antes_concluida
        if controle["nova_conclusao"]:
            if proposta_faturamento_mensal(proposta):
                descricao = "Aprovado e entregue — operação concluída; pagamento segue para Faturamento Mensal"
            else:
                descricao = "Aprovado, pago e entregue — proposta movida para o Histórico"
            registrar_evento_proposta(proposta, descricao, usuario=usuario_status)

    ok, atualizado, motivo = atualizar_proposta_com_leitura_fresca(numero, _mutar)
    if not ok:
        return False, f"Não foi possível atualizar a proposta com segurança ({motivo or 'falha de gravação'}). Tente novamente."

    # Confirma com leitura realmente fresca para que a tela do outro usuário veja
    # o mesmo estado que acabou de ser persistido.
    confirmado = next((p for p in carregar_historico(force_refresh=True) if p.get("numero_proposta") == numero), None)
    if confirmado is None:
        return False, "A proposta não foi localizada após a gravação."
    if any(valor_bool(confirmado.get(campo, False)) != valor for campo, valor in novos.items()):
        return False, "O banco recebeu outra atualização simultânea. Reabra a proposta e confirme os status atuais."

    if controle["mudancas"]:
        cliente_evt = str(confirmado.get("cliente_nome") or confirmado.get("cliente") or "Cliente").strip()
        registrar_atividade(
            obter_usuario_atual(),
            "Status da proposta atualizado",
            "Propostas",
            detalhe=f"{numero} · {cliente_evt} · " + " / ".join(controle["mudancas"]),
            evento=True,
        )
    if controle["aprovou_agora"]:
        sincronizar_producao_com_propostas()
    if proposta_concluida(confirmado):
        if proposta_faturamento_mensal(confirmado):
            return True, f"{numero} com operação concluída; pagamento segue para o Faturamento Mensal."
        return True, f"{numero} concluída e movida para o Histórico."
    return True, f"Andamento de {numero} atualizado por {usuario_status}."


@st.dialog("📦 Fluxo de pedidos", width="large")
def dialog_fluxo_anna():
    registrar_atividade(obter_usuario_atual(), "Atualizando fluxo de pedidos", "Fluxo de Pedidos")
    historico = carregar_historico(force_refresh=True)
    if not historico:
        st.info("Nenhuma proposta cadastrada.")
        return

    c_busca, c_status = st.columns([2, 1])
    busca = c_busca.text_input(
        "Pesquisar",
        placeholder="Cliente, proposta ou telefone",
        key="dlg_fluxo_busca",
    ).strip().lower()
    status = c_status.selectbox(
        "Mostrar",
        ["Todas", "Ativas", "Aguardando aprovação", "Aprovadas", "Pagas", "Entregues"],
        key="dlg_fluxo_status",
    )

    def atende_filtro(prop):
        texto = " ".join([
            str(prop.get("numero_proposta", "")),
            str(prop.get("cliente_nome", prop.get("cliente", ""))),
            str(prop.get("whatsapp", prop.get("cliente_wa", ""))),
        ]).lower()
        if busca and busca not in texto:
            return False
        aprovado = valor_bool(prop.get("aprovado", False))
        pago = valor_bool(prop.get("pago", False))
        entregue = valor_bool(prop.get("entregue", False))
        ativa = proposta_ativa_operacional(prop)
        return {
            "Todas": ativa,
            "Ativas": ativa,
            "Aguardando aprovação": ativa and not aprovado,
            "Aprovadas": ativa and aprovado,
            "Pagas": ativa and pago,
            "Entregues": ativa and entregue,
        }[status]

    propostas = [p for p in historico if atende_filtro(p)]
    st.caption(f"{len(propostas)} de {len(historico)} proposta(s) exibida(s)")
    if not propostas:
        st.warning("Nenhuma proposta encontrada com esse filtro.")
        return

    propostas.sort(key=lambda p: str(p.get("data_entrega", "")), reverse=False)
    for prop in propostas:
        numero = str(prop.get("numero_proposta", "")).strip()
        if not numero:
            continue
        chave_segura = "".join(ch if ch.isalnum() else "_" for ch in numero)
        with st.container(border=True):
            st.write(f"**{numero} — {prop.get('cliente_nome', prop.get('cliente', 'Cliente'))}**")
            st.caption(
                f"Entrega: {prop.get('data_entrega', '—')} · "
                f"{_anna_fmt_moeda(prop.get('valor_total', prop.get('total', 0)))}"
            )
            with st.form(f"dlg_fluxo_form_{chave_segura}"):
                c1, c2, c3 = st.columns(3)
                aprovado = c1.checkbox("Aprovado", value=valor_bool(prop.get("aprovado", False)))
                mensal_fluxo = proposta_faturamento_mensal(prop)
                pago = c2.checkbox(
                    "💳 Pago no fechamento mensal" if mensal_fluxo else "Pago",
                    value=valor_bool(prop.get("pago", False)),
                    disabled=mensal_fluxo,
                    help="Mensalistas recebem baixa somente pela Central de Faturamento Mensal." if mensal_fluxo else None,
                )
                entregue = c3.checkbox("Entregue", value=valor_bool(prop.get("entregue", False)))
                nf1, nf2 = st.columns(2)
                nao_pagto = nf1.checkbox("❌ Não fechado — falta de pagamento", value=valor_bool(prop.get("nao_fechado_pagamento")), key=f"nf_pag_{prop.get('numero_proposta')}")
                nao_retorno = nf2.checkbox("📵 Não fechado — sem retorno do cliente", value=valor_bool(prop.get("nao_fechado_sem_retorno")), key=f"nf_ret_{prop.get('numero_proposta')}")
                if nao_pagto != valor_bool(prop.get("nao_fechado_pagamento")):
                    alternar_motivo_nao_fechado(prop.get("numero_proposta"), "pagamento", nao_pagto); st.rerun()
                if nao_retorno != valor_bool(prop.get("nao_fechado_sem_retorno")):
                    alternar_motivo_nao_fechado(prop.get("numero_proposta"), "sem_retorno", nao_retorno); st.rerun()
                salvar = st.form_submit_button("💾 Salvar andamento", use_container_width=True)
            if salvar:
                ok, mensagem = salvar_andamento_proposta(numero, aprovado, pago, entregue)
                if ok:
                    st.session_state["_mensagem_sucesso_pendente"] = mensagem
                    st.rerun()
                else:
                    st.error(mensagem)



def _thu_i4_tokens(valor):
    """Tokens leves para comparar sugestão comercial com produto oficial."""
    import unicodedata
    texto = unicodedata.normalize("NFKD", str(valor or ""))
    texto = "".join(c for c in texto if not unicodedata.combining(c)).casefold()
    texto = re.sub(r"[^a-z0-9]+", " ", texto)
    ignorar = {
        "de", "do", "da", "dos", "das", "para", "com", "e",
        "personalizado", "personalizada", "personalizados", "personalizadas",
    }
    equivalencias = {
        "topos": "topo",
        "baloes": "balao",
        "lembrancinhas": "lembrancinha",
        "canecas": "caneca",
        "copos": "copo",
        "chaveiros": "chaveiro",
        "camisetas": "camiseta",
        "brindes": "brinde",
        "adesivos": "adesivo",
        "etiquetas": "etiqueta",
    }
    saida = []
    for token in texto.split():
        if token in ignorar:
            continue
        saida.append(equivalencias.get(token, token))
    return saida


def _thu_i4_termo_base(termo, campanha=""):
    """Retira qualificadores de campanha/cor para achar a família do produto."""
    tokens = _thu_i4_tokens(termo)
    camp_tokens = set(_thu_i4_tokens(campanha))
    qualificadores = {
        "rosa", "azul", "vermelho", "verde", "dourado", "branco", "preto",
        "natalino", "natalina", "maes", "mae", "pais", "pai", "crianca",
        "criancas", "outubro", "novembro", "pascoa", "halloween",
    } | camp_tokens
    base = [t for t in tokens if t not in qualificadores]
    return base or tokens


def _thu_i4_score_termo_produto(termo, produto, campanha=""):
    """Pontua sem decidir: nome/alias > família do nome > categoria."""
    termo_tokens = set(_thu_i4_termo_base(termo, campanha))
    if not termo_tokens:
        return 0, ""

    nomes = [str(produto.get("Nome") or "")] + [
        str(x) for x in (produto.get("Aliases", []) or []) if str(x).strip()
    ]
    melhor_nome = 0
    for nome in nomes:
        nome_tokens = set(_thu_i4_termo_base(nome, campanha))
        if not nome_tokens:
            continue
        if nome_tokens == termo_tokens:
            melhor_nome = max(melhor_nome, 100)
            continue
        inter = len(nome_tokens & termo_tokens)
        uniao = max(len(nome_tokens | termo_tokens), 1)
        jac = inter / uniao
        if termo_tokens <= nome_tokens or nome_tokens <= termo_tokens:
            melhor_nome = max(melhor_nome, 88 if inter >= 1 else 0)
        elif jac >= 0.66:
            melhor_nome = max(melhor_nome, 82)
        elif jac >= 0.45:
            melhor_nome = max(melhor_nome, 72)
        elif inter >= 1 and min(len(nome_tokens), len(termo_tokens)) == 1:
            melhor_nome = max(melhor_nome, 68)

    if melhor_nome:
        return melhor_nome, f"nome/alias relacionado a “{termo}”"

    categoria = " ".join([
        str(produto.get("Categoria") or ""),
        str(produto.get("Subcategoria") or ""),
    ])
    cat_tokens = set(_thu_i4_termo_base(categoria, campanha))
    inter_cat = len(cat_tokens & termo_tokens)
    if cat_tokens and termo_tokens and (
        termo_tokens <= cat_tokens or cat_tokens <= termo_tokens
    ):
        return 66, f"categoria relacionada a “{termo}”"
    if inter_cat and len(termo_tokens) == 1:
        return 62, f"família/categoria relacionada a “{termo}”"

    return 0, ""


def _thu_i4_termos_site_campanha(scan_site, campanha):
    """Extrai somente textos de links úteis de páginas históricas da campanha."""
    if not scan_site:
        return []
    try:
        scan = thu_site_reprocessar_scan(scan_site)
    except Exception:
        scan = dict(scan_site or {})

    campanha_norm = _thu_normalizar_campanha(campanha)
    termos = []
    bloqueados = {
        "inicio", "home", "contato", "quem somos", "loja", "mais itens",
        "instagram", "facebook", "whatsapp", "alpha fest", "alphafest",
    }

    for pagina in (scan.get("paginas") or []):
        if not isinstance(pagina, dict):
            continue
        camp_pg = _thu_normalizar_campanha(
            pagina.get("campanha") or pagina.get("nome") or pagina.get("texto_menu")
        )
        if camp_pg != campanha_norm:
            continue
        for link in (pagina.get("links") or []):
            texto = str((link or {}).get("texto") or "").strip()
            if not texto:
                continue
            norm = _thu_site_norm(texto)
            if not norm or norm in bloqueados or len(norm) < 3:
                continue
            tipo_link, _ = _thu_site_classificar_link(
                texto,
                str((link or {}).get("url") or ""),
            )
            if tipo_link in ("produto", "categoria", "servico"):
                termos.append(texto)

    return list(dict.fromkeys(termos))[:30]


def thu_sugerir_elegibilidade_campanha(
    catalogo,
    campanha,
    produtos_calendario=None,
    conteudos=None,
    scan_site=None,
):
    """I4 — sugere elegibilidade com evidência; não modifica o Catálogo."""
    campanha = _thu_normalizar_campanha(campanha)
    produtos_calendario = [
        str(x).strip() for x in (produtos_calendario or []) if str(x).strip()
    ]
    termos_site = _thu_i4_termos_site_campanha(scan_site, campanha)
    conteudos = conteudos or []

    candidatos = []
    elegiveis = []
    correspondencias_cal = set()

    for idx, produto in enumerate(catalogo or []):
        if produto.get("Ativo") is False:
            continue

        permitidas = list(produto.get("CampanhasPermitidas", []) or [])
        if (
            campanha in permitidas
            or "Permanente / Todas as épocas" in permitidas
        ):
            elegiveis.append({
                "indice": idx,
                "produto": produto,
                "motivo": (
                    "campanha explícita"
                    if campanha in permitidas
                    else "produto permanente"
                ),
            })
            continue

        score = 0
        evidencias = []
        fontes = []

        for termo in produtos_calendario:
            pts, motivo = _thu_i4_score_termo_produto(termo, produto, campanha)
            if pts:
                correspondencias_cal.add(termo)
                if pts > score:
                    score = pts
                evidencias.append(f"Calendário: {motivo}")
                fontes.append({"fonte": "Calendário", "termo": termo, "pontos": pts})

        melhor_site = 0
        melhor_site_motivo = ""
        melhor_site_termo = ""
        for termo in termos_site:
            pts, motivo = _thu_i4_score_termo_produto(termo, produto, campanha)
            if pts > melhor_site:
                melhor_site = pts
                melhor_site_motivo = motivo
                melhor_site_termo = termo
        if melhor_site >= 66:
            bonus_site = 18 if score else min(72, melhor_site)
            score = min(100, score + bonus_site) if score else bonus_site
            evidencias.append(f"Site legado: {melhor_site_motivo}")
            fontes.append({
                "fonte": "Site AlphaFest legado",
                "termo": melhor_site_termo,
                "pontos": melhor_site,
            })

        # Arte já classificada com esta campanha é uma evidência forte.
        campanha_norm = _thu_site_norm(campanha)
        artes_campanha = []
        for arte in thu_correlacionar_catalogo_biblioteca(produto, conteudos):
            texto_arte = _thu_site_norm(
                " ".join([
                    str(arte.get("campanha") or ""),
                    str(arte.get("tema_reuso") or ""),
                    str(arte.get("produto") or ""),
                ])
            )
            if campanha_norm and campanha_norm in texto_arte:
                artes_campanha.append(arte)

        if artes_campanha:
            score = min(100, max(score, 78) + (10 if score else 0))
            evidencias.append("Biblioteca: já existe arte relacionada a esta campanha")
            fontes.append({
                "fonte": "Biblioteca",
                "termo": campanha,
                "pontos": 78,
            })

        if score < 62:
            continue

        revisao = avaliar_pendencias_produto_catalogo(produto)
        # Nesta tela "Campanhas/Datas" não é tratada como falha:
        # justamente é o dado que o usuário está revisando aqui.
        pendencias_reais = [
            x for x in (revisao.get("criticas") or [])
            if str(x) != "Campanhas/Datas"
        ]
        candidatos.append({
            "indice": idx,
            "produto": produto,
            "score": int(min(score, 100)),
            "evidencias": list(dict.fromkeys(evidencias)),
            "fontes": fontes,
            "cadastro_pronto": not pendencias_reais,
            "pendencias": pendencias_reais,
        })

    candidatos.sort(
        key=lambda x: (
            x["score"],
            x["cadastro_pronto"],
            bool(x["produto"].get("Destaque")),
            str(x["produto"].get("Nome") or "").casefold(),
        ),
        reverse=True,
    )

    termos_sem_match = [
        termo for termo in produtos_calendario
        if termo not in correspondencias_cal
    ]

    return {
        "campanha": campanha,
        "candidatos": candidatos,
        "elegiveis": elegiveis,
        "termos_calendario": produtos_calendario,
        "termos_site": termos_site,
        "termos_sem_match": termos_sem_match,
    }


def thu_confirmar_elegibilidade_campanha(campanha, selecoes):
    """Grava somente seleções confirmadas e mantém auditoria da decisão."""
    campanha = _thu_normalizar_campanha(campanha)
    if campanha not in CAMPANHAS_PRODUTO_OPCOES:
        return False, "A campanha não existe nas opções oficiais do Catálogo.", 0

    catalogo = carregar_catalogo()
    mapa_selecoes = {
        normalizar_identidade_produto(str(item.get("nome") or "")): item
        for item in (selecoes or [])
        if str(item.get("nome") or "").strip()
    }
    alterados = 0

    for idx, produto in enumerate(catalogo):
        chave = normalizar_identidade_produto(produto.get("Nome"))
        selecao = mapa_selecoes.get(chave)
        if not selecao:
            continue

        registro = dict(produto)
        permitidas = list(registro.get("CampanhasPermitidas", []) or [])
        if campanha not in permitidas:
            permitidas.append(campanha)
            registro["CampanhasPermitidas"] = list(dict.fromkeys(permitidas))

            hist = list(registro.get("HistoricoElegibilidadeTHU", []) or [])
            hist.append({
                "campanha": campanha,
                "acao": "Habilitada com confirmação humana",
                "evidencias": list(selecao.get("evidencias") or []),
                "fontes": list(selecao.get("fontes") or []),
                "confirmado_em": agora_local().isoformat(timespec="seconds"),
                "usuario": obter_usuario_atual(),
            })
            registro["HistoricoElegibilidadeTHU"] = hist[-100:]
            registro["AtualizadoEm"] = agora_local().isoformat(timespec="seconds")
            catalogo[idx] = registro
            alterados += 1

    if alterados:
        salvar_catalogo(catalogo)
        return True, f"{alterados} produto(s) habilitado(s) para {campanha}.", alterados

    return False, "Nenhum produto novo foi habilitado.", 0



def _thu_i5_campanha_salva(marketing, campanha, produto_nome=""):
    """Localiza copy THU já preparada para a mesma campanha/produto."""
    camp = _thu_normalizar_campanha(campanha)
    prod_key = normalizar_identidade_produto(produto_nome)
    encontrados = []
    for item in (marketing or {}).get("thu_campanhas_sugeridas", []) or []:
        if _thu_normalizar_campanha(item.get("campanha")) != camp:
            continue
        if prod_key and normalizar_identidade_produto(item.get("produto")) != prod_key:
            continue
        encontrados.append(item)
    encontrados.sort(
        key=lambda x: str(x.get("gerado_em") or ""),
        reverse=True,
    )
    return encontrados[0] if encontrados else None


def thu_montar_plano_execucao_campanhas(
    catalogo,
    conteudos,
    marketing,
    referencia=None,
    limite_dias=120,
):
    """I5 — transforma oportunidades em próximas ações operacionais de Marketing."""
    referencia = referencia or hoje_local()
    planos = []

    for oportunidade in campanhas_em_oportunidade(
        referencia=referencia,
        limite_dias=limite_dias,
    ):
        campanha = str(oportunidade.get("nome") or "").strip()
        inicio = oportunidade.get("inicio_calculado")
        fim = oportunidade.get("fim_calculado")
        dias_inicio = int(oportunidade.get("dias_para_inicio") or 0)
        antecedencia = int(oportunidade.get("antecedencia_dias", 30) or 30)
        data_preparar = (
            inicio - timedelta(days=antecedencia)
            if isinstance(inicio, date)
            else None
        )

        ops = thu_priorizar_oportunidades(
            catalogo,
            conteudos,
            campanha,
            dias_para_inicio=dias_inicio,
        )

        for _op_social in ops:
            _produto_social = (_op_social.get("produto") or {}).get("Nome")
            _frescor = thu_social_frescor_produto(
                marketing,
                _produto_social,
                referencia=referencia,
            )
            _op_social["ajuste_social"] = int(_frescor.get("ajuste") or 0)
            _op_social["nota_social"] = str(_frescor.get("nota") or "")
            _op_social["indice_execucao"] = max(
                0,
                min(
                    100,
                    int(_op_social.get("indice_prontidao") or 0)
                    + int(_frescor.get("ajuste") or 0),
                ),
            )

        prontos = [x for x in ops if x.get("pronto_divulgar")]
        prontos.sort(
            key=lambda x: (
                int(x.get("indice_execucao") or 0),
                int(x.get("indice_prontidao") or 0),
            ),
            reverse=True,
        )
        sem_arte = [
            x for x in ops
            if x.get("pronto_cadastro") and not x.get("tem_arte")
        ]
        incompletos = [x for x in ops if not x.get("pronto_cadastro")]

        recomendado = (
            prontos[0]
            if prontos
            else (sem_arte[0] if sem_arte else (incompletos[0] if incompletos else None))
        )
        produto = (recomendado or {}).get("produto") or {}
        produto_nome = str(produto.get("Nome") or "").strip()
        arte = (recomendado or {}).get("arte_recomendada")
        salva = (
            _thu_i5_campanha_salva(marketing, campanha, produto_nome)
            if produto_nome
            else None
        )
        publicacoes_campanha = []
        if produto_nome:
            _pubs_mesmo_produto = thu_social_publicacoes_da_campanha(
                marketing,
                campanha,
                produto_nome,
            )
            if salva:
                _chave_salva = thu_social_chave_campanha(salva)
                publicacoes_campanha = [
                    x for x in _pubs_mesmo_produto
                    if str(x.get("campanha_preparada_chave") or "") == _chave_salva
                ]

            # Publicação manual/avulsa também encerra a etapa quando ocorreu
            # na janela desta campanha. Histórico de anos anteriores não conta.
            if not publicacoes_campanha:
                for _pub in _pubs_mesmo_produto:
                    _data_pub = _thu_social_data(_pub.get("data_publicacao"))
                    if not _data_pub:
                        continue
                    _inicio_janela = data_preparar or inicio
                    if isinstance(_inicio_janela, date) and _data_pub < _inicio_janela:
                        continue
                    if isinstance(fim, date) and _data_pub > fim:
                        continue
                    publicacoes_campanha.append(_pub)

        if publicacoes_campanha:
            etapa = "Campanha publicada"
            acao = "ver_publicacao"
            icone = "📣"
        elif salva:
            etapa = "Campanha preparada"
            acao = "ver_campanha"
            icone = "✅"
        elif prontos:
            etapa = "Preparar campanha"
            acao = "preparar_campanha"
            icone = "🟢"
        elif sem_arte:
            etapa = "Cadastrar arte"
            acao = "cadastrar_arte"
            icone = "🟡"
        elif incompletos:
            etapa = "Revisar cadastro"
            acao = "revisar_cadastro"
            icone = "🟠"
        else:
            etapa = "Revisar elegibilidade"
            acao = "revisar_elegibilidade"
            icone = "🔵"

        em_periodo = bool(oportunidade.get("em_periodo"))
        dias_prazo = (
            (data_preparar - referencia).days
            if isinstance(data_preparar, date)
            else None
        )

        if publicacoes_campanha:
            urgencia = "Publicada"
            ordem_urgencia = 0
        elif salva:
            urgencia = "Preparada"
            ordem_urgencia = 1
        elif em_periodo:
            urgencia = "Ação imediata"
            ordem_urgencia = 5
        elif isinstance(data_preparar, date) and referencia > data_preparar:
            urgencia = "Preparação atrasada"
            ordem_urgencia = 5
        elif isinstance(data_preparar, date) and referencia == data_preparar:
            urgencia = "Preparar hoje"
            ordem_urgencia = 4
        elif isinstance(dias_prazo, int) and dias_prazo <= 7:
            urgencia = f"Preparar em {max(dias_prazo, 0)} dia(s)"
            ordem_urgencia = 4
        elif dias_inicio <= 30:
            urgencia = "Próxima"
            ordem_urgencia = 3
        else:
            urgencia = "Programada"
            ordem_urgencia = 2

        idx_prod = None
        if produto_nome:
            idx_prod = next(
                (
                    i for i, p in enumerate(catalogo or [])
                    if normalizar_identidade_produto(p.get("Nome"))
                    == normalizar_identidade_produto(produto_nome)
                ),
                None,
            )

        planos.append({
            "id": str(oportunidade.get("id") or campanha),
            "campanha": campanha,
            "inicio": inicio,
            "fim": fim,
            "dias_para_inicio": dias_inicio,
            "antecedencia_dias": antecedencia,
            "data_preparar": data_preparar,
            "urgencia": urgencia,
            "ordem_urgencia": ordem_urgencia,
            "etapa": etapa,
            "acao": acao,
            "icone": icone,
            "produto": produto,
            "produto_nome": produto_nome,
            "produto_indice": idx_prod,
            "arte": arte,
            "nota_social": str((recomendado or {}).get("nota_social") or ""),
            "indice_execucao": int((recomendado or {}).get("indice_execucao") or 0),
            "campanha_salva": salva,
            "publicacoes": publicacoes_campanha,
            "elegiveis": len(ops),
            "prontos": len(prontos),
            "sem_arte": len(sem_arte),
            "incompletos": len(incompletos),
            "produtos_calendario": list(oportunidade.get("produtos", []) or []),
            "tipo": oportunidade.get("tipo", "Campanha"),
        })

    planos.sort(
        key=lambda x: (
            -int(x.get("ordem_urgencia") or 0),
            x.get("inicio") or date.max,
            str(x.get("campanha") or "").casefold(),
        )
    )
    return planos


def _thu_i6_abrir_registro_preparada(campanha_salva):
    for chave in list(st.session_state.keys()):
        if str(chave).startswith("thu_i6_"):
            st.session_state.pop(chave, None)
    st.session_state["_thu_i6_publicar_chave"] = thu_social_chave_campanha(
        campanha_salva or {}
    )
    st.session_state["_thu_i6_abrir"] = True


def _thu_i5_acionar_plano(item, prefixo):
    """Executa somente navegação/preenchimento; não toma decisão comercial sozinho."""
    acao = str(item.get("acao") or "")
    campanha = str(item.get("campanha") or "")
    produto = item.get("produto") or {}
    produto_nome = str(item.get("produto_nome") or "")
    arte = item.get("arte") or {}

    if acao == "revisar_elegibilidade":
        dialog_thu_revisar_elegibilidade(campanha)
        return

    if acao == "revisar_cadastro":
        idx = item.get("produto_indice")
        if idx is not None:
            dialog_catalogo_cadastro_anna(produto_indice=int(idx))
        return

    if acao == "cadastrar_arte":
        st.session_state["_thu_i5_preencher_arte"] = {
            "produto": produto_nome,
            "categoria": str(produto.get("Categoria") or ""),
            "campanha": campanha,
        }
        st.rerun()

    if acao == "preparar_campanha":
        st.session_state["thu_campanha_preparar_2049c"] = {
            "produto": produto_nome,
            "campanha": campanha,
            "arte_id": str(arte.get("id") or ""),
        }
        st.rerun()


def renderizar_plano_execucao_thu(
    marketing,
    conteudos,
    prefixo="thu_i5",
    compacto=False,
    limite_dias=120,
):
    catalogo = carregar_catalogo()
    planos = thu_montar_plano_execucao_campanhas(
        catalogo,
        conteudos,
        marketing,
        referencia=hoje_local(),
        limite_dias=limite_dias,
    )

    if not planos:
        st.info("Nenhuma campanha em janela de planejamento neste período.")
        return []

    pendentes = [
        p for p in planos
        if p.get("acao") not in ("ver_campanha", "ver_publicacao")
    ]
    preparadas = [p for p in planos if p.get("acao") == "ver_campanha"]
    publicadas = [p for p in planos if p.get("acao") == "ver_publicacao"]
    atrasadas = [
        p for p in pendentes
        if p.get("urgencia") in ("Ação imediata", "Preparação atrasada")
    ]
    falta_arte = [p for p in pendentes if p.get("acao") == "cadastrar_arte"]

    if not compacto:
        m1, m2, m3, m4, m5 = st.columns(5)
        m1.metric("Campanhas no plano", len(planos))
        m2.metric("Ação agora / atrasadas", len(atrasadas))
        m3.metric("Preparadas", len(preparadas))
        m4.metric("Publicadas", len(publicadas))
        m5.metric("Aguardando arte", len(falta_arte))
        st.caption(
            "O prazo de preparação vem da antecedência cadastrada no Calendário. "
            "O THU organiza o trabalho; não publica nem aprova nada automaticamente."
        )

    limite_cards = 4 if compacto else 15
    exibidos = planos[:limite_cards]

    for pos, item in enumerate(exibidos, 1):
        campanha = item["campanha"]
        inicio = item.get("inicio")
        data_preparar = item.get("data_preparar")
        produto_nome = item.get("produto_nome")
        acao = item.get("acao")

        with st.container(border=True):
            c1, c2 = st.columns([4.4, 1.45])
            c1.markdown(
                f"**{item.get('icone','')} {campanha}** "
                f"• {item.get('etapa')} • **{item.get('urgencia')}**"
            )

            datas = []
            if isinstance(inicio, date):
                datas.append(f"início {inicio.strftime('%d/%m/%Y')}")
            if isinstance(data_preparar, date):
                datas.append(f"preparar até {data_preparar.strftime('%d/%m/%Y')}")
            c1.caption(" • ".join(datas))

            if produto_nome:
                c1.caption(
                    f"🎯 Produto priorizado: **{produto_nome}** • "
                    f"{item.get('elegiveis',0)} elegível(eis) • "
                    f"{item.get('prontos',0)} pronto(s) • "
                    f"{item.get('sem_arte',0)} sem arte"
                )
                if item.get("nota_social"):
                    c1.caption(
                        "📱 Memória social: " + str(item.get("nota_social"))
                        + ". Este ajuste serve apenas para diversidade de divulgação."
                    )
            elif item.get("produtos_calendario"):
                c1.caption(
                    "📅 Calendário sugere: "
                    + " • ".join(item.get("produtos_calendario")[:6])
                )
            else:
                c1.caption("Ainda não há produto oficial elegível para esta campanha.")

            if acao == "revisar_elegibilidade":
                label = "📅 Revisar elegibilidade"
            elif acao == "revisar_cadastro":
                label = "✏️ Revisar cadastro"
            elif acao == "cadastrar_arte":
                label = "🎨 Cadastrar arte"
            elif acao == "preparar_campanha":
                label = "💙 Preparar campanha"
            else:
                label = ""

            if acao not in ("ver_campanha", "ver_publicacao"):
                if c2.button(
                    label,
                    key=f"{prefixo}_acao_{pos}_{abs(hash((item.get('id'), campanha, acao)))}",
                    use_container_width=True,
                ):
                    _thu_i5_acionar_plano(item, prefixo)

            elif acao == "ver_campanha":
                salva = item.get("campanha_salva") or {}
                c2.success("Preparada")
                if c2.button(
                    "📤 Registrar publicação",
                    key=f"{prefixo}_publicar_{pos}_{abs(hash((item.get('id'), campanha)))}",
                    use_container_width=True,
                ):
                    _thu_i6_abrir_registro_preparada(salva)
                    if compacto:
                        rerun_na_aba("marketing")
                    else:
                        st.rerun()

                with c1.expander("Ver campanha preparada", expanded=False):
                    st.caption(
                        f"Produto: {salva.get('produto') or produto_nome} • "
                        f"Gerada em: {str(salva.get('gerado_em') or '')[:16].replace('T',' ')}"
                    )
                    if salva.get("legenda"):
                        st.text_area(
                            "Legenda Feed",
                            value=str(salva.get("legenda") or ""),
                            height=170,
                            disabled=True,
                            key=f"{prefixo}_legenda_salva_{pos}_{abs(hash(campanha))}",
                        )
                    if salva.get("story"):
                        st.text_area(
                            "Story / Status",
                            value=str(salva.get("story") or ""),
                            height=110,
                            disabled=True,
                            key=f"{prefixo}_story_salvo_{pos}_{abs(hash(campanha))}",
                        )

            else:
                c2.success("Publicada")
                publicacoes_item = list(item.get("publicacoes") or [])
                salva = item.get("campanha_salva") or {}
                if salva and c2.button(
                    "➕ Outro canal",
                    key=f"{prefixo}_outro_canal_{pos}_{abs(hash((item.get('id'), campanha)))}",
                    use_container_width=True,
                ):
                    _thu_i6_abrir_registro_preparada(salva)
                    if compacto:
                        rerun_na_aba("marketing")
                    else:
                        st.rerun()

                with c1.expander("Ver histórico de publicação", expanded=False):
                    for pub in publicacoes_item[:8]:
                        st.write(
                            f"• **{pub.get('canal') or 'Canal'}** — "
                            f"{pub.get('data_publicacao') or '—'}"
                        )
                        if pub.get("link"):
                            st.link_button(
                                "Abrir publicação",
                                str(pub.get("link")),
                            )

    return planos



# --- 20.4.9-I6: THU Acervo Social + Histórico de Publicações ---
THU_SOCIAL_CANAIS = [
    "Instagram Feed",
    "Instagram Story",
    "Instagram Reel",
    "Instagram Carrossel",
    "Facebook",
    "Status WhatsApp",
]

THU_SOCIAL_ORIGENS = [
    "Campanha preparada pelo THU",
    "Publicação histórica",
    "Publicação avulsa",
]


def thu_social_chave_campanha(campanha):
    campanha = campanha or {}
    base = "|".join([
        normalizar_identidade_produto(campanha.get("produto")),
        _thu_normalizar_campanha(campanha.get("campanha")),
        str(campanha.get("arte_id") or ""),
        str(campanha.get("gerado_em") or ""),
    ])
    return hashlib.sha1(base.encode("utf-8")).hexdigest()[:18]


def _thu_social_data(valor):
    if isinstance(valor, datetime):
        return valor.date()
    if isinstance(valor, date):
        return valor
    texto = str(valor or "").strip()
    if not texto:
        return None
    try:
        return datetime.fromisoformat(texto.replace("Z", "+00:00")).date()
    except Exception:
        pass
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(texto[:19], fmt).date()
        except Exception:
            pass
    return None


def _thu_social_publicacoes(marketing, incluir_anuladas=False):
    itens = [
        dict(x) for x in (marketing or {}).get("publicacoes_sociais", []) or []
        if isinstance(x, dict)
    ]
    if not incluir_anuladas:
        itens = [x for x in itens if not x.get("anulada")]
    itens.sort(
        key=lambda x: (
            str(x.get("data_publicacao") or ""),
            str(x.get("registrado_em") or ""),
        ),
        reverse=True,
    )
    return itens


def thu_social_publicacoes_da_campanha(marketing, campanha, produto_nome=""):
    camp = _thu_normalizar_campanha(campanha)
    produto_key = normalizar_identidade_produto(produto_nome)
    encontrados = []
    for item in _thu_social_publicacoes(marketing):
        if camp and _thu_normalizar_campanha(item.get("campanha")) != camp:
            continue
        if produto_key and normalizar_identidade_produto(item.get("produto")) != produto_key:
            continue
        encontrados.append(item)
    return encontrados


def thu_social_ultima_publicacao_produto(marketing, produto_nome):
    chave = normalizar_identidade_produto(produto_nome)
    if not chave:
        return None
    itens = [
        x for x in _thu_social_publicacoes(marketing)
        if normalizar_identidade_produto(x.get("produto")) == chave
    ]
    return itens[0] if itens else None


def thu_social_frescor_produto(marketing, produto_nome, referencia=None):
    """Ajuste pequeno para diversidade; nunca substitui prontidão/cadastro."""
    referencia = referencia or hoje_local()
    ultima = thu_social_ultima_publicacao_produto(marketing, produto_nome)
    if not ultima:
        return {
            "dias": None,
            "ajuste": 5,
            "nota": "produto sem publicação registrada no histórico social",
        }

    data_pub = _thu_social_data(ultima.get("data_publicacao"))
    if not data_pub:
        return {"dias": None, "ajuste": 0, "nota": ""}

    dias = (referencia - data_pub).days
    if dias < 0:
        return {"dias": dias, "ajuste": 0, "nota": ""}
    if dias <= 7:
        return {
            "dias": dias,
            "ajuste": -18,
            "nota": f"produto publicado há {dias} dia(s); considerar variar o conteúdo",
        }
    if dias <= 14:
        return {
            "dias": dias,
            "ajuste": -12,
            "nota": f"produto publicado há {dias} dias",
        }
    if dias <= 30:
        return {
            "dias": dias,
            "ajuste": -6,
            "nota": f"produto publicado há {dias} dias",
        }
    if dias >= 45:
        return {
            "dias": dias,
            "ajuste": 5,
            "nota": f"produto sem publicação há {dias} dias",
        }
    return {"dias": dias, "ajuste": 0, "nota": f"última publicação há {dias} dias"}


def thu_social_alertas_repeticao(
    marketing,
    produto_nome,
    canal,
    arte_id="",
    data_publicacao=None,
):
    """Alerta; nunca bloqueia publicação."""
    alvo = data_publicacao or hoje_local()
    if isinstance(alvo, datetime):
        alvo = alvo.date()
    produto_key = normalizar_identidade_produto(produto_nome)
    arte_id = str(arte_id or "").strip()
    canal = str(canal or "").strip()
    alertas = []

    for item in _thu_social_publicacoes(marketing):
        data_item = _thu_social_data(item.get("data_publicacao"))
        if not data_item:
            continue
        delta = (alvo - data_item).days
        if delta < 0:
            continue

        mesmo_produto = (
            produto_key
            and normalizar_identidade_produto(item.get("produto")) == produto_key
        )
        mesmo_canal = canal and str(item.get("canal") or "") == canal
        mesma_arte = arte_id and str(item.get("arte_id") or "") == arte_id

        if mesmo_produto and mesmo_canal and delta <= 14:
            alertas.append(
                f"{produto_nome} já foi registrado em {canal} há {delta} dia(s)."
            )
        if mesma_arte and delta <= 30:
            alertas.append(
                f"A mesma arte já foi registrada há {delta} dia(s) em {item.get('canal') or 'outro canal'}."
            )

    return list(dict.fromkeys(alertas))


def thu_social_link_coerente(canal, link):
    link = str(link or "").strip()
    if not link:
        return True, ""
    try:
        parsed = urllib.parse.urlparse(link)
        host = (parsed.hostname or "").casefold()
    except Exception:
        return False, "Link não reconhecido."

    if parsed.scheme not in ("http", "https") or not host:
        return False, "Use um link completo começando por https://."

    if canal.startswith("Instagram"):
        esperado = ("instagram.com", "www.instagram.com")
        if host not in esperado:
            return False, "O canal é Instagram, mas o link não aponta para instagram.com."
    elif canal == "Facebook":
        if host not in ("facebook.com", "www.facebook.com", "m.facebook.com"):
            return False, "O canal é Facebook, mas o link não aponta para facebook.com."
    return True, ""


def salvar_upload_social(upload):
    """Usa armazenamento persistente existente, mas em namespace separado do Catálogo."""
    if upload is None:
        return ""
    return upload_catalog_image(upload, "social_uploads")


def thu_social_registrar_publicacao(
    marketing,
    *,
    origem,
    canal,
    data_publicacao,
    tipo_midia="Imagem",
    produto="",
    campanha="",
    arte_id="",
    legenda="",
    link="",
    observacao="",
    imagem="",
    campanha_preparada=None,
):
    """Registra fato de publicação. Não publica em rede social."""
    marketing = marketing or {}
    publicacoes = list(marketing.get("publicacoes_sociais", []) or [])

    data_obj = _thu_social_data(data_publicacao) or hoje_local()
    agora = agora_local()
    chave_preparada = (
        thu_social_chave_campanha(campanha_preparada)
        if campanha_preparada
        else ""
    )

    base_id = "|".join([
        data_obj.isoformat(),
        str(canal or ""),
        normalizar_identidade_produto(produto),
        _thu_normalizar_campanha(campanha),
        str(arte_id or ""),
        str(link or ""),
        str(agora.isoformat()),
    ])
    registro = {
        "id": "SOC-" + hashlib.sha1(base_id.encode("utf-8")).hexdigest()[:16].upper(),
        "origem": str(origem or "Publicação avulsa"),
        "canal": str(canal or "").strip(),
        "tipo_midia": str(tipo_midia or "Imagem").strip(),
        "data_publicacao": data_obj.isoformat(),
        "produto": str(produto or "").strip(),
        "campanha": _thu_normalizar_campanha(campanha),
        "arte_id": str(arte_id or "").strip(),
        "legenda": str(legenda or "").strip(),
        "link": str(link or "").strip(),
        "observacao": str(observacao or "").strip(),
        "imagem": str(imagem or "").strip(),
        "campanha_preparada_chave": chave_preparada,
        "registrado_em": agora.isoformat(timespec="seconds"),
        "usuario": obter_usuario_atual(),
        "anulada": False,
    }
    publicacoes.insert(0, registro)
    marketing["publicacoes_sociais"] = publicacoes[:1000]

    if chave_preparada:
        campanhas = list(marketing.get("thu_campanhas_sugeridas", []) or [])
        for idx, item in enumerate(campanhas):
            if thu_social_chave_campanha(item) != chave_preparada:
                continue
            atualizado = dict(item)
            ids = list(atualizado.get("publicacoes_ids", []) or [])
            if registro["id"] not in ids:
                ids.append(registro["id"])
            atualizado["publicacoes_ids"] = ids[-50:]
            atualizado["status_publicacao"] = "Publicada"
            atualizado["ultima_publicacao_em"] = data_obj.isoformat()
            atualizado["ultima_publicacao_canal"] = registro["canal"]
            campanhas[idx] = atualizado
            break
        marketing["thu_campanhas_sugeridas"] = campanhas

    salvar_marketing(marketing)
    return registro


def thu_social_anular_publicacao(marketing, publicacao_id, motivo=""):
    """Não apaga histórico: marca o registro como anulado."""
    marketing = marketing or {}
    publicacoes = list(marketing.get("publicacoes_sociais", []) or [])
    alterou = False
    for idx, item in enumerate(publicacoes):
        if str(item.get("id") or "") != str(publicacao_id or ""):
            continue
        reg = dict(item)
        reg["anulada"] = True
        reg["anulada_em"] = agora_local().isoformat(timespec="seconds")
        reg["anulada_por"] = obter_usuario_atual()
        reg["motivo_anulacao"] = str(motivo or "").strip()
        publicacoes[idx] = reg
        alterou = True
        break
    if alterou:
        marketing["publicacoes_sociais"] = publicacoes

        # Recalcula o status da campanha preparada sem apagar histórico.
        chave_anulada = ""
        for item in publicacoes:
            if str(item.get("id") or "") == str(publicacao_id or ""):
                chave_anulada = str(item.get("campanha_preparada_chave") or "")
                break

        if chave_anulada:
            ainda_ativas = any(
                str(x.get("campanha_preparada_chave") or "") == chave_anulada
                and not x.get("anulada")
                for x in publicacoes
            )
            if not ainda_ativas:
                campanhas = list(marketing.get("thu_campanhas_sugeridas", []) or [])
                for idx, camp in enumerate(campanhas):
                    if thu_social_chave_campanha(camp) != chave_anulada:
                        continue
                    atualizado = dict(camp)
                    atualizado["status_publicacao"] = "Preparada"
                    atualizado.pop("ultima_publicacao_em", None)
                    atualizado.pop("ultima_publicacao_canal", None)
                    campanhas[idx] = atualizado
                    break
                marketing["thu_campanhas_sugeridas"] = campanhas

        salvar_marketing(marketing)
    return alterou


def thu_social_resumo(marketing, referencia=None):
    referencia = referencia or hoje_local()
    publicacoes = _thu_social_publicacoes(marketing)
    mes = [
        x for x in publicacoes
        if (_thu_social_data(x.get("data_publicacao")) or date.min).year == referencia.year
        and (_thu_social_data(x.get("data_publicacao")) or date.min).month == referencia.month
    ]
    ultimos_30 = [
        x for x in publicacoes
        if _thu_social_data(x.get("data_publicacao"))
        and 0 <= (referencia - _thu_social_data(x.get("data_publicacao"))).days <= 30
    ]
    produtos_30 = {
        normalizar_identidade_produto(x.get("produto"))
        for x in ultimos_30
        if normalizar_identidade_produto(x.get("produto"))
    }
    return {
        "total": len(publicacoes),
        "mes": len(mes),
        "ultimos_30": len(ultimos_30),
        "produtos_30": len(produtos_30),
    }


@st.dialog("📸 Assistente THU • Aproveitar imagem social", width="large")
def dialog_thu_aproveitar_imagem_social(publicacao_id):
    marketing = carregar_marketing()
    publicacao = next(
        (
            x for x in _thu_social_publicacoes(marketing)
            if str(x.get("id") or "") == str(publicacao_id or "")
        ),
        None,
    )
    if not publicacao:
        st.error("Publicação não localizada.")
        return

    imagem = str(publicacao.get("imagem") or "").strip()
    produto_nome = str(publicacao.get("produto") or "").strip()
    if not imagem:
        st.warning("Este registro social não possui imagem/print armazenado.")
        return
    if not produto_nome:
        st.warning("Vincule a publicação a um produto oficial antes de aproveitar a imagem.")
        return

    catalogo = carregar_catalogo()
    idx_prod = next(
        (
            i for i, p in enumerate(catalogo)
            if normalizar_identidade_produto(p.get("Nome"))
            == normalizar_identidade_produto(produto_nome)
        ),
        None,
    )
    if idx_prod is None:
        st.warning("O produto vinculado não existe mais no Catálogo oficial.")
        return

    produto = dict(catalogo[idx_prod])
    st.markdown(f"### {produto.get('Nome')}")
    st.caption(
        "A imagem veio de uma publicação social e pode estar comprimida. "
        "Por segurança, ela não pode substituir a foto principal nesta etapa."
    )
    try:
        st.image(imagem_streamlit_catalogo(imagem), width=360)
    except Exception:
        st.caption("Prévia indisponível.")

    modo = st.radio(
        "Como aproveitar esta imagem?",
        [
            "Adicionar como referência secundária",
            "Salvar como variação do produto",
        ],
        key=f"thu_i6_aproveitar_modo_{publicacao_id}",
    )
    observacao = st.text_input(
        "Descrição da variação/referência (opcional)",
        placeholder="Ex.: versão rosa, nova estampa, acabamento diferente...",
        key=f"thu_i6_aproveitar_obs_{publicacao_id}",
    )

    if st.button(
        "✅ Confirmar no banco de imagens",
        type="primary",
        use_container_width=True,
        key=f"thu_i6_aproveitar_confirmar_{publicacao_id}",
    ):
        imagens = list(produto.get("Imagens", []) or [])
        ja_existe = imagem in imagens
        if not ja_existe:
            imagens.append(imagem)
            produto["Imagens"] = imagens

        acao = (
            "Acervo Social — variação"
            if modo == "Salvar como variação do produto"
            else "Acervo Social — referência secundária"
        )
        hist = list(produto.get("BancoImagensHistorico", []) or [])
        hist.append({
            "origem": "Acervo Social AlphaFest",
            "publicacao_id": str(publicacao.get("id") or ""),
            "canal": str(publicacao.get("canal") or ""),
            "link": str(publicacao.get("link") or ""),
            "acao": acao,
            "fotos": [imagem],
            "observacao": str(observacao or "").strip(),
            "adicionado_em": agora_local().isoformat(timespec="seconds"),
            "usuario": obter_usuario_atual(),
        })
        produto["BancoImagensHistorico"] = hist[-150:]

        if modo == "Salvar como variação do produto":
            variacoes = list(produto.get("VariacoesImagem", []) or [])
            variacoes.append({
                "origem": "Acervo Social AlphaFest",
                "publicacao_id": str(publicacao.get("id") or ""),
                "canal": str(publicacao.get("canal") or ""),
                "fotos": [imagem],
                "descricao": (
                    str(observacao or "").strip()
                    or "Variação registrada a partir de publicação social"
                ),
                "criado_em": agora_local().isoformat(timespec="seconds"),
            })
            produto["VariacoesImagem"] = variacoes[-150:]

        produto["AtualizadoEm"] = agora_local().isoformat(timespec="seconds")
        catalogo[idx_prod] = produto
        salvar_catalogo(catalogo)

        st.session_state["_thu_auditar_produto_nome"] = produto.get("Nome")
        st.session_state["_thu_i6_feedback"] = (
            "Imagem social já existia no produto; histórico atualizado."
            if ja_existe
            else f"Imagem social adicionada ao banco de {produto.get('Nome')} como "
                 + ("variação." if modo == "Salvar como variação do produto" else "referência secundária.")
        )
        st.rerun()


def renderizar_acervo_social_thu(marketing, conteudos):
    """Painel manual primeiro; futura API Meta pode alimentar a mesma estrutura."""
    catalogo = carregar_catalogo()
    publicacoes = _thu_social_publicacoes(marketing)
    resumo = thu_social_resumo(marketing)

    sm1, sm2, sm3, sm4 = st.columns(4)
    sm1.metric("Publicações registradas", resumo["total"])
    sm2.metric("Neste mês", resumo["mes"])
    sm3.metric("Últimos 30 dias", resumo["ultimos_30"])
    sm4.metric("Produtos divulgados / 30d", resumo["produtos_30"])

    st.caption(
        "Nesta versão o registro é manual e confiável. O sistema não faz scraping contínuo de Instagram/Facebook. "
        "Quando a API oficial da Meta for conectada, ela poderá alimentar este mesmo histórico."
    )
    perf1, perf2, perf3 = st.columns([1, 1, 2])
    perf1.link_button(
        "📸 Abrir Instagram AlphaFest",
        "https://www.instagram.com/alphafest10/",
        use_container_width=True,
    )
    perf2.link_button(
        "📘 Abrir Facebook AlphaFest",
        "https://www.facebook.com/alphafest10",
        use_container_width=True,
    )
    perf3.caption(
        "Use estes atalhos para revisar publicações antigas e registrar no Acervo Social somente o que realmente vale preservar."
    )

    tab_reg, tab_hist, tab_prod = st.tabs([
        "📤 Registrar publicação",
        "🕘 Histórico social",
        "📦 Memória por produto",
    ])

    with tab_reg:
        campanhas_preparadas = list(marketing.get("thu_campanhas_sugeridas", []) or [])
        campanhas_preparadas.sort(
            key=lambda x: str(x.get("gerado_em") or ""),
            reverse=True,
        )

        chave_prefill = str(st.session_state.get("_thu_i6_publicar_chave") or "")
        origem_index = 0 if chave_prefill else 1
        origem = st.selectbox(
            "Origem do registro",
            THU_SOCIAL_ORIGENS,
            index=origem_index,
            key="thu_i6_origem",
        )

        preparada = None
        if origem == "Campanha preparada pelo THU":
            if not campanhas_preparadas:
                st.info("Ainda não há campanha preparada pelo THU.")
            else:
                labels = []
                mapa_preparadas = {}
                for _pos_pre, item in enumerate(campanhas_preparadas, 1):
                    chave = thu_social_chave_campanha(item)
                    _gerado_label = str(item.get("gerado_em") or "")[:16].replace("T", " ")
                    label = (
                        f"{item.get('campanha') or 'Campanha livre'} • "
                        f"{item.get('produto') or 'Produto'} • "
                        f"{_gerado_label or 'sem data'} • #{_pos_pre}"
                    )
                    labels.append(label)
                    mapa_preparadas[label] = item

                index_pre = 0
                if chave_prefill:
                    for pos, label in enumerate(labels):
                        if thu_social_chave_campanha(mapa_preparadas[label]) == chave_prefill:
                            index_pre = pos
                            break
                label_preparada = st.selectbox(
                    "Campanha preparada",
                    labels,
                    index=index_pre,
                    key="thu_i6_preparada",
                )
                preparada = mapa_preparadas.get(label_preparada)

        _ctx_social = (
            thu_social_chave_campanha(preparada)
            if preparada
            else "manual"
        )

        nomes_catalogo = [
            str(p.get("Nome") or "").strip()
            for p in catalogo
            if str(p.get("Nome") or "").strip()
        ]
        produto_default = str((preparada or {}).get("produto") or "")
        produto_opcoes = ["— Sem produto vinculado —"] + nomes_catalogo
        produto_index = (
            produto_opcoes.index(produto_default)
            if produto_default in produto_opcoes else 0
        )

        r1, r2, r3 = st.columns([1.3, 1.3, 1])
        canal = r1.selectbox(
            "Canal",
            THU_SOCIAL_CANAIS,
            key="thu_i6_canal",
        )
        data_pub = r2.date_input(
            "Data da publicação",
            value=hoje_local(),
            key="thu_i6_data",
        )
        _tipos_midia = ["Imagem", "Vídeo / Reel", "Sem arquivo"]
        _tipo_index = 1 if canal == "Instagram Reel" else 0
        tipo_midia = r3.selectbox(
            "Mídia",
            _tipos_midia,
            index=_tipo_index,
            key=f"thu_i6_tipo_midia_{_ctx_social}_{canal}",
        )

        produto_sel = st.selectbox(
            "Produto oficial do Catálogo",
            produto_opcoes,
            index=produto_index,
            key=f"thu_i6_produto_{_ctx_social}",
        )
        produto = "" if produto_sel == "— Sem produto vinculado —" else produto_sel

        campanha_default = _thu_normalizar_campanha((preparada or {}).get("campanha"))
        campanhas_opts = ["Sem campanha específica"] + [
            x for x in CAMPANHAS_PRODUTO_OPCOES
            if x != "Permanente / Todas as épocas"
        ]
        camp_index = (
            campanhas_opts.index(campanha_default)
            if campanha_default in campanhas_opts else 0
        )
        campanha_sel = st.selectbox(
            "Campanha / data relacionada",
            campanhas_opts,
            index=camp_index,
            key=f"thu_i6_campanha_{_ctx_social}",
        )
