        rs2.metric("Pedidos aprovados", indicadores_unificados_central["aprovadas_hoje"])
        rs3.metric("Entregas concluídas", indicadores_unificados_central["entregues_hoje"])
        rs4.metric("Minha fila", len(minha_fila_central))
